 transform="translate(89,430)"><rect rx="0" ry="0" x="-56.5" y="-20.5" width="113" height="41"></rect><g class="label" transform="translate(0,0)"><g transform="translate(-46.5,-10.5)"><foreignObject width="93" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">XML docs / md</div></foreignObject></g></g></g><g class="node xml" style="opacity: 1;" id="sch" transform="translate(252.5,264.25)"><rect rx="5" ry="5" x="-49" y="-20.5" width="98" height="41"></rect><g class="label" transform="translate(0,0)"><g transform="translate(-39,-10.5)"><foreignObject width="78" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">XML Schema</div></foreignObject></g></g></g><g class="node xml" style="opacity: 1;" id="xj" transform="translate(425.75,264.25)"><polygon points="74.25,0 148.5,-74.25 74.25,-148.5 0,-74.25" rx="5" ry="5" transform="translate(-74.25,74.25)"></polygon><g class="label" transform="translate(0,0)"><g transform="translate(-52,-10.5)"><foreignObject width="104" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">xml to json XSLT</div></foreignObject></g></g></g><g class="node json" style="opacity: 1;" id="jx" transform="translate(624.25,264.25)"><polygon points="74.25,0 148.5,-74.25 74.25,-148.5 0,-74.25" rx="5" ry="5" transform="translate(-74.25,74.25)"></polygon><g class="label" transform="translate(0,0)"><g transform="translate(-52,-10.5)"><foreignObject width="104" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">json to xml XSLT</div></foreignObject></g></g></g><g class="node json" style="opacity: 1;" id="jsch" transform="translate(800.5,264.25)"><rect rx="5" ry="5" x="-52" y="-20.5" width="104" height="41"></rect><g class="label" transform="translate(0,0)"><g transform="translate(-42,-10.5)"><foreignObject width="84" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">JSON Schema</div></foreignObject></g></g></g><g class="node html" style="opacity: 1;" id="jsondocsh" transform="translate(970,264.25)"><rect rx="0" ry="0" x="-67.5" y="-20.5" width="135" height="41"></rect><g class="label" transform="translate(0,0)"><g transform="translate(-57.5,-10.5)"><foreignObject width="115" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">JSON docs / HTML</div></foreignObject></g></g></g><g class="node md" style="opacity: 1;" id="jsondocmd" transform="translate(970,430)"><rect rx="0" ry="0" x="-87.5" y="-20.5" width="175" height="41"></rect><g class="label" transform="translate(0,0)"><g transform="translate(-77.5,-10.5)"><foreignObject width="155" height="21"><div xmlns="http://www.w3.org/1999/xhtml" style="display: inline-block; white-space: nowrap;">JSON-flavored docs / md</div></foreignObject></g></g></g></g></g></g></svg>METASCHEMA { font-family: Calibri, Verdana, sans-serif }
* { display: block }
pre { color: darkgrey }
tag { color: black; font-family: monospace; font-size: 80%; font-weight: bold }
METASCHEMA { }
title { }
import:before { content: 'import module ' oxy_urlChooser(edit, '@href', columns 60) }
define-assembly, define-field, define-flag { margin-top: 1ex; margin-bottom: 1ex; border: thin inset black; padding: 0.5em }
define-assembly:before, define-field:before, define-flag:before { content: oxy_name() oxy_textfield(edit, '@name', columns, 12) }
root-name:before { content: "Root name: " }
prop:before { content: 'property ' oxy_textfield(edit, '@name', columns, 25) oxy_textfield(edit, '@value', columns, 30) }
define-assembly[group-as]:before, define-field[group-as]:before, define-flag[group-as]:before { content: oxy_name() oxy_textfield(edit, '@name', columns, 12) } define-assembly *, define-field *, define-flag * { margin: 0em }
define-assembly > * { margin-top: 1em }
pre { padding: 0.5em; background-color: gainsboro }
define-assembly { }
define-field { }
define-flag { }
flag { }
formal-name { font-size: 120%; font-weight: bold; margin: 0.5em 0em }
description, remarks { max-width: 60em }
remarks { border-left: thin solid black; padding-left: 1em; margin-left: 1em } remarks p { margin-top: 1em }
example { }
prose { }
p { }
code { display: inline; font-family: monospace } q { display: inline; background-color: lemonchiffon } em, i { display: inline; font-style: italic } strong, b { display: inline; font-weight: bold }
example { background-color: lavender; white-space: pre; }
example *:before { content: '<' oxy_name() '>'; font-family: monospace; font-size: 80% } example *:after { content: '</' oxy_name() '>'; font-family: monospace; font-size: 80% }
model { padding-left: 0.5em; border-left: medium solid blue; font-size: 80%; padding-right: 2em }
model model { font-size: 100%; }
flag:before { content: oxy_name() ' ref: ' oxy_textfield(edit, '@ref', columns, 12) }
assembly:before, field:before { content: oxy_name() ' named ' oxy_textfield(edit, '@ref', columns, 12) }
group-as { margin-left: 2em }
group-as:before { content: 'group as ' oxy_textfield(edit, '@name', columns, 12) }
choice:before { content: 'a choice between' }
prose:before { font-weight: bold; content: 'prose' }
choice > * { margin-left: 2em }
a { display: inline; color: blue } a:before { content: oxy_urlChooser( edit, "@href", columns 42); }
/* CONSTRAINTS */
constraint > * { border: thin solid black; padding: 0.6em }
allowed-values:before { content: "Allowed values" ' level: ' oxy_combobox(edit, '@level', editable, false, values, "ERROR, WARNING" ) }
enum { margin-left: 2em; display: list-item; font-size: 90%; padding-left: 1em } enum:before { content: oxy_textfield(edit, '@value', columns, 24); }
index { } index:before { content: "Index: " ' name: ' oxy_textfield(edit, '@name', columns, 24) ' target: ' oxy_textfield(edit, '@target', columns, 52) ' level: ' oxy_combobox(edit, '@level', editable, false, values, "ERROR, WARNING" ); }
key-field { margin-left: 2em } key-field:before { content: "Key field " ' target: ' oxy_textfield(edit, '@target', columns, 52) ' level: ' oxy_combobox(edit, '@level', editable, false, values, "ERROR, WARNING" ); }
expect { } expect:before { content: "Expect " ' target: ' oxy_textfield(edit, '@target', columns, 52) ' test: ' oxy_textfield(edit, '@test', columns, 36) ' level: ' oxy_combobox(edit, '@level', editable, false, values, "ERROR, WARNING" ); }
index-has-key { }
index-has-key:before { content: "Index has key: " ' name: ' oxy_textfield(edit, '@name', columns, 24) ' target: ' oxy_textfield(edit, '@target', columns, 52) ' level: ' oxy_combobox(edit, '@level', editable, false, values, "ERROR, WARNING" ); }<?xml version="1.0" encoding="UTF-8"?> <xsl:stylesheet xmlns:xsl="http://www.w3.org/1999/XSL/Transform" xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns="http://www.w3.org/1999/xhtml" version="1.0" xmlns:m="http://csrc.nist.gov/ns/oscal/metaschema/1.0" exclude-result-prefixes="xs m">
<xsl:template match="/"> <html> <head> <xsl:call-template name="css"/> </head> <body> <xsl:apply-templates/> </body> </html> </xsl:template>
<xsl:template match="m:METASCHEMA"> <div class="METASCHEMA"> <xsl:apply-templates/> </div> </xsl:template>
<xsl:template match="m:METASCHEMA/m:schema-name"> <h2 class="title"> <xsl:apply-templates/> </h2> </xsl:template>
<xsl:template match="m:define-flag"> <div class="define-flag" id="{@name}"> <h3> <xsl:apply-templates select="m:formal-name" mode="inline"/>: <xsl:apply-templates select="@name"/> flag</h3>
<xsl:apply-templates/> </div> </xsl:template>
<xsl:template match="m:define-field"> <div class="define-field" id="{@name}"> <h3> <xsl:apply-templates select="m:formal-name" mode="inline"/>: <xsl:apply-templates select="@name"/> <xsl:text> field</xsl:text> <xsl:apply-templates select="@group-as"/> </h3>
<xsl:choose> <xsl:when test="@as='mixed'"><p>Supports inline encoding</p></xsl:when> <xsl:when test="@as='boolean'"><p>True whenever given (presence signifies Boolean value)</p></xsl:when> </xsl:choose> <xsl:apply-templates select="m:formal-name | m:description"/> <xsl:if test="m:flag"> <div class="model"> <p>The <xsl:apply-templates select="@name"/> field supports:</p> <ul> <xsl:apply-templates select="m:flag" mode="model"/> </ul> </div>
</xsl:if> <xsl:apply-templates select="m:remarks"/> <xsl:apply-templates select="m:example"/> </div> </xsl:template>
<xsl:template match="m:define-assembly"> <div class="define-assembly" id="{@name}"> <h3> <xsl:apply-templates select="m:formal-name" mode="inline"/>: <xsl:apply-templates select="@name"/> <xsl:text> assembly</xsl:text> <xsl:apply-templates select="@group-as"/> </h3> <xsl:apply-templates select="m:formal-name | m:description"/> <xsl:apply-templates select="m:model"/> <xsl:apply-templates select="m:remarks"/> <xsl:apply-templates select="m:example"/> </div> </xsl:template>
<xsl:template match="@name | @named"> <code class="name"><xsl:value-of select="."/></code> </xsl:template>
<xsl:template match="@group-as"> <xsl:text> (group as </xsl:text> <code> <xsl:value-of select="."/> </code>)<xsl:text/> </xsl:template>
<xsl:template match="@datatype"> <xsl:text> (datatype: </xsl:text> <code> <xsl:value-of select="."/> </code>)<xsl:text/> </xsl:template>
<xsl:template match="@address"> <xsl:text> (addressable by </xsl:text> <code> <xsl:value-of select="."/> </code>)<xsl:text/> </xsl:template>
<xsl:template match="@required"> <i> (required)</i> </xsl:template>
<xsl:template match="m:flag"/>
<xsl:template match="m:flag" mode="model"> <li> <xsl:text>Flag </xsl:text> <a href="#{@name}" class="name"> <xsl:apply-templates select="@name"/> </a> <xsl:apply-templates select="@datatype"/> <xsl:apply-templates select="@required"/> <xsl:if test="not(@required)"> (<i>optional</i>)</xsl:if> <xsl:apply-templates select="m:description" mode="model"/> <xsl:apply-templates select="m:remarks" mode="model"/> </li> </xsl:template>
<!-- Empty model elements (whether by accident or design) will be dropped. --> <xsl:template match="m:model[not(*)]" priority="3"/>
<xsl:template match="m:model"> <div class="model"> <p>The <xsl:apply-templates select="../@name"/> assembly has the following contents <xsl:if test="count(*) > 1"> (in order)</xsl:if>:</p> <ul> <xsl:apply-templates select="../m:flag" mode="model"/> <xsl:apply-templates/> </ul> </div> </xsl:template>
<xsl:template match="m:assembly | m:field"> <li> <xsl:text>A</xsl:text> <xsl:if test="not(translate(substring(@named,1,1),'AEIOUaeiuo',''))">n</xsl:if> <xsl:text> </xsl:text> <a class="name" href="#{@named}"><xsl:apply-templates select="@named"/></a> <xsl:value-of select="concat(' ',local-name(),' ')"/> <xsl:apply-templates select="." mode="cardinality"/>
<xsl:apply-templates select="m:description" mode="model"/> <xsl:apply-templates select="m:remarks" mode="model"/> </li> </xsl:template>
<xsl:template match="*" mode="cardinality"> (<i>zero or one</i>)</xsl:template>
<xsl:template match="*[@required='yes']" mode="cardinality"> (<i>one</i>)</xsl:template>
<xsl:template match="m:example"> <div class="example"> <xsl:apply-templates select="m:description"/> <pre class="xml"> <xsl:apply-templates select="*" mode="as-example"/> </pre> <xsl:apply-templates select="m:remarks"/> </div> </xsl:template>
<xsl:template match="m:*" mode="as-example"/>
<xsl:template match="*" mode="as-example"> <xsl:apply-templates select="." mode="serialize"/> </xsl:template>
<xsl:template match="m:code[. = /*/*/@name]"> <a href="#{.}" class="name"> <xsl:apply-templates/> </a> </xsl:template>
<xsl:template name="css"> <style type="text/css"> html, body { background-color: lightsteelblue }
pre { color: darkgrey } .tag { color: black; font-family: monospace; font-size: 80%; font-weight: bold }
.METASCHEMA { }
.title { }
.define-assembly, .define-field, .define-flag { margin-top: 1ex; margin-bottom: 1ex; border: thin inset black; padding: 0.5em }
.define-assembly *, .define-field *, .define-flag * { margin: 0em }
.define-assembly > div { margin-top: 1em }
pre { padding: 0.5em; background-color: gainsboro }
.define-assembly { }
.define-field { }
.define-flag { }
.flag { }
.formal-name { font-size: 120%; font-weight: bold; font-family: sans-serif; margin: 0.5em 0em }
.description { font-size: 90% }
.remarks { }
.remarks p { margin-top: 0.5em } // .remarks > p:first-child { margin-top: 0em }
.model { margin-top: 1em }
.field { }
.fields { }
.assembly { }
.assemblies { }
.choice { }
.example { margin-top: 1em }
.prose { }
.p { }
.code { display: inline; } .q { display: inline; } .em { display: inline; } .strong { display: inline; }
.name { color: midnightblue; background-color: lavender; font-family: monospace }
a { text-decoration:none } a:hover { text-decoration: underline }
</style> </xsl:template>
<xsl:template match="m:METASCHEMA/m:short-name"> <p>The short name (file identifier) for this schema shall be <i><xsl:apply-templates/></i>. It is used internally when an identifier is called for, and may appear in file names of schema artifacts.</p> </xsl:template>
<xsl:template match="m:description" mode="model"> <xsl:text>: </xsl:text> <xsl:apply-templates/> </xsl:template>
<xsl:template match="m:remarks/m:p" mode="model"> <br class="br"/> <xsl:apply-templates/> </xsl:template>
<xsl:template match="m:choice"> <li class="choice">A choice between <ul> <xsl:apply-templates/> </ul> </li> </xsl:template>
<xsl:template match="m:prose"> <li class="prose">Prose contents (paragraphs and lists)</li> </xsl:template>
<xsl:template match="m:remarks"> <div class="remarks"> <xsl:apply-templates/> </div> </xsl:template>
<xsl:template match="m:formal-name"/>
<xsl:template match="m:formal-name" mode="inline"> <b class="formal-name"> <xsl:apply-templates/> </b> </xsl:template>
<xsl:template match="m:description"> <p class="description"> <xsl:apply-templates/> </p> </xsl:template>
<xsl:template match="m:p"> <p class="p"> <xsl:apply-templates/> </p> </xsl:template>
<xsl:template match="m:code"> <code> <xsl:apply-templates/> </code> </xsl:template>
<xsl:template match="m:q"> <q> <xsl:apply-templates/> </q> </xsl:template>
<xsl:template match="m:em | m:strong | m:b | m:i | m:u"> <xsl:element name="{local-name()}"> <xsl:apply-templates/> </xsl:element> </xsl:template>
<!-- temporary, until we work by passing the xml through the converter and showing that. :-) --> <xsl:template match="*" mode="serialize">
<xsl:call-template name="indent-for-pre"/>
<code class="tag">&lt;<xsl:value-of select="name(.)"/> <xsl:for-each select="@*"> <xsl:text> </xsl:text> <xsl:value-of select="name()"/> <xsl:text>="</xsl:text> <xsl:value-of select="."/> <xsl:text>"</xsl:text> </xsl:for-each> <xsl:text>&gt;</xsl:text> </code>
<xsl:apply-templates mode="serialize"> <xsl:with-param name="hot" select="boolean(text()[normalize-space(.)])"/> </xsl:apply-templates>
<xsl:if test="not(text()[normalize-space(.)])"> <xsl:call-template name="indent-for-pre"> <xsl:with-param name="endtag" select="true()"/> </xsl:call-template> </xsl:if> <code class="tag">&lt;/<xsl:value-of select="name(.)"/> <xsl:text>&gt;</xsl:text> </code> </xsl:template>
<xsl:template name="indent-for-pre"> <xsl:param name="endtag" select="false()"/> <!-- Pretty heavy duty doing this under XSLT 1.0 --> <xsl:variable name="inline" select="boolean(../text()[normalize-space(.)])"/> <xsl:variable name="all-ancestors" select="ancestor::*"/> <xsl:variable name="example-ancestors" select="ancestor::m:example/ancestor::*"/> <xsl:variable name="depth" select="count($all-ancestors) - count($example-ancestors)"/>
<xsl:if test="not($inline)"> <!-- No CR for the first one --> <xsl:if test="boolean(preceding-sibling::*) or not(parent::m:example) or $endtag"> <xsl:text>&#xA;</xsl:text> </xsl:if> <!-- check out the ancient method for a loop --> <xsl:for-each select="ancestor::*[position() &lt; $depth]"> <xsl:text> </xsl:text> </xsl:for-each> </xsl:if> </xsl:template>
<xsl:template match="text()" mode="serialize"> <xsl:param name="hot" select="boolean(../text()[normalize-space(.)])"/> <xsl:if test="$hot"> <xsl:value-of select="."/> </xsl:if> </xsl:template>
</xsl:stylesheet><?xml version="1.0" encoding="UTF-8"?> <METASCHEMA xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" abstract="yes"> <schema-name>OSCAL Assessment Layer Format -- Common Modules</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-assessment-common</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>This contains all modules common to the assessment plan, assessment results, and POAM models. </p> <p>The root of the OSCAL Assessment Plan format is <code>assessment-plan</code>.</p> <p>The root of the OSCAL Assessment Results format is <code>assessment-results</code>.</p> <p>The root of the OSCAL Plan of Action and Milestones (POA&amp;M) format is <code>plan-of-action-and-milestones</code>.</p> </remarks> <!-- IMPORT STATEMENTS --> <import href="oscal_control-common_metaschema.xml"/> <import href="oscal_implementation-common_metaschema.xml"/>
<!-- SSP Import --> <define-assembly name="import-ssp"> <formal-name>Import System Security Plan</formal-name> <description>Used by the assessment plan and POA&amp;M to import information about the system.</description> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>System Security Plan Reference</formal-name> <description>A resolvable URL reference to the system security plan for the system being assessed.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag>
<model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="local-objective"> <formal-name>Assessment-Specific Control Objective</formal-name> <description>A local definition of a control objective for this assessment. Uses catalog syntax for control objective and assessment actions.</description> <flag ref="control-id" required="yes"> <remarks> <p>The specified <code>control-id</code> must be a valid value within the baseline identified by the target system's SSP via the <code>import-profile</code> statement.</p> </remarks> </flag> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Objective Description</formal-name> <description>A human-readable description of this control objective.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="part" min-occurs="1" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY" /> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <allowed-values id="oscal-assessment-objective-types" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="objective" deprecated="1.0.1">**(deprecated)** Use 'assessment-objective' instead.</enum> <enum value="assessment" deprecated="1.0.1">**(deprecated)** Use 'assessment-method' instead.</enum> <enum value="assessment-objective">The part defines an assessment objective.</enum> <enum value="assessment-method">The part defines an assessment method.</enum> </allowed-values> <has-cardinality id="oscal-assessment-objective-cardinality" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('objective','assessment-objective')]" max-occurs="1" /> <has-cardinality id="oscal-assessment-method-cardinality" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/prop[has-oscal-namespace(('http://csrc.nist.gov/ns/oscal','http://csrc.nist.gov/ns/rmf')) and @name='method']" min-occurs="1" max-occurs="1" /> <has-cardinality id="oscal-assessment-objects-cardinality" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('objects','assessment-objects')]" min-occurs="1" max-occurs="1" /> <has-cardinality id="oscal-assessment-method-id-cardinality" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('objective','assessment-objective')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='method-id']" min-occurs="1" /> </constraint> </define-assembly> <define-assembly name="assessment-method"> <formal-name>Assessment Method</formal-name> <description>A local definition of a control objective. Uses catalog syntax for control objective and assessment activities.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Method Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this assessment method elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>assessment method</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Assessment Method Description</formal-name> <description>A human-readable description of this assessment method.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="assessment-part" min-occurs="1" max-occurs="1"/> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="activity"> <formal-name>Activity</formal-name> <description>Identifies an assessment or related process that can be performed. In the assessment plan, this is an intended activity which may be associated with an assessment task. In the assessment results, this an activity that was actually performed as part of an assessment.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Activity Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this assessment activity elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>activity</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Included Activity Title</formal-name> <description>The title for this included activity.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Included Activity Description</formal-name> <description>A human-readable description of this included activity.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="step" min-occurs="0" max-occurs="unbounded"> <formal-name>Step</formal-name> <description>Identifies an individual step in a series of steps related to an activity, such as an assessment test or examination procedure.</description> <group-as name="steps" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Step Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this step elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>step</code> (in a series of steps) can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Step Title</formal-name> <description>The title for this step.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Step Description</formal-name> <description>A human-readable description of this step.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="reviewed-controls"> <remarks> <p>This can be optionally used to define the set of controls and control objectives that are assessed by this step.</p> </remarks> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> <remarks> <p>Identifies the roles, and optionally the parties, associated with this step that is part of an assessment activity.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <is-unique id="oscal-unique-step-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since multiple <code>party-uuid</code> entries can be provided, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <assembly ref="reviewed-controls"> <use-name>related-controls</use-name> <remarks> <p>This can be optionally used to define the set of controls and control objectives that are assessed or remediated by this activity.</p> </remarks> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <!-- TODO: Dave to double-check constraints here --> <allowed-values id="oscal-activity-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="method">The assessment method to use. This typically appears on parts with the name "assessment".</enum> </allowed-values> <has-cardinality id="oscal-activity-type-cardinality" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='method']" min-occurs="1"/> <allowed-values id="oscal-activity-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='method']/@value"> <enum value="INTERVIEW">The process of holding discussions with individuals or groups of individuals within an organization to once again, facilitate assessor understanding, achieve clarification, or obtain evidence.</enum> <enum value="EXAMINE">The process of reviewing, inspecting, observing, studying, or analyzing one or more assessment objects (i.e., specifications, mechanisms, or activities).</enum> <enum value="TEST">The process of exercising one or more assessment objects (i.e., activities or mechanisms) under specified conditions to compare actual with expected behavior.</enum> </allowed-values> <is-unique id="oscal-unique-activity-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly>
<define-assembly name="task"> <formal-name>Task</formal-name> <description>Represents a scheduled event or milestone, which may be associated with a series of assessment actions.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Task Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this task elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>task</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <define-flag name="type" required="yes" as-type="token"> <formal-name>Task Type</formal-name> <description>The type of task.</description> <constraint> <allowed-values id="oscal-task-values" allow-other="yes"> <enum value="milestone">The task represents a planned milestone.</enum> <enum value="action">The task represents a specific assessment action to be performed.</enum> </allowed-values> </constraint> </define-flag>
<model> <define-field name="title" min-occurs="1" as-type="markup-line"> <formal-name>Task Title</formal-name> <description>The title for this task.</description> </define-field> <define-field name="description" max-occurs="1" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Task Description</formal-name> <description>A human-readable description of this task.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="timing"> <formal-name>Event Timing</formal-name> <description>The timing under which the task is intended to occur.</description> <model> <choice> <define-assembly name="on-date" min-occurs="1"> <formal-name>On Date Condition</formal-name> <description>The task is intended to occur on the specified date.</description> <define-flag name="date" as-type="date-time-with-timezone" required="yes"> <formal-name>On Date Condition</formal-name> <description>The task must occur on the specified date.</description> </define-flag> <model> <!-- Without a model the flags do not get converted in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <define-assembly name="within-date-range" min-occurs="1"> <formal-name>On Date Range Condition</formal-name> <description>The task is intended to occur within the specified date range.</description> <define-flag name="start" as-type="date-time-with-timezone" required="yes"> <formal-name>Start Date Condition</formal-name> <description>The task must occur on or after the specified date.</description> </define-flag> <define-flag name="end" as-type="date-time-with-timezone" required="yes"> <formal-name>End Date Condition</formal-name> <description>The task must occur on or before the specified date.</description> </define-flag> <model> <!-- Without a model the flags do not get converted in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <define-assembly name="at-frequency" min-occurs="1"> <formal-name>Frequency Condition</formal-name> <description>The task is intended to occur at the specified frequency.</description> <define-flag name="period" as-type="positive-integer" required="yes"> <formal-name>Period</formal-name> <description>The task must occur after the specified period has elapsed.</description> </define-flag> <define-flag name="unit" as-type="string" required="yes"> <formal-name>Time Unit</formal-name> <description>The unit of time for the period.</description> <constraint> <allowed-values id="oscal-timing-unit-values"> <enum value="seconds">The period is specified in seconds.</enum> <enum value="minutes">The period is specified in minutes.</enum> <enum value="hours">The period is specified in hours.</enum> <enum value="days">The period is specified in days.</enum> <enum value="months">The period is specified in calendar months.</enum> <enum value="years">The period is specified in calendar years.</enum> </allowed-values> </constraint> </define-flag> <model> <!-- Without a model the flags do not get converted in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> </choice> </model> </define-assembly> <define-assembly name="dependency" max-occurs="unbounded"> <formal-name>Task Dependency</formal-name> <description>Used to indicate that a task is dependent on another task.</description> <group-as name="dependencies" in-json="ARRAY"/> <define-flag name="task-uuid" required="yes" as-type="uuid"> <formal-name>Task Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a unique task.</description> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <assembly ref="task" min-occurs="0" max-occurs="unbounded"> <group-as name="tasks" in-json="ARRAY"/> </assembly>
<define-assembly name="associated-activity" min-occurs="0" max-occurs="unbounded"> <formal-name>Associated Activity</formal-name> <description>Identifies an individual activity to be performed as part of a task.</description> <group-as name="associated-activities" in-json="ARRAY"/> <define-flag name="activity-uuid" required="yes" as-type="uuid"> <formal-name>Activity Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to an activity defined in the list of activities.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> <remarks> <p>Identifies the person or organization responsible for performing a specific role defined by the activity.</p> </remarks> </assembly> <!-- <choice> --> <assembly ref="assessment-subject" min-occurs="1" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> </assembly> <!-- <assembly ref="assessment-subject-placeholder"> <use-name>subject-placeholder</use-name> </assembly> </choice> --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <is-unique id="oscal-unique-associated-activity-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <assembly ref="assessment-subject" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>The assessment subjects that the activity was performed against.</p> </remarks> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> <remarks> <p>Identifies the person or organization responsible for performing a specific role related to the task.</p> <!-- todo: role id and party id scope is defined at the document level. Refer to root object within which the data is declared for...mention resolved through imports. Note: wh--> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- ********** OBJECTIVES Assembly ********** --> <define-assembly name="reviewed-controls"> <formal-name>Reviewed Controls and Control Objectives</formal-name> <description>Identifies the controls being assessed and their control objectives.</description> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Control Objective Description</formal-name> <description>A human-readable description of control objectives.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly>
<define-assembly name="control-selection" min-occurs="1" max-occurs="unbounded"> <formal-name>Assessed Controls</formal-name> <description>Identifies the controls being assessed. In the assessment plan, these are the planned controls. In the assessment results, these are the actual controls, and reflects any changes from the plan.</description> <group-as name="control-selections" in-json="ARRAY"/> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Assessed Controls Description</formal-name> <description>A human-readable description of in-scope controls specified for assessment.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <choice> <assembly ref="include-all" min-occurs="1"/> <assembly ref="select-control-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>include-control</use-name> <group-as name="include-controls" in-json="ARRAY"/> <remarks> <p>Used to select a control for inclusion by the control's identifier. Specific control statements can be selected by their statement identifier.</p> </remarks> </assembly> </choice> <assembly ref="select-control-by-id" max-occurs="unbounded"> <use-name>exclude-control</use-name> <group-as name="exclude-controls" in-json="ARRAY"/> <remarks> <p>Used to select a control for exclusion by the control's identifier. Specific control statements can be excluded by their statement identifier.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>The <code>include-all</code>, specifies all control identified in the <strong>baseline</strong> are included in the scope if this assessment, as specified by the <code>include-profile</code> statement within the linked SSP.</p> <p>Any control specified within <code>exclude-controls</code> must first be within a range of explicitly included controls, via <code>include-controls</code> or <code>include-all</code>.</p> </remarks> </define-assembly>
<define-assembly name="control-objective-selection" min-occurs="0" max-occurs="unbounded"> <formal-name>Referenced Control Objectives</formal-name> <description>Identifies the control objectives of the assessment. In the assessment plan, these are the planned objectives. In the assessment results, these are the assessed objectives, and reflects any changes from the plan.</description> <group-as name="control-objective-selections" in-json="ARRAY"/> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Control Objectives Description</formal-name> <description>A human-readable description of this collection of control objectives.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <choice> <assembly ref="include-all" min-occurs="1"/> <assembly ref="select-objective-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>include-objective</use-name> <group-as name="include-objectives" in-json="ARRAY"/> <remarks> <p>Used to select a control objective for inclusion by the control objective's identifier.</p> </remarks> </assembly> </choice> <assembly ref="select-objective-by-id" max-occurs="unbounded"> <use-name>exclude-objective</use-name> <group-as name="exclude-objectives" in-json="ARRAY"/> <remarks> <p>Used to select a control objective for exclusion by the control objective's identifier.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>The <code>include-all</code> field, specifies all control objectives for any in-scope control. In-scope controls are defined in the <code>control-selection</code>.</p> <p>Any control objective specified within <code>exclude-controls</code> must first be within a range of explicitly included control objectives, via <code>include-objectives</code> or <code>include-all</code>.</p> </remarks> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>In the context of an assessment plan, this construct is used to identify the controls and control objectives that are to be assessed. In the context of an assessment result, this construct is used to identify the actual controls and objectives that were assessed, reflecting any changes from the plan.</p> <p>When resolving the selection of controls and control objectives, the following processing will occur:</p> <p>1. Controls will be resolved by creating a set of controls based on the control-selections by first handling the includes, and then removing any excluded controls.</p> <p>2. The set of control objectives will be resolved from the set of controls that was generated in the previous step. The set of control objectives is based on the control-objective-selection by first handling the includes, and then removing any excluded control objectives.</p> </remarks> </define-assembly>
<define-assembly name="select-control-by-id" scope="local"> <formal-name>Select Control</formal-name> <description>Used to select a control for inclusion/exclusion based on one or more control identifiers. A set of statement identifiers can be used to target the inclusion/exclusion to only specific control statements providing more granularity over the specific statements that are within the assessment scope.</description> <flag ref="control-id" required="yes"/> <model> <define-field name="statement-id" as-type="token" min-occurs="0" max-occurs="unbounded" > <formal-name>Include Specific Statements</formal-name> <description>Used to constrain the selection to only specificity identified statements.</description> <group-as name="statement-ids" in-json="ARRAY"/> </define-field> </model> </define-assembly>
<define-assembly name="select-objective-by-id"> <formal-name>Select Objective</formal-name> <description>Used to select a control objective for inclusion/exclusion based on the control objective's identifier.</description> <flag ref="objective-id" required="yes"/> <model> <!-- Without a model the flags do not get generated properly --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- ********** ASSESSMENT SUBJECT Assembly ********** --> <define-assembly name="assessment-subject-placeholder"> <formal-name>Assessment Subject Placeholder</formal-name> <description>Used when the assessment subjects will be determined as part of one or more other assessment activities. These assessment subjects will be recorded in the assessment results in the assessment log.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Subject Placeholder Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier for a set of assessment subjects that will be identified by a task or an activity that is part of a task. The locally defined <em>UUID</em> of the <code>assessment subject placeholder</code> can be used to reference the data item locally or globally (e.g., in an <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">imported OSCAL instance</a>). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Assessment Subject Placeholder Description</formal-name> <description>A human-readable description of intent of this assessment subject placeholder.</description> </define-field> <define-assembly name="source" min-occurs="1" max-occurs="unbounded"> <formal-name>Assessment Subject Source</formal-name> <description>Assessment subjects will be identified while conducting the referenced activity-instance.</description> <group-as name="sources" in-json="ARRAY"/> <define-flag name="task-uuid" required="yes" as-type="uuid"> <formal-name>Task Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference (in this or other OSCAL instances) an assessment activity to be performed as part of the event. The locally defined <em>UUID</em> of the <code>task</code> can be used to reference the data item locally or globally (e.g., in an <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">imported OSCAL instance</a>). This UUID should be assigned <em>per-subject</em>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <!-- Without a model the flags do not get generated properly --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="assessment-subject"> <formal-name>Subject of Assessment</formal-name> <description>Identifies system elements being assessed, such as components, inventory items, and locations. In the assessment plan, this identifies a planned assessment subject. In the assessment results this is an actual assessment subject, and reflects any changes from the plan. exactly what will be the focus of this assessment. Any subjects not identified in this way are out-of-scope.</description> <define-flag name="type" as-type="token" required="yes"> <formal-name>Subject Type</formal-name> <description>Indicates the type of assessment subject, such as a component, inventory, item, location, or party represented by this selection statement.</description> <!-- REVIEW THIS --> <constraint> <allowed-values id="oscal-assessment-subject-values" allow-other="yes"> <enum value="component">The referenced assessment subject is a component defined in the SSP, or in the <code>local-definitions</code> of an Assessment Plan or Assessment Results.</enum> <enum value="inventory-item">The referenced assessment subject is a inventory item defined in the SSP, or in the <code>local-definitions</code> of an Assessment Plan or Assessment Results.</enum> <enum value="location">The referenced assessment subject is a <code>location</code> defined in the <code>metadata</code> of the SSP, Assessment Plan, or Assessment Results.</enum> <enum value="party">The referenced assessment subject is a person or team to interview, who is defined as a <code>party</code> in the <code>metadata</code> of the SSP, Assessment Plan, or Assessment Results.</enum> <enum value="user">The referenced assessment subject is a <code>user</code> defined in the SSP, or in the <code>local-definitions</code> of an Assessment Plan or Assessment Results.</enum> </allowed-values> </constraint> </define-flag> <model> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Include Subjects Description</formal-name> <description>A human-readable description of the collection of subjects being included in this assessment.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <choice> <assembly ref="include-all" min-occurs="1"/> <assembly ref="select-subject-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>include-subject</use-name> <group-as name="include-subjects" in-json="ARRAY"/> </assembly> </choice> <assembly ref="select-subject-by-id" min-occurs="0" max-occurs="unbounded"> <use-name>exclude-subject</use-name> <group-as name="exclude-subjects" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>Processing of an include/exclude pair starts with processing the include, then removing matching entries in the exclude.</p> </remarks> </define-assembly>
<define-assembly name="select-subject-by-id"> <formal-name>Select Assessment Subject</formal-name> <description>Identifies a set of assessment subjects to include/exclude by UUID.</description> <flag ref="subject-uuid" required="yes"/> <flag ref="subject-type" required="yes"> <use-name>type</use-name> </flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-flag name="subject-uuid" as-type="uuid" scope="local"> <formal-name>Subject Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a component, inventory-item, location, party, user, or resource using it's UUID.</description> </define-flag>
<define-flag name="subject-type" as-type="token" scope="local"> <formal-name>Subject Universally Unique Identifier Reference Type</formal-name> <description>Used to indicate the type of object pointed to by the <code>uuid-ref</code> within a subject.</description> <constraint> <!-- REVIEW THIS --> <allowed-values id="oscal-assessment-subject-type-values" allow-other="yes"> <enum value="component">Component</enum> <enum value="inventory-item">Inventory Item</enum> <enum value="location">Location</enum> <enum value="party">Interview Party</enum> <enum value="user">User</enum> <enum value="resource">Resource or Artifact</enum> </allowed-values> </constraint> </define-flag>
<define-assembly name="subject-reference" scope="local"> <formal-name>Identifies the Subject</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a> identifier reference to a resource. Use type to indicate whether the identified resource is a component, inventory item, location, user, or something else.</description> <flag ref="subject-uuid" required="yes"/> <flag ref="subject-type" required="yes"> <use-name>type</use-name> </flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <!-- QUESTION: Is this needed, since the title from the target can be used? --> <formal-name>Subject Reference Title</formal-name> <description>The title or name for the referenced subject.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>The subject reference UUID could point to an item defined in the SSP, AP, or AR.</p> <p>Tools should check look for the ID in every file imported directly or indirectly.</p> </remarks> </define-assembly>
<!-- ********** ASSET Assembly ********** --> <define-assembly name="assessment-assets"> <formal-name>Assessment Assets</formal-name> <description>Identifies the assets used to perform this assessment, such as the assessment team, scanning tools, and assumptions.</description> <model> <assembly ref="system-component" min-occurs="0" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> <remarks> <p>Used to add any components for tools used during the assessment. These are represented here to avoid mixing with system components.</p> <p>The technology tools used by the assessor to perform the assessment, such as vulnerability scanners. In the assessment plan these are the intended tools. In the assessment results, these are the actual tools used, including any differences from the assessment plan.</p> </remarks> </assembly> <define-assembly name="assessment-platform" min-occurs="1" max-occurs="unbounded"> <formal-name>Assessment Platform</formal-name> <description>Used to represent the toolset used to perform aspects of the assessment.</description> <group-as name="assessment-platforms" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Platform Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this assessment platform elsewhere in this or other OSCAL instances. The locally defined <em>UUID</em> of the <code>assessment platform</code> can be used to reference the data item locally or globally (e.g., in an <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">imported OSCAL instance</a>). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" max-occurs="1" as-type="markup-line"> <formal-name>Assessment Platform Title</formal-name> <description>The title or name for the assessment platform.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="uses-component" min-occurs="0" max-occurs="unbounded"> <formal-name>Uses Component</formal-name> <description>The set of components that are used by the assessment platform.</description> <group-as name="uses-components" in-json="ARRAY"/> <define-flag required="yes" name="component-uuid" as-type="uuid"> <formal-name>Component Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a component that is implemented as part of an inventory item.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-ssp-uses-component-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly> </model> <constraint> <is-unique id="oscal-unique-ssp-assessment-assets-component" target="component"> <key-field target="@uuid"/> <remarks> <p>Since multiple assessment <code>component</code> entries can be provided, each component must have a unique <code>uuid</code>.</p> </remarks> </is-unique> </constraint> </define-assembly>
<!-- ********** Assemblies used within RESULTS and POA&M Items ********** --> <define-assembly name="finding-target"> <formal-name>Objective Status</formal-name> <description>Captures an assessor's conclusions regarding the degree to which an objective is satisfied.</description> <define-flag name="type" as-type="string" required="yes"> <formal-name>Finding Target Type</formal-name> <description>Identifies the type of the target.</description> <constraint> <allowed-values id="oscal-finding-target-values"> <enum value="statement-id">A reference to a control statement identifier within a control.</enum> <enum value="objective-id">A reference to a control objective identifier within a control.</enum> </allowed-values> </constraint> <remarks> <p>The target will always be a reference to: 1) a control statement, or 2) a control objective. In the former case, there is always a single top-level statement within a control. Thus, if the entire control is targeted, this statement identifier can be used.</p> </remarks> </define-flag> <define-flag name="target-id" as-type="token" required="yes"> <formal-name>Finding Target Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference for a specific target qualified by the <code>type</code>.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Objective Status Title</formal-name> <description>The title for this objective status.</description> </define-field> <define-field name="description" min-occurs="0" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Objective Status Description</formal-name> <description>A human-readable description of the assessor's conclusions regarding the degree to which an objective is satisfied.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="status" min-occurs="1"> <formal-name>Objective Status</formal-name> <description>A determination of if the objective is satisfied or not within a given system.</description> <define-flag name="state" as-type="token" required="yes"> <formal-name>Objective Status State</formal-name> <description>An indication as to whether the objective is satisfied or not.</description> <constraint> <allowed-values id="oscal-finding-target-status-state-values"> <enum value="satisfied">The objective has been completely satisfied.</enum> <enum value="not-satisfied">The objective has not been completely satisfied, but may be partially satisfied.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="reason" as-type="token"> <formal-name>Objective Status Reason</formal-name> <description>The reason the objective was given it's status.</description> <constraint> <allowed-values id="oscal-finding-target-reason-values" allow-other="yes"> <enum value="pass">The target system or system component satisfied all the conditions.</enum> <enum value="fail">The target system or system component did not satisfy all the conditions.</enum> <enum value="other">Some other event took place that is not a pass or a fail.</enum> </allowed-values> </constraint> <remarks> <p>Reason may contain any value, and should be used to communicate additional information regarding the status.</p> </remarks> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <assembly ref="implementation-status"> <remarks> <p>The <code>implementation-status</code> is used to qualify the <code>status</code> value to indicate the degree to which the control was found to be implemented.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="finding"> <formal-name>Finding</formal-name> <description>Describes an individual finding.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Finding Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this finding in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ar-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>finding</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="1" as-type="markup-line"> <formal-name>Finding Title</formal-name> <description>The title for this finding.</description> </define-field> <!-- CHANGE: Added WITH_WRAPPER to description --> <define-field name="description" min-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Finding Description</formal-name> <description>A human-readable description of this finding.</description> </define-field>
<assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly>
<assembly ref="origin" max-occurs="unbounded"> <group-as name="origins" in-json="ARRAY"/> <remarks> <p>Used to identify the individual and/or tool generated this finding.</p> </remarks> </assembly> <assembly ref="finding-target" min-occurs="1"> <use-name>target</use-name> </assembly> <define-field name="implementation-statement-uuid" as-type="uuid" min-occurs="0" max-occurs="1"> <formal-name>Implementation Statement UUID</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to the implementation statement in the SSP to which this finding is related.</description> </define-field> <!-- CHANGED: replaced embedded observation with references --> <assembly ref="related-observation" max-occurs="unbounded"> <group-as name="related-observations" in-json="ARRAY"/> </assembly> <!-- CHANGED: replaced "risk" with new "associated-risk" --> <assembly ref="associated-risk" max-occurs="unbounded"> <group-as name="related-risks" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="related-observation"> <formal-name>Related Observation</formal-name> <description>Relates the identified element to a set of referenced observations that were used to support its determination.</description> <define-flag name="observation-uuid" as-type="uuid" required="yes"> <formal-name>Observation Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to an observation defined in the list of observations.</description> </define-flag> <model> <!-- Without a model the flags do not get generated properly --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="associated-risk"> <formal-name>Associated Risk</formal-name> <description>Relates the finding to a set of referenced risks that were used to determine the finding.</description> <define-flag name="risk-uuid" as-type="uuid" required="yes"> <formal-name>Risk Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a risk defined in the list of risks.</description> </define-flag> <model> <!-- Without a model the flags do not get converted in JSON schemas--> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="observation"> <formal-name>Observation</formal-name> <description>Describes an individual observation.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Observation Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <em>cross-instance</em> scope that can be used to reference this observation elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>observation</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Observation Title</formal-name> <description>The title for this observation.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Observation Description</formal-name> <description>A human-readable description of this assessment observation.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-field name="method" min-occurs="1" max-occurs="unbounded"> <formal-name>Observation Method</formal-name> <description>Identifies how the observation was made.</description> <group-as name="methods" in-json="ARRAY"/> <constraint> <allowed-values id="oscal-observation-method-type-values" target="." allow-other="yes"> <enum value="EXAMINE">An inspection was performed.</enum> <enum value="INTERVIEW">An interview was performed.</enum> <enum value="TEST">A manual or automated test was performed.</enum> <enum value="UNKNOWN">This is only for use when converting historic content to OSCAL, where the conversion process cannot initially identify the appropriate method(s).</enum> </allowed-values> </constraint> </define-field>
<define-field name="type" as-type="token" max-occurs="unbounded"> <formal-name>Observation Type</formal-name> <description>Identifies the nature of the observation. More than one may be used to further qualify and enable filtering.</description> <group-as name="types" in-json="ARRAY"/> <constraint> <allowed-values id="oscal-observation-values" target="." allow-other="yes"> <enum value="ssp-statement-issue">A difference between the SSP implementation statement, and actual implementation.</enum> <enum value="control-objective">An observation about the status of a the associated control objective.</enum> <enum value="mitigation">A mitigating factor was identified.</enum> <enum value="finding" deprecated="1.1.4">**(deprecated)** Use 'discovery' instead.</enum> <enum value="discovery">An observation of potential risk in the system's implementation, identified through security scanning tools, penetration testing, and other means.</enum> <enum value="historic">An observation from a past assessment, which was converted to OSCAL at a later date.</enum> </allowed-values> </constraint> </define-field> <assembly ref="origin" max-occurs="unbounded"> <group-as name="origins" in-json="ARRAY"/> <remarks> <p>Used to identify the individual and/or tool that gathered the evidence resulting in the observation identification.</p> </remarks> </assembly> <assembly ref="subject-reference" min-occurs="0" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>Identifies who was interviewed, or what was tested or inspected.</p> </remarks> </assembly>
<define-assembly name="relevant-evidence" max-occurs="unbounded"> <formal-name>Relevant Evidence</formal-name> <description>Links this observation to relevant evidence.</description> <group-as name="relevant-evidence" in-json="ARRAY"/> <define-flag name="href" as-type="uri-reference"> <formal-name>Relevant Evidence Reference</formal-name> <description>A resolvable URL reference to relevant evidence.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Relevant Evidence Description</formal-name> <description>A human-readable description of this evidence.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <define-field name="collected" as-type="date-time-with-timezone" min-occurs="1" max-occurs="1"> <formal-name>Collected Field</formal-name> <description>Date/time stamp identifying when the finding information was collected.</description> </define-field> <define-field name="expires" as-type="date-time-with-timezone" min-occurs="0" max-occurs="1"> <formal-name>Expires Field</formal-name> <description>Date/time identifying when the finding information is out-of-date and no longer valid. Typically used with continuous assessment scenarios.</description> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <!-- <constraint> <!-\- TODO: review these and figure out where these go -\-> <allowed-values target="origin/@type" allow-other="no"> <!-\\- CHANGED: "tool" to "******" -\\-> <enum value="tool">An assessment tool, defined in the assets section of the assessment plan or results.</enum> <enum value="test-method">A test method defined in the assessment-activities section of the assessment plan or results.</enum> <enum value="task">A task defined in the schedule of the assessment plan or results.</enum> <enum value="included-activity">An assessment activity defined in the assessment-activities section of the assessment plan or results.</enum> <enum value="other">The UUID points elsewhere in the this file or an imported file.</enum> </allowed-values> </constraint> --> </define-assembly>
<define-assembly name="origin"> <formal-name>Origin</formal-name> <description>Identifies the source of the finding, such as a tool, interviewed person, or activity.</description> <model> <assembly ref="origin-actor" min-occurs="1" max-occurs="unbounded"> <use-name>actor</use-name> <group-as name="actors" in-json="ARRAY"/> </assembly> <assembly ref="related-task" max-occurs="unbounded"> <group-as name="related-tasks" in-json="ARRAY"/> </assembly> </model> </define-assembly>
<define-assembly name="origin-actor"> <formal-name>Originating Actor</formal-name> <description>The actor that produces an observation, a finding, or a risk. One or more actor type can be used to specify a person that is using a tool.</description> <define-flag name="type" as-type="token" required="yes"> <formal-name>Actor Type</formal-name> <description>The kind of actor.</description> <constraint> <allowed-values id="oscal-origin-actor-type-values"> <enum value="tool">A reference to a tool component defined with the assessment assets.</enum> <enum value="assessment-platform">A reference to an assessment-platform defined with the assessment assets.</enum> <enum value="party">A reference to a party defined within the document metadata.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="actor-uuid" as-type="uuid" required="yes"> <formal-name>Actor Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to the tool or person based on the associated type.</description> </define-flag> <define-flag name="role-id" as-type="token"> <formal-name>Actor Role</formal-name> <description>For a party, this can optionally be used to specify the role the actor was performing.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> </model> </define-assembly>
<define-assembly name="related-task"> <formal-name>Task Reference</formal-name> <description>Identifies an individual task for which the containing object is a consequence of.</description> <define-flag name="task-uuid" required="yes" as-type="uuid"> <formal-name>Task Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a unique task.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> <remarks> <p>Identifies the person or organization responsible for performing a specific role defined by the activity.</p> </remarks> </assembly> <assembly ref="assessment-subject" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>The assessment subjects that the task was performed against.</p> </remarks> </assembly> <define-assembly name="identified-subject"> <formal-name>Identified Subject</formal-name> <description>Used to detail assessment subjects that were identified by this task.</description>
<define-flag name="subject-placeholder-uuid" required="yes" as-type="uuid"> <formal-name>Assessment Subject Placeholder Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a unique assessment subject placeholder defined by this task.</description> </define-flag> <model> <assembly ref="assessment-subject" min-occurs="1" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>The assessment subjects that the task identified, which will be used by another task through a subject-placeholder reference. Such a task will "consume" these subjects.</p> </remarks> </assembly> </model> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <is-unique id="oscal-unique-ssp-related-task-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly>
<define-field name="threat-id" as-type="uri"> <!-- This is an id because it is an externally provided identifier --> <formal-name>Threat ID</formal-name> <description>A pointer, by ID, to an externally-defined threat.</description> <json-value-key>id</json-value-key> <define-flag name="system" as-type="uri" required="yes"> <formal-name>Threat Type Identification System</formal-name> <description>Specifies the source of the threat information.</description> <constraint> <allowed-values id="oscal-threat-id-system" allow-other="yes"> <enum value="http://fedramp.gov" deprecated="1.0.3">**deprecated** The value conforms to FedRAMP definitions. This value has been deprecated; use <code>http://fedramp.gov/ns/oscal</code> instead.</enum> <enum value="http://fedramp.gov/ns/oscal">The value conforms to FedRAMP definitions.</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> <define-flag name="href" as-type="uri-reference"> <!-- TODO: consider deprecating this in favor of a link --> <formal-name>Threat Information Resource Reference</formal-name> <description>An optional location for the threat data, from which this ID originates.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> </define-field>
<define-assembly name="risk"> <formal-name>Identified Risk</formal-name> <description>An identified risk.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Risk Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this risk elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>risk</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="1" max-occurs="1" as-type="markup-line"> <formal-name>Risk Title</formal-name> <description>The title for this risk.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Risk Description</formal-name> <description>A human-readable summary of the identified risk, to include a statement of how the risk impacts the system.</description> </define-field> <define-field name="statement" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <!-- QUESTION: how is this different from description? --> <!-- TODO: remove this --> <formal-name>Risk Statement</formal-name> <description>An summary of impact for how the risk affects the system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="risk-status" min-occurs="1"> <use-name>status</use-name> </field> <assembly ref="origin" max-occurs="unbounded"> <group-as name="origins" in-json="ARRAY"/> <remarks> <p>Used to identify the individual and/or tool that identified this risk.</p> </remarks> </assembly> <field ref="threat-id" min-occurs="0" max-occurs="unbounded"> <!-- QUESTION: Should this be moved to risk? --> <group-as name="threat-ids" in-json="ARRAY"/> </field>
<assembly ref="characterization" min-occurs="0" max-occurs="unbounded"> <group-as name="characterizations" in-json="ARRAY"/> </assembly> <define-assembly name="mitigating-factor" max-occurs="unbounded"> <formal-name>Mitigating Factor</formal-name> <description>Describes an existing mitigating factor that may affect the overall determination of the risk, with an optional link to an implementation statement in the SSP.</description> <group-as name="mitigating-factors" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Mitigating Factor Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this mitigating factor elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>mitigating factor</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <define-flag name="implementation-uuid" as-type="uuid"> <formal-name>Implementation UUID</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this implementation statement elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>s. The locally defined <em>UUID</em> of the <code>implementation statement</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Mitigating Factor Description</formal-name> <description>A human-readable description of this mitigating factor.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="subject-reference" min-occurs="0" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>Links identifiable elements of the system to this mitigating factor, such as an inventory-item or component.</p> </remarks> </assembly> </model> </define-assembly>
<define-field name="deadline" as-type="date-time-with-timezone"> <formal-name>Risk Resolution Deadline</formal-name> <description>The date/time by which the risk must be resolved.</description> </define-field>
<assembly ref="response" min-occurs="0" max-occurs="unbounded"> <group-as name="remediations" in-json="ARRAY"/> </assembly> <define-assembly name="risk-log"> <formal-name>Risk Log</formal-name> <description>A log of all risk-related tasks taken.</description> <model> <define-assembly name="entry" min-occurs="1" max-occurs="unbounded"> <formal-name>Risk Log Entry</formal-name> <description>Identifies an individual risk response that occurred as part of managing an identified risk.</description> <group-as name="entries" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Risk Log Entry Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this risk log entry elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>risk log entry</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Title</formal-name> <description>The title for this risk log entry.</description> </define-field> <define-field name="description" min-occurs="0" max-occurs="1" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Risk Task Description</formal-name> <description>A human-readable description of what was done regarding the risk.</description> </define-field> <define-field name="start" as-type="date-time-with-timezone" min-occurs="1" max-occurs="1"> <formal-name>Start</formal-name> <description>Identifies the start date and time of the event.</description> </define-field> <define-field name="end" as-type="date-time-with-timezone" max-occurs="1"> <formal-name>End</formal-name> <description>Identifies the end date and time of the event. If the event is a point in time, the start and end will be the same date and time.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="logged-by" max-occurs="unbounded"> <group-as name="logged-by" in-json="ARRAY"/> </assembly> <field ref="risk-status"> <use-name>status-change</use-name> <remarks> <p>Identifies a change in risk status made resulting from the task described by this risk log entry. This allows the risk's status history to be captured as a sequence of risk log entries.</p> </remarks> </field> <define-assembly name="related-response" max-occurs="unbounded"> <formal-name>Risk Response Reference</formal-name> <description>Identifies an individual risk response that this log entry is for.</description> <group-as name="related-responses" in-json="ARRAY"/> <define-flag name="response-uuid" required="yes" as-type="uuid"> <formal-name>Response Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a unique risk response.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="related-task" max-occurs="unbounded"> <group-as name="related-tasks" in-json="ARRAY"/> <remarks> <p>This is used to identify the task(s) that this log entry was generated for.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <allowed-values id="oscal-risk-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="type">The type of remediation tracking entry. Can be multi-valued.</enum> </allowed-values> <allowed-values id="oscal-risk-prop-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type']/@value" allow-other="yes"> <enum value="vendor-check-in">Contacted vendor to determine the status of a pending fix to a known vulnerability.</enum> <enum value="status-update">Information related to the current state of response to this risk.</enum> <enum value="milestone-complete">A significant step in the response plan has been achieved.</enum> <enum value="mitigation">An activity was completed that reduces the likelihood or impact of this risk.</enum> <enum value="remediated">An activity was completed that eliminates the likelihood or impact of this risk.</enum> <!-- QUESTION: Is this needed, since this is handled by the status field? --> <enum value="closed">The risk is no longer applicable to the system.</enum> <enum value="dr-submission">A deviation request was made to the authorizing official.</enum> <enum value="dr-updated">A previously submitted deviation request has been modified.</enum> <enum value="dr-approved">The authorizing official approved the deviation.</enum> <enum value="dr-rejected">The authorizing official rejected the deviation.</enum> </allowed-values> </constraint> </define-assembly> </model> </define-assembly>
<assembly ref="related-observation" max-occurs="unbounded"> <group-as name="related-observations" in-json="ARRAY"/> </assembly> </model> <constraint> <!-- REVIEW THIS --> <allowed-values id="oscal-risk-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="false-positive">The risk has been confirmed to be a false positive.</enum> <enum value="accepted">The risk has been accepted. No further action will be taken.</enum> <enum value="risk-adjusted">The risk has been adjusted.</enum> <enum value="priority">A numeric value indicating the sequence in which risks should be addressed. (Lower numbers are higher priority)</enum> </allowed-values> <matches id="oscal-risk-priority-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='priority']/@value" datatype="integer" /> </constraint> </define-assembly>
<define-assembly name="logged-by"> <formal-name>Logged By</formal-name> <description>Used to indicate who created a log entry in what role.</description> <define-flag name="party-uuid" as-type="uuid" required="yes"> <formal-name>Party UUID Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to the party who is making the log entry.</description> </define-flag> <define-flag name="role-id" as-type="token"> <formal-name>Actor Role</formal-name> <description>A point to the role-id of the role in which the party is making the log entry.</description> </define-flag> <model> <!-- Without a model the flags do not get generated in JSON schemas--> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-field name="risk-status" as-type="token"> <formal-name>Risk Status</formal-name> <description>Describes the status of the associated risk.</description> <constraint> <allowed-values id="oscal-risk-status-values" target="." allow-other="yes"> <enum value="open">The risk has been identified.</enum> <enum value="investigating">The identified risk is being investigated. (Open risk)</enum> <enum value="remediating">Remediation activities are underway, but are not yet complete. (Open risk)</enum> <enum value="deviation-requested">A risk deviation, such as false positive, risk reduction, or operational requirement has been submitted for approval. (Open risk)</enum> <enum value="deviation-approved">A risk deviation, such as false positive, risk reduction, or operational requirement has been approved. (Open risk)</enum> <enum value="closed">The risk has been resolved.</enum> </allowed-values> </constraint> </define-field>
<define-assembly name="characterization"> <formal-name>Characterization</formal-name> <description>A collection of descriptive data about the containing object from a specific origin.</description> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="origin" min-occurs="1"> <remarks> <p>metadata about the specific actor that generated this descriptive data.</p> </remarks> </assembly> <define-assembly name="facet" min-occurs="1" max-occurs="unbounded"> <formal-name>Facet</formal-name> <description>An individual characteristic that is part of a larger set produced by the same actor.</description> <group-as name="facets" in-json="ARRAY"/> <define-flag name="name" as-type="token" required="yes"> <formal-name>Facet Name</formal-name> <description>The name of the risk metric within the specified system.</description> </define-flag> <define-flag name="system" as-type="uri" required="yes"> <formal-name>Naming System</formal-name> <description>Specifies the naming system under which this risk metric is organized, which allows for the same names to be used in different systems controlled by different parties. This avoids the potential of a name clash.</description> <constraint> <allowed-values id="oscal-characterization-facet-name-system-values" allow-other="yes"><!-- Other values --> <enum value="http://fedramp.gov" deprecated="1.0.3">**deprecated** The FedRAMP naming system. This has been deprecated; use <code>http://fedramp.gov/ns/oscal</code> instead.</enum> <enum value="http://fedramp.gov/ns/oscal">The facet naming system defined by FedRAMP.</enum> <enum value="http://csrc.nist.gov/ns/oscal">The facet naming system defined by OSCAL.</enum> <enum value="http://csrc.nist.gov/ns/oscal/unknown">The facet is from an unknown taxonomy. The meaning of the name is tool or organization specific.</enum> <enum value="http://cve.mitre.org">The facet naming system defined by the CVE Program.</enum> <!-- To identify which CVSS values to use --> <enum value="http://www.first.org/cvss/v2.0">The facet naming system for representing Common Vulnerability Scoring System (CVSS) vectors as defined by the the <a href="https://www.first.org/">Forum for Incident Response and Security Teams</a> <a href="https://www.first.org/cvss/">CVSS Special Interest Group</a> (CVSS-SIG) for <a href="https://www.first.org/cvss/v2/">CVSS v2</a>.</enum> <enum value="http://www.first.org/cvss/v3.0">The facet naming system for representing Common Vulnerability Scoring System (CVSS) vectors as defined by the the <a href="https://www.first.org/">Forum for Incident Response and Security Teams</a> <a href="https://www.first.org/cvss/">CVSS Special Interest Group</a> (CVSS-SIG) for <a href="https://www.first.org/cvss/v3-0/">CVSS v3.0</a>.</enum> <enum value="http://www.first.org/cvss/v3.1">The facet naming system for representing Common Vulnerability Scoring System (CVSS) vectors as defined by the the <a href="https://www.first.org/">Forum for Incident Response and Security Teams</a> <a href="https://www.first.org/cvss/">CVSS Special Interest Group</a> (CVSS-SIG) for <a href="https://www.first.org/cvss/v3-1/">CVSS v3.1</a>.</enum> <enum value="https://www.first.org/cvss/v4-0">The facet naming system for representing Common Vulnerability Scoring System (CVSS) vectors as defined by the the <a href="https://www.first.org/">Forum for Incident Response and Security Teams</a> <a href="https://www.first.org/cvss/">CVSS Special Interest Group</a> (CVSS-SIG) for <a href="https://www.first.org/cvss/v4-0/">CVSS v4.0</a>.</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> <define-flag name="value" as-type="string" required="yes"> <formal-name>Facet Value</formal-name> <description>Indicates the value of the facet.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-facet-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="state">Indicates if the facet is 'initial' as first identified, or 'adjusted' indicating that the value has be changed after some adjustments have been made (e.g., to identify residual risk).</enum> </allowed-values> <allowed-values id="oscal-facet-prop-state-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='state']/@value"><!-- For values related to initial and residual (mitigated) risk --> <enum value="initial">As first identified.</enum> <enum value="adjusted">Indicates that residual risk remains after some adjustments have been made.</enum> </allowed-values> <!-- TODO: What about "vulnerability-id", "plugin-id"? Should this be added to FedRAMP? --> <allowed-values id="oscal-facet-name-core-values" target="(.)[@system='http://csrc.nist.gov/ns/oscal']/@name"> <enum value="likelihood">General likelihood rating.</enum> <enum value="impact">General impact rating.</enum> <enum value="risk">General risk rating.</enum> <enum value="severity">General severity rating.</enum> </allowed-values> <allowed-values id="oscal-facet-fedramp-values" target="(.)[@system=('http://fedramp.gov','http://fedramp.gov/ns/oscal')]/@name"> <enum value="likelihood">Likelihood as defined by FedRAMP. The <code>class</code> can be used to specify 'initial' and 'adjusted' risk states.</enum> <enum value="impact">Impact as defined by FedRAMP. The <code>class</code> can be used to specify 'initial' and 'adjusted' risk states.</enum> <enum value="risk">Risk as calculated according to FedRAMP. The <code>class</code> can be used to specify 'initial' and 'adjusted' risk states.</enum> </allowed-values> <allowed-values id="oscal-facet-cve-values" target="(.)[@system='http://cve.mitre.org']/@name"> <enum value="cve-id">An identifier managed by the CVE program (see <a>https://cve.mitre.org/</a>).</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-name-values" target="(.)[@system='http://www.first.org/cvss/v2.0']/@name"> <enum value="access-vector">Base: Access Vector</enum> <enum value="access-complexity">Base: Access Complexity</enum> <enum value="authentication">Base: Authentication</enum> <enum value="confidentiality-impact">Base: Confidentiality Impact</enum> <enum value="integrity-impact">Base: Integrity Impact</enum> <enum value="availability-impact">Base: Availability Impact</enum> <enum value="exploitability">Temporal: Exploitability</enum> <enum value="remediation-level">Temporal: Remediation Level</enum> <enum value="report-confidence">Temporal: Report Confidence</enum> <enum value="collateral-damage-potential">Environmental: Collateral Damage Potential</enum> <enum value="target-distribution">Environmental: Target Distribution</enum> <enum value="confidentiality-requirement">Environmental: Confidentiality Requirement</enum> <enum value="integrity-requirement">Environmental: Integrity Requirement</enum> <enum value="availability-requirement">Environmental: Availability Requirement</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-access-vector-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='access-vector']/@value"> <enum value="local">Local</enum> <enum value="adjacent-network">Network Adjacent</enum> <enum value="network">Network</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-access-complexity-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='access-complexity']/@value"> <enum value="high">High</enum> <enum value="medium">Medium</enum> <enum value="low">Low</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-authentication-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='authentication']/@value"> <enum value="multiple">Multiple</enum> <enum value="single">Single</enum> <enum value="none">None</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-confidentiality-impact-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name=('confidentiality-impact', 'integrity-impact', 'availability-impact')]/@value"> <enum value="none">None</enum> <enum value="partial">Partial</enum> <enum value="complete">Complete</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-exploitability-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='exploitability']/@value"> <enum value="unproven">Unproven</enum> <enum value="proof-of-concept">Proof-of-Concept</enum> <enum value="functional">Functional</enum> <enum value="high">High</enum> <enum value="not-defined">Not Defined</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-remediation-level-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='remediation-level']/@value"> <enum value="official-fix">Official Fix</enum> <enum value="temporary-fix">Temporary Fix</enum> <enum value="workaround">Workaround</enum> <enum value="unavailable">Unavailable</enum> <enum value="not-defined">Not Defined</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-report-confidence-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='report-confidence']/@value"> <enum value="unconfirmed">Unconfirmed</enum> <enum value="uncorroborated">Uncorroborated</enum> <enum value="confirmed">Confirmed</enum> <enum value="not-defined">Not Defined</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-collateral-damage-potential-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name='collateral-damage-potential']/@value"> <enum value="none">None</enum> <enum value="low">Low (light loss)</enum> <enum value="low-medium">Low Medium</enum> <enum value="medium-high">Medium High</enum> <enum value="high">High (catastrophic loss)</enum> <enum value="not-defined">Not Defined</enum> </allowed-values> <allowed-values id="oscal-facet-cvss2-cia-requirement-values" target="(.)[@system='http://www.first.org/cvss/v2.0' and @name=('target-distribution', 'confidentiality-requirement', 'integrity-requirement', 'availability-requirement')]/@value"> <enum value="none">None</enum> <enum value="low">Low</enum> <enum value="medium">Medium</enum> <enum value="high">High</enum> <enum value="not-defined">Not Defined</enum> </allowed-values>
<allowed-values id="oscal-facet-cvss3-name-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1')]/@name"> <enum value="attack-vector">Base: Attack Vector</enum> <enum value="access-complexity">Base: Attack Complexity</enum> <enum value="privileges-required">Base: Privileges Required</enum> <enum value="user-interaction">Base: User Interaction</enum> <enum value="scope">Base: Scope</enum> <enum value="confidentiality-impact">Base: Confidentiality Impact</enum> <enum value="integrity-impact">Base: Integrity Impact</enum> <enum value="availability-impact">Base: Availability Impact</enum> <enum value="exploit-code-maturity">Temporal: Exploit Code Maturity</enum> <enum value="remediation-level">Temporal: Remediation Level</enum> <enum value="report-confidence">Temporal: Report Confidence</enum> <enum value="modified-attack-vector">Environmental: Modified Attack Vector</enum> <enum value="modified-attack-complexity">Environmental: Modified Attack Complexity</enum> <enum value="modified-privileges-required">Environmental: Modified Privileges Required</enum> <enum value="modified-user-interaction">Environmental: Modified User Interaction</enum> <enum value="modified-scope">Environmental: Modified Scope</enum> <enum value="modified-confidentiality">Environmental: Modified Confidentiality</enum> <enum value="modified-integrity">Environmental: Modified Integrity</enum> <enum value="modified-availability">Environmental: Modified Availability</enum> <enum value="confidentiality-requirement">Environmental: Confidentiality Requirement Modifier</enum> <enum value="integrity-requirement">Environmental: Integrity Requirement Modifier</enum> <enum value="availability-requirement">Environmental: Availability Requirement Modifier</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-access-vector-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='access-vector']/@value"> <enum value="network">Network</enum> <enum value="adjacent">Adjacent</enum> <enum value="local">Local</enum> <enum value="physical">Physical</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-access-complexity-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='access-complexity']/@value"> <enum value="high">High</enum> <enum value="low">Low</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-cia-impact-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name=('privileges-required', 'confidentiality-impact', 'integrity-impact', 'availability-impact')]/@value"> <enum value="none">None</enum> <enum value="low">Low</enum> <enum value="high">High</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-user-interaction" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='user-interaction']/@value"> <enum value="none">None</enum> <enum value="required">Required</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-scope" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='scope']/@value"> <enum value="unchanged">Unchanged</enum> <enum value="changed">Changed</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-exploit-code-maturity-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='exploit-code-maturity']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="unproven">Unproven</enum> <enum value="proof-of-concept">Proof-of-Concept</enum> <enum value="functional">Functional</enum> <enum value="high">High</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-remediation-level" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='remediation-level']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="official-fix">Official Fix</enum> <enum value="temporary-fix">Temporary Fix</enum> <enum value="workaround">Workaround</enum> <enum value="unavailable">Unavailable</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-report-confidence-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='report-confidence']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="unknown">Unknown</enum> <enum value="reasonable">Reasonable</enum> <enum value="confirmed">Confirmed</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-cia-requirement-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name=('confidentiality-requirement', 'integrity-requirement', 'availability-requirement')]/@value"> <enum value="not-defined">Not Defined</enum> <enum value="low">Low</enum> <enum value="medium">Medium</enum> <enum value="high">High</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-modified-attack-vector-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='modified-attack-vector']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="network">Network</enum> <enum value="adjacent">Adjacent</enum> <enum value="local">Local</enum> <enum value="physical">Physical</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-modified-attack-complexity-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='modified-attack-complexity']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="high">High</enum> <enum value="low">Low</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-modified-cia-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name=('modified-privileges-required', 'modified-confidentiality', 'modified-integrity', 'modified-availability')]/@value"> <enum value="not-defined">Not Defined</enum> <enum value="none">None</enum> <enum value="low">Low</enum> <enum value="high">High</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-modified-user-interaction-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='modified-user-interaction']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="none">None</enum> <enum value="required">Required</enum> </allowed-values> <allowed-values id="oscal-facet-cvss3-modified-scope-values" target="(.)[@system=('http://www.first.org/cvss/v3.0', 'http://www.first.org/cvss/v3.1') and @name='modified-scope']/@value"> <enum value="not-defined">Not Defined</enum> <enum value="unchanged">Unchanged</enum> <enum value="changed">Changed</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-vectors" target="(.)[@system=('https://www.first.org/cvss/v4-0')]/@name"> <enum value="av">Base: Attack Vector</enum> <enum value="ac">Base: Attack Complexity</enum> <enum value="at">Base: Attack Requirements</enum> <enum value="pr">Base: Privileges Required</enum> <enum value="ui">Base: User Interaction</enum> <enum value="vc">Base: Vulnerable System Confidentiality Impact</enum> <enum value="vi">Base: Vulnerable System Integrity Impact</enum> <enum value="va">Base: Vulnerable System Availability Impact</enum> <enum value="sc">Base: Subsequent System Confidentiality Impact</enum> <enum value="si">Base: Vulnerable System Integrity Impact</enum> <enum value="sa">Base: Vulnerable System Availability Impact</enum> <enum value="s">Supplemental: Safety</enum> <enum value="au">Supplemental: Automatable</enum> <enum value="r">Supplemental: Recovery</enum> <enum value="v">Supplemental: Value Density</enum> <enum value="re">Supplemental: Vulnerability Response Effort</enum> <enum value="u">Supplemental: Provider Urgency</enum> <enum value="mav">Environmental: Modified Attack Vector</enum> <enum value="mac">Environmental: Modified Attack Complexity</enum> <enum value="mat">Environmental: Modified Attack Requirements</enum> <enum value="mpr">Environmental: Modified Privileges Required</enum> <enum value="mui">Environmental: Modified User Interaction</enum> <enum value="mvc">Environmental: Modified Vulnerable System Confidentiality</enum> <enum value="mvi">Environmental: Modified Vulnerable System Integrity</enum> <enum value="mva">Environmental: Modified Vulnerable System Availability</enum> <enum value="msc">Environmental: Subsequent Vulnerable System Confidentiality</enum> <enum value="msi">Environmental: Subsequent Vulnerable System Integrity</enum> <enum value="msa">Environmental: Subsequent Vulnerable System Availability</enum> <enum value="cr">Environmental: Confidentiality Requirements</enum> <enum value="ir">Environmental: Integrity Requirements</enum> <enum value="ar">Environmental: Availability Requirements</enum> <enum value="e">Threat: Exploit Maturity</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-av-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='av']/@value"> <formal-name>Attack Vector Values</formal-name> <enum value="n">Network</enum> <enum value="a">Adjacent</enum> <enum value="l">Local</enum> <enum value="p">Physical</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-ac-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='ac']/@value"> <formal-name>Attack Complexity Values</formal-name> <enum value="h">High</enum> <enum value="l">Low</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-at-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='at']/@value"> <formal-name>Attack Requirements Values</formal-name> <enum value="n">None</enum> <enum value="p">Present</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-pr-cia-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name=('pr','vc','vi','va','sc','si','sa')]/@value"> <formal-name>Privileges Required, Confidentiality, Integrity, and Availability Values</formal-name> <enum value="n">None</enum> <enum value="l">Low</enum> <enum value="h">High</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-ui-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='ui']/@value"> <formal-name>User Interaction Values</formal-name> <enum value="n">None</enum> <enum value="p">Passive</enum> <enum value="a">Active</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-s-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='s']/@value"> <formal-name>Safety Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">Negligible</enum> <enum value="p">Present</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-au-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='au']/@value"> <formal-name>Automatable Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">No</enum> <enum value="y">Yes</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-r-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='r']/@value"> <formal-name>Recovery Values</formal-name> <enum value="x">Not Defined</enum> <enum value="a">Automatic</enum> <enum value="u">User</enum> <enum value="i">Irrecoverable</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-v-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='v']/@value"> <formal-name>Value Density Values</formal-name> <enum value="x">Not Defined</enum> <enum value="a">Automatic</enum> <enum value="u">User</enum> <enum value="i">Irrecoverable</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-re-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='re']/@value"> <formal-name>Vulnerability Response Effort Values</formal-name> <enum value="x">Not Defined</enum> <enum value="l">Low</enum> <enum value="m">Moderate</enum> <enum value="h">High</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-u-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='u']/@value"> <formal-name>Provider Urgency Values</formal-name> <enum value="x">Not Defined</enum> <enum value="clear">Clear</enum> <enum value="green">Green</enum> <enum value="amber">Amber</enum> <enum value="red">Red</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-mav-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='mav']/@value"> <formal-name>Modified Attack Vector Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">Network</enum> <enum value="a">Adjacent</enum> <enum value="l">Local</enum> <enum value="p">Physical</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-mac-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='mac']/@value"> <formal-name>Modified Attack Complexity Values</formal-name> <enum value="x">Not Defined</enum> <enum value="h">High</enum> <enum value="l">Low</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-mat-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='mat']/@value"> <formal-name>Modified Attack Requirements Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">None</enum> <enum value="p">Present</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-mpr-mvs-cia-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name=('mpr','mvc','mvi')]/@value"> <formal-name>Modified Privileges Required, and Vulnerable System Confidentiality, Integrity, and Availability Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">None</enum> <enum value="l">Low</enum> <enum value="h">High</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-mui-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='mui']/@value"> <formal-name>Modified User Interaction Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">None</enum> <enum value="p">Passive</enum> <enum value="a">Active</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-msc-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='msc']/@value"> <formal-name>Modified Subsequent System Confidentiality Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">Negligible</enum> <enum value="l">Low</enum> <enum value="h">High</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-msi-msa-cia-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name=('msi','msa')]/@value"> <formal-name>Modified Safety-Related Subsequent System Integrity and Availability Values</formal-name> <enum value="x">Not Defined</enum> <enum value="n">Negligible</enum> <enum value="l">Low</enum> <enum value="h">High</enum> <enum value="s">Safety</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-env-cia-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name=('cr','ir','ar')]/@value"> <formal-name>Vulnerability Response Effort Values</formal-name> <enum value="x">Not Defined</enum> <enum value="l">Low</enum> <enum value="m">Medium</enum> <enum value="h">High</enum> </allowed-values> <allowed-values id="oscal-cvss-v4.0-e-values" target=".[@system='https://www.first.org/cvss/v4-0' and @name='e']/@value"> <formal-name>Vulnerability Response Effort Values</formal-name> <enum value="x">Not Defined</enum> <enum value="a">Attacked</enum> <enum value="p">PoC</enum> <enum value="u">Unreported</enum> </allowed-values> </constraint> </define-assembly> </model> </define-assembly>
<define-assembly name="response" scope="local"> <formal-name>Risk Response</formal-name> <description>Describes either recommended or an actual plan for addressing the risk.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Remediation Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this remediation elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>risk response</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <define-flag name="lifecycle" as-type="token" required="yes"> <formal-name>Remediation Intent</formal-name> <description>Identifies whether this is a recommendation, such as from an assessor or tool, or an actual plan accepted by the system owner.</description> <constraint> <allowed-values id="oscal-response-lifecycle-values" allow-other="yes"> <enum value="recommendation">Recommended remediation.</enum> <enum value="planned">The actions intended to resolve the risk.</enum> <enum value="completed">This remediation activities were performed to address the risk.</enum> </allowed-values> </constraint> </define-flag> <model> <define-field name="title" min-occurs="1" max-occurs="1" as-type="markup-line"> <formal-name>Response Title</formal-name> <description>The title for this response activity.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Response Description</formal-name> <description>A human-readable description of this response plan.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="origin" max-occurs="unbounded"> <group-as name="origins" in-json="ARRAY"/> <remarks> <p>Used to identify the individual and/or tool that generated this recommended or planned response.</p> </remarks> </assembly>
<define-assembly name="required-asset" max-occurs="unbounded"> <!-- QUESTION: Do we need to identify a set of remediation assets similar to assessment-assets --> <formal-name>Required Asset</formal-name> <description>Identifies an asset required to achieve remediation.</description> <group-as name="required-assets" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Required Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this required asset elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>asset</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="subject-reference" min-occurs="0" max-occurs="unbounded"> <use-name>subject</use-name> <group-as name="subjects" in-json="ARRAY"/> <remarks> <p>Identifies an asset associated with this requirement, such as a party, system component, or inventory-item.</p> </remarks> </assembly> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Title for Required Asset</formal-name> <description>The title for this required asset.</description> </define-field> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Description of Required Asset</formal-name> <description>A human-readable description of this required asset.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <assembly ref="task" min-occurs="0" max-occurs="unbounded"> <group-as name="tasks" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <allowed-values id="oscal-response-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="type">Risk Response Type</enum> </allowed-values> <allowed-values id="oscal-response-prop-type-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type']/@value"> <enum value="avoid">The risk will be eliminated.</enum> <enum value="mitigate">The risk will be reduced.</enum> <enum value="transfer">The risk will be transferred to another organization or entity.</enum> <enum value="accept">The risk will continue to exist without further efforts to address it. (Sometimes referred to as "Operationally required")</enum> <enum value="share">The risk will be partially transferred to another organization or entity.</enum> <enum value="contingency">Plans will be made to address the risk impact if the risk occurs. (This is a form of mitigation.)</enum> <enum value="none">No response, such as when the identified risk is found to be a false positive.</enum> </allowed-values> </constraint> </define-assembly>
<define-flag name="objective-id" as-type="token" scope="local"> <!-- This is an id to sync with control syntax --> <formal-name>Objective ID</formal-name> <description>Points to an assessment objective.</description> </define-flag>
<define-assembly name="assessment-part"> <!--scope="local"--> <!-- QUESTION: Is it confusing to use part here, given the control meaning of part? --> <formal-name>Assessment Part</formal-name> <description>A partition of an assessment plan or results or a child of another part.</description> <use-name>part</use-name> <define-flag name="uuid" as-type="uuid"> <!-- CHANGE: from uuiid to uuid --> <formal-name>Part Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this part elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>part</code> can be used to reference the data item locally or globally (e.g., in an ported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <define-flag name="name" as-type="token" required="yes"> <formal-name>Part Name</formal-name> <description>A textual label that uniquely identifies the part's semantic type.</description> <constraint> <allowed-values id="oscal-assessment-part-values" allow-other="yes"> <!-- QUESTION: Should this be in sync with control part? Should these be defined here or should they be defined in the context of use? --> <enum value="asset">An assessment asset.</enum> <enum value="method">An assessment method.</enum> <enum value="objective">Describes a set of control objectives.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="ns" as-type="uri" default="http://csrc.nist.gov/ns/oscal"> <!-- CHANGED: data type to uri --> <formal-name>Part Namespace</formal-name> <description>A namespace qualifying the part's name. This allows different organizations to associate distinct semantics with the same name.</description> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code>http://csrc.nist.gov/ns/oscal</code> and the name should be a name defined by the associated OSCAL model.</p> </remarks> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Part Class</formal-name> <description>A textual label that provides a sub-type or characterization of the part's <code>name</code>. This can be used to further distinguish or discriminate between the semantics of multiple parts of the same control with the same <code>name</code> and <code>ns</code>.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> <p>A <code>class</code> can also be used in an OSCAL profile as a means to target an alteration to control content.</p> </remarks> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line" > <formal-name>Part Title</formal-name> <description>A name given to the part, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <define-field name="prose" as-type="markup-multiline" in-xml="UNWRAPPED" min-occurs="0"> <!-- QUESTION: Is this the right name? --> <formal-name>Part Text</formal-name> <description>Permits multiple paragraphs, lists, tables etc.</description> </define-field> <assembly ref="assessment-part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <!-- <any/> --> </model> <constraint> <allowed-values id="oscal-assesment-part-objective-name" target=".[@name='objective']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="method">The assessment method to use. This typically appears on parts with the name "objective".</enum> </allowed-values> <has-cardinality id="oscal-assesment-part-objective-cardinality" target=".[@name='objective']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='method']" min-occurs="1"/> <allowed-values id="oscal-assesment-part-objective-method-value" target=".[@name='objective']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='method']/@value"> <enum value="INTERVIEW">The process of holding discussions with individuals or groups of individuals within an organization to once again, facilitate assessor understanding, achieve clarification, or obtain evidence.</enum> <enum value="EXAMINE">The process of reviewing, inspecting, observing, studying, or analyzing one or more assessment objects (i.e., specifications, mechanisms, or activities).</enum> <enum value="TEST">The process of exercising one or more assessment objects (i.e., activities or mechanisms) under specified conditions to compare actual with expected behavior.</enum> </allowed-values> </constraint> <remarks> <p>A <code>part</code> provides for logical partitioning of prose, and can be thought of as a grouping structure (e.g., section). A <code>part</code> can have child parts allowing for arbitrary nesting of prose content (e.g., statement hierarchy). A <code>part</code> can contain <code>prop</code> objects that allow for enriching prose text with structured name/value information.</p> <p>A <code>part</code> can be assigned an optional <code>id</code>, which allows for internal and external references to the textual concept contained within a <code>part</code>. A <code>id</code> provides a means for an OSCAL profile, or a higher layer OSCAL model to reference a specific part within a <code>catalog</code>. For example, an <code>id</code> can be used to reference or to make modifications to a control statement in a profile.</p> <p>Use of <code>part</code> and <code>prop</code> provides for a wide degree of extensibility within the OSCAL catalog model. The optional <code>ns</code> provides a means to qualify a part's <code>name</code>, allowing for organization-specific vocabularies to be defined with clear semantics. Any organization that extends OSCAL in this way should consistently assign a <code>ns</code> value that represents the organization, making a given namespace qualified <code>name</code> unique to that organization. This allows the combination of <code>ns</code> and <code>name</code> to always be unique and unambiguous, even when mixed with extensions from other organizations. Each organization is responsible for governance of their own extensions, and is strongly encouraged to publish their extensions as standards to their user community. If no <code>ns</code> is provided, the name is expected to be in the "OSCAL" namespace.</p> <p>To ensure a <code>ns</code> is unique to an organization and naming conflicts are avoided, a URI containing a DNS or other globally defined organization name should be used. For example, if FedRAMP and DoD both extend OSCAL, FedRAMP will use the <code>ns</code> <code>http://fedramp.gov/ns/oscal</code>, while DoD might use the <code>ns</code> <code>https://defense.gov</code> for any organization specific <code>name</code>.</p> <p>Tools that process OSCAL content are not required to interpret unrecognized OSCAL extensions; however, OSCAL compliant tools should not modify or remove unrecognized extensions, unless there is a compelling reason to do so, such as data sensitivity.</p> </remarks> </define-assembly>
</METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <METASCHEMA xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0"> <schema-name>OSCAL Assessment Plan Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-ap</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL assessment plan format is used to describe the information typically provided by an assessor during the preparation for an assessment.</p> <p>The root of the OSCAL assessment plan format is <code>assessment-plan</code>. </p> </remarks> <!-- IMPORT STATEMENTS --> <import href="oscal_metadata_metaschema.xml"/> <import href="oscal_assessment-common_metaschema.xml"/> <!-- TOP LEVEL ASSEMBLY --> <define-assembly name="assessment-plan"> <formal-name>Security Assessment Plan (SAP)</formal-name> <description>An assessment plan, such as those provided by a FedRAMP assessor.</description> <root-name>assessment-plan</root-name> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Plan Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this assessment plan in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ap-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>assessment plan</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="metadata" min-occurs="1" max-occurs="1"/> <assembly ref="import-ssp" min-occurs="1" max-occurs="1"> <remarks> <p>Used by the SAP to import information about the system being assessed.</p> </remarks> </assembly> <define-assembly name="local-definitions"> <!-- CHANGE: moved "local-definitions" to hete from assessment-subjects --> <formal-name>Local Definitions</formal-name> <description>Used to define data objects that are used in the assessment plan, that do not appear in the referenced SSP.</description> <model> <assembly ref="system-component" min-occurs="0" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> <remarks> <p>Used to add any components, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <assembly ref="inventory-item" min-occurs="0" max-occurs="unbounded"> <group-as name="inventory-items" in-json="ARRAY"/> <remarks> <p>Used to add any inventory-items, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <assembly ref="system-user" min-occurs="0" max-occurs="unbounded"> <use-name>user</use-name> <group-as name="users" in-json="ARRAY"/> <remarks> <p>Used to add any users, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <!-- CHANGED: "objective" to "add-objectives-and-methods" --> <assembly ref="local-objective" min-occurs="0" max-occurs="unbounded"> <use-name>objectives-and-methods</use-name> <group-as name="objectives-and-methods" in-json="ARRAY"/> </assembly>
<!-- CHANGED: implemented new model --> <assembly ref="activity" min-occurs="0" max-occurs="unbounded"> <group-as name="activities" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <is-unique id="oscal-unique-ap-local-definitions-component" target="component"> <key-field target="@uuid"/> <remarks> <p>Since multiple <code>component</code> entries can be provided, each component must have a unique <code>uuid</code>.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ap-local-definitions-user" target="user"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a user.</p> </remarks> </is-unique> </constraint> </define-assembly> <define-assembly name="terms-and-conditions"> <formal-name>Assessment Plan Terms and Conditions</formal-name> <description>Used to define various terms and conditions under which an assessment, described by the plan, can be performed. Each child part defines a different type of term or condition.</description> <model> <assembly ref="assessment-part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> </model> <constraint> <allowed-values id="oscal-terms-and-conditions-part-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="rules-of-engagement">Defines the circumstances, conditions, degree, and manner in which the use of cyber-attack techniques or actions may be applied to the assessment.</enum> <enum value="disclosures">Any information the assessor should make known to the system owner or authorizing official. Has child 'item' parts for each individual disclosure.</enum> <enum value="assessment-inclusions">Defines any assessment activities which the system owner or authorizing official wishes to ensure are performed as part of the assessment.</enum> <enum value="assessment-exclusions">Defines any assessment activities which the system owner or authorizing official explicitly prohibits from being performed as part of the assessment.</enum> <enum value="results-delivery">Defines conditions related to the delivery of the assessment results, such as when to deliver, how, and to whom.</enum> <enum value="assumptions">Defines any supposition made by the assessor. Has child 'item' parts for each assumption.</enum> <enum value="methodology">An explanation of practices, procedures, and rules used in the course of the assessment.</enum> </allowed-values> </constraint> </define-assembly> <!-- CHANGED: "objectives" to "reviewed-controls" --> <assembly ref="reviewed-controls" min-occurs="1" max-occurs="1"/> <assembly ref="assessment-subject" min-occurs="0" max-occurs="unbounded"> <group-as name="assessment-subjects" in-json="ARRAY"/> </assembly> <assembly ref="assessment-assets" min-occurs="0" max-occurs="1"> <!-- CHANGED: "assets" to "assessment-assets" --> </assembly>
<!-- CHANGED: removed "assessment-actions" merging with "tasks" -->
<!-- CHANGED: Moved "schedule" to top level (from assessment-activities), and changed model to "task" --> <assembly ref="task" min-occurs="0" max-occurs="unbounded"> <group-as name="tasks" in-json="ARRAY"/> </assembly> <assembly ref="back-matter" min-occurs="0" max-occurs="1"/> </model> <!-- todo: add remark need to describe how import-ssp is also importing roles, parties, locations defined in the SSP, as well as other (similar) objects that may have been imported into the SSP (e.g., control-id). Controls that can be referenced are those imported into the SSP through resolved profile. --> <!-- bogus example <constraint> <index id="index-assessment-plan-roles" name="index-assessment-plan-role-ids" target="metadata/role|doc(import-ssp/@href)/metadata/role"> <key-field target="@id"/> </index> <index-has-key name="index-assessment-plan-role-ids" target="tasks/responsible-roles"> <key-field target="@role-id"/> </index-has-key> </constraint> --> </define-assembly>
</METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema-xslt/support/metaschema/schema/xml/metaschema.xsd"> <schema-name>OSCAL Assessment Results Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-ar</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL assessment results format is used to describe the information typically provided by an assessor following an assessment.</p> <p>The root of the OSCAL assessment results format is <code>assessment-results</code>. </p> </remarks> <!-- IMPORT STATEMENTS --> <import href="oscal_metadata_metaschema.xml"/> <import href="oscal_assessment-common_metaschema.xml"/> <!-- TOP LEVEL ASSEMBLY --> <define-assembly name="assessment-results"> <formal-name>Security Assessment Results (SAR)</formal-name> <description>Security assessment results, such as those provided by a FedRAMP assessor in the FedRAMP Security Assessment Report.</description> <root-name>assessment-results</root-name> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Results Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this assessment results instance in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ar-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>assessment result</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="metadata" min-occurs="1" max-occurs="1"/> <assembly ref="import-ap" min-occurs="1" max-occurs="1"> <remarks> <p>Used by the SAR to import information about the original plan for assessing the system.</p> </remarks> </assembly> <define-assembly name="local-definitions"> <!-- CHANGE: added "local-definitions" --> <formal-name>Local Definitions</formal-name> <description>Used to define data objects that are used in the assessment plan, that do not appear in the referenced SSP.</description> <model> <assembly ref="local-objective" min-occurs="0" max-occurs="unbounded"> <use-name>objectives-and-methods</use-name> <group-as name="objectives-and-methods" in-json="ARRAY"/> </assembly>
<!-- CHANGED: implemented new model --> <assembly ref="activity" min-occurs="0" max-occurs="unbounded"> <use-name>activity</use-name> <group-as name="activities" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <assembly ref="result" min-occurs="1" max-occurs="unbounded"> <!-- CHANGED: "results" to "result" --> <use-name>result</use-name> <!-- CHANGED: "results_group" to "results" --> <group-as name="results" in-json="ARRAY"/> </assembly> <assembly ref="back-matter" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- ********** RESULTS Assembly ********** --> <define-assembly name="result"> <formal-name>Assessment Result</formal-name> <description>Used by the assessment results and POA&amp;M. In the assessment results, this identifies all of the assessment observations and findings, initial and residual risks, deviations, and disposition. In the POA&amp;M, this identifies initial and residual risks, deviations, and disposition.</description> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Results Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this set of results in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ar-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>assessment result</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="1" max-occurs="1" as-type="markup-line"> <formal-name>Results Title</formal-name> <description>The title for this set of results.</description> </define-field> <!-- CHANGE: Added WITH_WRAPPER to description --> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Results Description</formal-name> <description>A human-readable description of this set of test results.</description> </define-field>
<define-field name="start" as-type="date-time-with-timezone" min-occurs="1" max-occurs="1"> <formal-name>start field</formal-name> <description>Date/time stamp identifying the start of the evidence collection reflected in these results.</description> </define-field> <define-field name="end" as-type="date-time-with-timezone" max-occurs="1"> <formal-name>end field</formal-name> <description>Date/time stamp identifying the end of the evidence collection reflected in these results. In a continuous motoring scenario, this may contain the same value as start if appropriate.</description> </define-field>
<assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="local-definitions"> <!-- CHANGE: added "local-definitions" --> <formal-name>Local Definitions</formal-name> <description>Used to define data objects that are used in the assessment plan, that do not appear in the referenced SSP.</description> <model> <assembly ref="system-component" min-occurs="0" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> <remarks> <p>Used to add any components, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <assembly ref="inventory-item" min-occurs="0" max-occurs="unbounded"> <group-as name="inventory-items" in-json="ARRAY"/> <remarks> <p>Used to add any inventory-items, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <assembly ref="system-user" min-occurs="0" max-occurs="unbounded"> <use-name>user</use-name> <group-as name="users" in-json="ARRAY"/> <remarks> <p>Used to add any users, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly>
<assembly ref="assessment-assets" min-occurs="0" max-occurs="1"> <!-- To augment the assessment plan --> <remarks> <p>This needs to be defined in the results if an assessment platform used is different from the one described in the assessment plan. Else the platform(s) defined in the plan may be referenced within the results.</p> </remarks> </assembly>
<assembly ref="task" min-occurs="0" max-occurs="unbounded"> <use-name>assessment-task</use-name> <group-as name="tasks" in-json="ARRAY"/> </assembly> </model> <constraint> <is-unique id="oscal-unique-ar-local-definitions-component" target="component"> <key-field target="@uuid"/> <remarks> <p>Since multiple <code>component</code> entries can be provided, each component must have a unique <code>uuid</code>.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ar-local-definitions-user" target="user"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a user.</p> </remarks> </is-unique> </constraint> </define-assembly> <!-- CHANGED: "objectives" to "reviewed-controls" --> <assembly ref="reviewed-controls" min-occurs="1" max-occurs="1"> <remarks> <p>The Assessment Results <code>control-selection</code> ignores any control selection in the Assessment Plan and re-selects controls from the baseline identified by the SSP.</p> <p>The Assessment Results <code>control-objective-selection</code> ignores any control objective selection in the Assessment Plan and re-selects control objectives from the baseline identified by the SSP.</p> <p>Any additional control objectives defined in the Assessment Plan <code>local-definitions</code> do not need to be re-defined in the Assessment Results <code>local-definitions</code>; however, if they were explicitly referenced with an Assessment Plan <code>control-objective-selection</code>, they need to be selected again in the Assessment Results <code>control-objective-selection</code>.</p> </remarks> </assembly>
<define-assembly name="attestation" max-occurs="unbounded"> <formal-name>Attestation Statements</formal-name> <description>A set of textual statements, typically written by the assessor.</description> <group-as name="attestations" in-json="ARRAY"/> <model> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <assembly ref="assessment-part" min-occurs="1" max-occurs="unbounded"> <!-- TODO: defined allowed parts: authorization-statement --> <use-name>part</use-name> <group-as name="parts" in-json="ARRAY"/> </assembly> </model> <constraint> <is-unique id="oscal-unique-ar-attestation-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <!-- CHANGED: removed "schedule" and replaced with "assessment-log" --> <define-assembly name="assessment-log"> <formal-name>Assessment Log</formal-name> <description>A log of all assessment-related actions taken.</description> <model> <define-assembly name="entry" min-occurs="1" max-occurs="unbounded"> <formal-name>Assessment Log Entry</formal-name> <!-- TODO: improve this description --> <description>Identifies the result of an action and/or task that occurred as part of executing an assessment plan or an assessment event that occurred in producing the assessment results.</description> <group-as name="entries" in-json="ARRAY"/> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>Assessment Log Entry Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference an assessment event in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ar-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>assessment log entry</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="0" max-occurs="1" as-type="markup-line"> <formal-name>Action Title</formal-name> <description>The title for this event.</description> </define-field> <!-- CHANGE: Added WITH_WRAPPER to description --> <define-field name="description" min-occurs="0" max-occurs="1" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Action Description</formal-name> <description>A human-readable description of this event.</description> </define-field> <define-field name="start" as-type="date-time-with-timezone" min-occurs="1" max-occurs="1"> <formal-name>Start</formal-name> <description>Identifies the start date and time of an event.</description> </define-field> <define-field name="end" as-type="date-time-with-timezone" max-occurs="1"> <formal-name>End</formal-name> <description>Identifies the end date and time of an event. If the event is a point in time, the start and end will be the same date and time.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="logged-by" max-occurs="unbounded"> <group-as name="logged-by" in-json="ARRAY"/> </assembly> <!-- CHANGED: Added "related-task" --> <assembly ref="related-task" max-occurs="unbounded"> <group-as name="related-tasks" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> </model> </define-assembly>
<!-- CHANGE: move "observation" from finding --> <assembly ref="observation" min-occurs="0" max-occurs="unbounded"> <group-as name="observations" in-json="ARRAY"/> </assembly>
<!-- CHANGE: move "risk" from finding --> <assembly ref="risk" max-occurs="unbounded"> <group-as name="risks" in-json="ARRAY"/> </assembly> <assembly ref="finding" max-occurs="unbounded"> <group-as name="findings" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- Moved Finding Assembly to Assessment Common -->
<!-- Assessment Plan Import --> <define-assembly name="import-ap"> <formal-name>Import Assessment Plan</formal-name> <description>Used by assessment-results to import information about the original plan for assessing the system.</description> <define-flag name="href" required="yes" as-type="uri-reference"> <formal-name>Assessment Plan Reference</formal-name> <description>A resolvable URL reference to the assessment plan governing the assessment activities.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
</METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!-- OSCAL CATALOG METASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-control-group-property-name SYSTEM "shared-constraints/allowed-values-control-group-property-name.ent"> ]> <?xml-stylesheet type="text/css" href="metaschema-author.css"?> <METASCHEMA xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0"> <schema-name>OSCAL Control Catalog Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-catalog</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL Control Catalog format can be used to describe a collection of security controls and related control enhancements, along with contextualizing documentation and metadata. The root of the Control Catalog format is <code>catalog</code>.</p> </remarks> <import href="oscal_control-common_metaschema.xml"/> <import href="oscal_metadata_metaschema.xml"/> <!-- <import href="oscal_mapping-common_metaschema.xml"/> --> <define-assembly name="catalog"> <formal-name>Catalog</formal-name> <description>A structured, <a href="https://pages.nist.gov/OSCAL/concepts/terminology/#catalog">organized collection</a> of control information.</description> <root-name>catalog</root-name> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Catalog Universally Unique Identifier</formal-name> <description>Provides a globally unique means to identify a given catalog instance.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="change-on-write"/> </define-flag>
<model> <assembly ref="metadata" min-occurs="1"/> <assembly ref="parameter" max-occurs="unbounded"> <group-as name="params" in-json="ARRAY"/> </assembly> <assembly ref="control" max-occurs="unbounded"> <group-as name="controls" in-json="ARRAY"/> </assembly> <assembly ref="group" max-occurs="unbounded"> <group-as name="groups" in-json="ARRAY"/> </assembly> <assembly ref="back-matter"> <remarks> <p>Back matter including references and resources.</p> </remarks> </assembly> </model> <constraint> <allowed-values id="oscal-catalog-metadata-prop-name" target="metadata/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="resolution-tool">The tool used to produce a resolved profile.</enum> <enum value="source-profile-uuid">The document-level <code>uuid</code> of the source profile from which the catalog was produced by <a href="https://pages.nist.gov/OSCAL/concepts/processing/profile-resolution/">profile resolution</a>.</enum> </allowed-values> <allowed-values id="oscal-catalog-metadata-link-rel-type" target="metadata/link/@rel" allow-other="yes"> <enum value="source-profile">The profile from which the catalog was produced by <a href="https://pages.nist.gov/OSCAL/concepts/processing/profile-resolution/">profile resolution</a>.</enum> <enum value="source-profile-uuid">The document-level <code>uuid</code> of the profile from which the catalog was produced by <a href="https://pages.nist.gov/OSCAL/concepts/processing/profile-resolution/">profile resolution</a>.</enum> </allowed-values> <index id="oscal-catalog-parts" name="catalog-parts" target="//part" > <key-field target="@id"/> </index> <index id="oscal-catalog-props" name="catalog-props" target="//prop" > <key-field target="@uuid"/> </index> <index id="oscal-catalog-groups-controls-parts" name="catalog-groups-controls-parts" target="//(control|group|part)"> <key-field target="@id"/> </index> <index id="oscal-catalog-controls" name="catalog-controls" target="//control" > <key-field target="@id"/> </index> <index id="oscal-catalog-params" name="catalog-params" target="//param" > <key-field target="@id"/> </index> <index id="oscal-catalog-groups" name="catalog-groups" target="//group" > <key-field target="@id"/> </index> </constraint> <remarks> <p>Catalogs may use one or more <code>group</code> objects to subdivide the control contents of a catalog.</p> </remarks> <example> <description>A small catalog with a single control.</description> <catalog xmlns="http://csrc.nist.gov/ns/oscal/1.0" uuid="35566cd4-7331-43ba-b023-988c38d62673"> <title>A Miniature Catalog</title> <control id="single"> <title>A Single Control</title> <!-- TODO: this is not a complete valid example. Fix this. --> </control> </catalog> </example> </define-assembly> <define-assembly name="group"> <formal-name>Control Group</formal-name> <description>A group of controls, or of groups of controls.</description> <define-flag name="id" as-type="token"> <!-- This is an id because the identifier is assigned and managed externally by humans. --> <formal-name>Group Identifier</formal-name> <!-- Identifier Declaration --> <description>Identifies the group for the purpose of cross-linking within the defining instance or from other instances that reference the catalog.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Group Class</formal-name> <description>A textual label that provides a sub-type or characterization of the group.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> <p>A <code>class</code> can also be used in an OSCAL profile as a means to target an alteration to control content.</p> </remarks> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Group Title</formal-name> <description>A name given to the group, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="parameter" max-occurs="unbounded"> <group-as name="params" in-json="ARRAY"/> </assembly>
<assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> <choice> <assembly ref="group" max-occurs="unbounded"> <group-as name="groups" in-json="ARRAY"/> </assembly> <assembly ref="control" max-occurs="unbounded"> <group-as name="controls" in-json="ARRAY"/> </assembly> </choice> <!--<any/>--> </model> <constraint> <allowed-values id="oscal-group-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-control-group-property-name; </allowed-values> <allowed-values id="oscal-group-part-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="overview">An introduction to a control or a group of controls.</enum> <enum value="instruction">Information providing directions for a control or a group of controls.</enum> </allowed-values> </constraint> <remarks> <p>Catalogs can use the catalog <code>group</code> construct to organize related controls into a single grouping, such as a family of controls or other logical organizational structure.</p> <p>A <code>group</code> may have its own properties, statements, parameters, and references, which are inherited by all controls of that are a member of the group.</p> </remarks> <example> <group xmlns="http://csrc.nist.gov/ns/oscal/1.0" id="xyz"> <title>My Group</title> <prop name="required" value="some value"/> <control id="xyz1"> <title>Control</title> </control> </group> </example> </define-assembly> <define-assembly name="control"> <formal-name>Control</formal-name> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/terminology/#control" >structured object</a> representing a requirement or guideline, which when implemented will reduce an aspect of risk related to an information system and its information.</description> <define-flag name="id" as-type="token" required="yes"> <!-- This is an id because the identifier is managed externally. --> <formal-name>Control Identifier</formal-name> <!-- Identifier Declaration --> <description>Identifies a control such that it can be referenced in the defining catalog and other OSCAL instances (e.g., profiles).</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="local"/> <prop name="identifier-scope" value="instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Control Class</formal-name> <description>A textual label that provides a sub-type or characterization of the control.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> <p>A <code>class</code> can also be used in an OSCAL profile as a means to target an alteration to control content.</p> </remarks> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Control Title</formal-name> <description>A name given to the control, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="parameter" max-occurs="unbounded"> <group-as name="params" in-json="ARRAY"/> </assembly> <!-- TODO: Need to be able to add valid values in context --> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> <!-- ######################################## --> <!-- The following assembly is very important but might not be available until profile resolution supports it. --> <!-- The assembly needs the import of oscal_mapping-common_metaschema.xml, commented out above! --> <!-- The easier way forward would probably be to not allow tailoring in a profile, and the resolution will just copy and paste when used by the catalog au.--> <!-- ######################################## --> <!-- define-assembly name="mapping"> <formal-name>Mapping</formal-name> <description>A mapping between the containing control and another resource identified by <code>target-resource</code>.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Mapping Identifier</formal-name> <description>The unique identifier for the mapping.</description> </define-flag> <model> <choice> <define-assembly name="local-mapping" max-occurs="unbounded"> <formal-name>Local Mapping</formal-name> <description> TBD </description> <group-as name="local-mappings" in-json="ARRAY"/> <model> <assembly ref="mapping-resource-reference" min-occurs="1"> <use-name>target-resource</use-name> </assembly> <assembly ref="map" min-occurs="1" max-occurs="unbounded"> <group-as name="maps" in-json="ARRAY"/> </assembly> </model> </define-assembly> <define-assembly name="external-mapping" max-occurs="unbounded"> <formal-name>External Mapping</formal-name> <description> TBD </description> <group-as name="external-mappings" in-json="ARRAY"/> <define-flag name="mapping-collection-uuid" as-type="uuid" required="yes"> <formal-name>Mapping Collection Identifier</formal-name> <description>The unique identifier for the <code>mapping-collection</code> instance.</description> </define-flag> <define-flag name="map-uuid" as-type="uuid" required="yes"> <formal-name>Map Item Identifier</formal-name> <description>The unique identifier for the <code>map</code> instance.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly> </choice> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly --> <assembly ref="control" max-occurs="unbounded"> <group-as name="controls" in-json="ARRAY"/> </assembly> </model> <constraint> <expect id="oscal-catalog-control-require-statement-when-not-withdrawn" target="." test="prop[@name='status']/@value=('withdrawn','Withdrawn') or part[@name='statement']"/> <allowed-values id="oscal-control-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-control-group-property-name; <enum value="status">The status of a <code>control</code>. For example, a value of 'withdrawn' can indicate that the <code>control</code> has been withdrawn and should no longer be used.</enum> </allowed-values> <allowed-values id="oscal-control-prop-status-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='status']/@value"> <enum value="withdrawn">The control is no longer used.</enum> <enum value="Withdrawn" deprecated="1.0.0">**(deprecated)*** Use 'withdrawn' instead.</enum> </allowed-values> <allowed-values id="oscal-control-link-rel-type" target="link/@rel" allow-other="yes"> <enum value="reference">The link cites an external resource related to this control.</enum> <enum value="related">The link identifies another control with bearing to this control.</enum> <enum value="required">The link identifies another control that must be present if this control is present.</enum> <enum value="incorporated-into">The link identifies other control content where this control content is now addressed.</enum> <enum value="moved-to">The containing control definition was moved to the referenced control.</enum> </allowed-values> <!-- TODO: add expect constraint to check for controls that reference themselves --> <index-has-key id="oscal-catalog-groups-controls-parts" level="WARNING" name="catalog-groups-controls-parts" target="link[@rel=('related','required','incorporated-into','moved-to') and starts-with(@href,'#')]"> <key-field target="@href" pattern="#(.*)"/> </index-has-key> <allowed-values id="oscal-control-part-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="overview">An introduction to a control or a group of controls.</enum> <enum value="statement">A set of implementation requirements or recommendations.</enum> <enum value="guidance">Additional information to consider when selecting, implementing, assessing, and monitoring a control.</enum> <enum value="example">An example of an implemented requirement or control statement.</enum> <enum value="assessment" deprecated="1.0.1">**(deprecated)** Use 'assessment-method' instead.</enum> <enum value="assessment-method">The part describes a method-based assessment over a set of assessment objects.</enum> </allowed-values> <allowed-values id="oscal-control-statement-part-subpart-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='statement']//part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="item">An individual item within a control statement.</enum> <remarks> <p>Nested statement parts are "item" parts.</p> </remarks> </allowed-values> <allowed-values id="oscal-control-statement-part-name" target=".//part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="objective" deprecated="1.0.1">**(deprecated)** Use 'assessment-objective' instead.</enum> <enum value="assessment-objective">The part describes a set of assessment objectives.</enum> <remarks> <p>Objectives can be nested.</p> </remarks> </allowed-values> <allowed-values id="oscal-control-objective-part-subpart-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="objects" deprecated="1.0.1">**(deprecated)** Use 'assessment-objects' instead.</enum> <enum value="assessment-objects">Provides a listing of assessment objects.</enum> <remarks> <p>Assessment objects appear on assessment methods.</p> </remarks> </allowed-values> <allowed-values id="oscal-control-statement-part-prop-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="method" deprecated="1.0.1">**(deprecated)** Use 'method' in the 'http://csrc.nist.gov/ns/rmf' namespace. The assessment method to use. This typically appears on parts with the name "assessment-method".</enum> </allowed-values> <allowed-values id="oscal-control-statement-part-rmf-prop-name" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/rmf')]/@name"> <enum value="method">The assessment method to use. This typically appears on parts with the name "assessment-method".</enum> </allowed-values> <expect level="WARNING" id="oscal-method-part-has-method-prop" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]" test="prop[has-oscal-namespace(('http://csrc.nist.gov/ns/oscal','http://csrc.nist.gov/ns/rmf')) and @name='method']"/> <allowed-values id="oscal-control-objective-part-method-prop-value" target="part[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('assessment','assessment-method')]/prop[has-oscal-namespace(('http://csrc.nist.gov/ns/oscal','http://csrc.nist.gov/ns/rmf')) and @name='method']/@value"> <enum value="INTERVIEW">The process of holding discussions with individuals or groups of individuals within an organization to once again, facilitate assessor understanding, achieve clarification, or obtain evidence.</enum> <enum value="EXAMINE">The process of reviewing, inspecting, observing, studying, or analyzing one or more assessment objects (i.e., specifications, mechanisms, or activities).</enum> <enum value="TEST">The process of exercising one or more assessment objects (i.e., activities or mechanisms) under specified conditions to compare actual with expected behavior.</enum> </allowed-values> </constraint> <remarks> <p>Each security or privacy control within the catalog is defined by a distinct control instance. Controls may be as complex or as simple as a catalog defines them. They may be decomposed or further specified into child <code>control</code> objects, for example to represent control enhancements or specific breakouts of control functionality, to be maintained as discrete requirements. Controls may also contain structured parts (using <code>part</code>) and they may be grouped together in families or classes with <code>group</code>.</p> <p>Control structures in OSCAL will also exhibit regularities and rules that are not codified in OSCAL but in its applications or domains of application. For example, for catalogs describing controls as defined by NIST SP 800-53, a control must have a part with the name "statement", which represents the textual narrative of the control. This "statement" part must occur only once, but may have nested parts to allow for multiple paragraphs or sections of text. This organization supports addressability of this data content as long as, and only insofar as, it is consistently implemented across the control set. As given with these model definitions, constraints defined and assigned here can aid in ensuring this regularity; but other such constraints and other useful patterns of use remain to be discovered and described.</p> </remarks> <example> <control xmlns="http://csrc.nist.gov/ns/oscal/1.0" id="x"> <title>Control 1</title> </control> </example> </define-assembly> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!-- OSCAL GRAND UNIFIED MEGALOMETASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-control-group-property-name SYSTEM "./shared-constraints/allowed-values-control-group-property-name.ent"> ]> <METASCHEMA xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0"> <schema-name>OSCAL Unified Model of Models</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-complete</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal/1.0</json-base-uri> <remarks> <p>This format represents a combination of all of the OSCAL models.</p> </remarks> <import href="oscal_catalog_metaschema.xml"/> <import href="oscal_mapping_metaschema.xml"/> <import href="oscal_profile_metaschema.xml"/> <import href="oscal_component_metaschema.xml"/> <import href="oscal_ssp_metaschema.xml"/> <import href="oscal_assessment-plan_metaschema.xml"/> <import href="oscal_assessment-results_metaschema.xml"/> <import href="oscal_poam_metaschema.xml"/> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-responsible-roles-operations SYSTEM "./shared-constraints/allowed-values-responsible-roles-operations.ent"> <!ENTITY allowed-values-responsible-roles-component-production SYSTEM "./shared-constraints/allowed-values-responsible-roles-component-production.ent"> <!ENTITY allowed-values-property-name-asset-type-values SYSTEM "./shared-constraints/allowed-values-property-name-asset-type-values.ent"> <!ENTITY allowed-values-component_component_property-name SYSTEM "./shared-constraints/allowed-values-component_component_property-name.ent"> <!ENTITY allowed-values-component_component_software SYSTEM "./shared-constraints/allowed-values-component_component_software.ent"> <!ENTITY allowed-values-component_component_service SYSTEM "./shared-constraints/allowed-values-component_component_service.ent"> <!ENTITY allowed-values-component_inventory-item_property-name SYSTEM "./shared-constraints/allowed-values-component_inventory-item_property-name.ent"> <!ENTITY allowed-values-component_component_link-rel SYSTEM "./shared-constraints/allowed-values-component_component_link-rel.ent"> <!ENTITY allowed-values-component-type SYSTEM "./shared-constraints/allowed-values-component-type.ent"> ]> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema-xslt/support/metaschema/schema/xml/metaschema.xsd"> <schema-name>OSCAL Component Definition Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-component-definition</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL Component Definition Model can be used to describe the implementation of controls in a <code>component</code> or a set of components grouped as a <code>capability</code>. A component can be either a <em>technical component</em>, or a <em>documentary component</em>.</p> <p>A technical component is a component that is implemented in hardware (physical or virtual) or software. Suppliers may document components in an OSCAL component definition that describes the implementation of controls in their hardware and software.</p> <p>A documentary component is a component implemented for a documented process, procedure, or policy. Suppliers may document components in an OSCAL component definition that describes the implementation of controls in their process, procedure, or policy.</p> <p>The information provided by a technical or documentary component can be used by component consumers to provide starting narratives for documenting control implementations in an OSCAL SSP.</p> <p>The root of the OSCAL Implementation Layer Component Definition model is <code>component-definition</code>.</p> </remarks>
<import href="oscal_implementation-common_metaschema.xml"/>
<define-assembly name="component-definition"> <formal-name>Component Definition</formal-name> <description>A collection of component descriptions, which may optionally be grouped by capability.</description> <root-name>component-definition</root-name> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Component Definition Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a globally unique means to identify a given component definition instance.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="change-on-write"/> </define-flag> <model> <assembly ref="metadata" min-occurs="1"/> <assembly ref="import-component-definition" max-occurs="unbounded"> <group-as name="import-component-definitions" in-json="ARRAY"/> </assembly> <assembly ref="defined-component" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> </assembly> <assembly ref="capability" max-occurs="unbounded"> <group-as name="capabilities" in-json="ARRAY"/> </assembly> <assembly ref="back-matter"/> </model> <constraint> <index id="oscal-index-system-component-uuid" name="index-system-component-uuid" target="component"> <key-field target="@uuid"/> <remarks> <p>Since multiple <code>component</code> entries can be provided, each component must have a unique <code>uuid</code>.</p> </remarks> </index> <is-unique id="oscal-unique-component-definition-capability" target="capability"> <key-field target="@uuid"/> <remarks> <p>A given <code>component</code> must not be referenced more than once within the same <code>capability</code>.</p> </remarks> </is-unique> </constraint> </define-assembly>
<define-assembly name="import-component-definition"> <formal-name>Import Component Definition</formal-name> <description>Loads a component definition from another resource.</description> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Hyperlink Reference</formal-name> <description>A link to a resource that defines a set of components and/or capabilities to import into this collection.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <!-- Without a model the flags do not get generated in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<define-assembly name="defined-component"> <formal-name>Component</formal-name> <description>A defined component that can be part of an implemented system.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Component Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a globally unique means to identify a given component.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <flag ref="defined-component-type" required="yes"> <use-name>type</use-name> </flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Component Title</formal-name> <description>A human readable name for the component.</description> </define-field> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Component Description</formal-name> <description>A description of the component, including information about its function.</description> </define-field> <define-field name="purpose" as-type="markup-line"> <formal-name>Purpose</formal-name> <description>A summary of the technological or business purpose of the component.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <assembly ref="protocol" max-occurs="unbounded"> <group-as name="protocols" in-json="ARRAY"/> <remarks> <p>Used for <code>service</code> components to define the protocols supported by the service.</p> </remarks> </assembly>
<assembly ref="control-implementation" max-occurs="unbounded"> <group-as name="control-implementations" in-json="ARRAY"/> </assembly> <!-- <assembly ref="configuration" max-occurs="unbounded"> <group-as name="configurations" in-json="BY_KEY" /> </assembly> <assembly ref="artifact" max-occurs="unbounded"> <group-as name="artifacts" in-json="BY_KEY" /> </assembly> --> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-component-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== --> &allowed-values-component_component_property-name; &allowed-values-component_inventory-item_property-name;
<!-- CHANGE: @name="date-released" changed to @name="release-date" --> </allowed-values>
<allowed-values id="oscal-component-link-rel-type" target="link/@rel" allow-other="yes"> <!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== --> &allowed-values-component_component_link-rel; <enum value="uses-network">This component uses the network provided by the identified network component.</enum> </allowed-values>
<allowed-values id="oscal-component-role-id" target="responsible-role/@role-id|control-implementation/implemented-requirement/responsible-role/@role-id|control-implementation/implemented-requirement/statement/responsible-role/@role-id" allow-other="yes"> <!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== --> &allowed-values-responsible-roles-operations; &allowed-values-responsible-roles-component-production; </allowed-values>
<allowed-values id="oscal-component-asset-type-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='asset-type']/@value" allow-other="yes"> &allowed-values-property-name-asset-type-values; </allowed-values>
<!-- ========================================================================================================== --> <!-- = TODO: The following was copied from implementation-common as-is and should probably be setup with = --> <!-- = shared constraints; however, the values are highly static (yes/no, internal/external). --> <!-- = Can be changed later with no breaking impact. --> <allowed-values id="oscal-component-allows-authenticated-scan-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='allows-authenticated-scan']/@value"> <enum value="yes">The component allows an authenticated scan.</enum> <enum value="no">The component does not allow an authenticated scan.</enum> </allowed-values>
<allowed-values id="oscal-component-virtual-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='virtual']/@value"> <enum value="yes">The component is virtualized.</enum> <enum value="no">The component is not virtualized.</enum> </allowed-values>
<allowed-values id="oscal-component-public-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='public']/@value"> <enum value="yes">The component is publicly accessible.</enum> <enum value="no">The component is not publicly accessible.</enum> </allowed-values>
<allowed-values id="oscal-component-implementation-point-value" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='implementation-point']/@value"> <enum value="internal">The component is implemented within the system boundary.</enum> <enum value="external">The component is implemented outside the system boundary.</enum> </allowed-values> <!-- ========================================================================================================== -->
<index-has-key id="oscal-index-metadata-location-uuid" name="index-metadata-location-uuid" target="prop[@name='physical-location']"> <key-field target="@value"/> </index-has-key>
<matches id="oscal-component-inherited-uuid-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='inherited-uuid']/@value" datatype="uuid" /> <matches id="oscal-component-release-date-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='release-date']/@value" datatype="date"/>
<!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== -->
<!-- ========================================================================================================== --> <!-- = SOFTWARE: type='software' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-software-component-prop-name" target="(.)[@type='software']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-component_component_software; </allowed-values>
<!-- ========================================================================================================== --> <!-- = SERVICE: type='service' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-service-component-link-rel-type" target="(.)[@type='service']/link/@rel" allow-other="yes"> &allowed-values-component_component_service; </allowed-values>
<!-- ========================================================================================================== --> <!-- = TODO: Consider whether INTERCONNECTION constraints are appropriate here. = --> <!-- = I'm not sure I see a use case for this, but doesn't break to add later. = --> <!-- = If interconnection is not appropriate for component-defintion, we'll need different = --> <!-- = component-type lists for the two models. = --> <!-- ========================================================================================================== --> <is-unique id="oscal-unique-defined-component-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> <remarks> <p>Components may be products, services, APIs, policies, processes, plans, guidance, standards, or other tangible items that enable security and/or privacy.</p> <p>The <code>type</code> indicates which of these component types is represented.</p> <p>A group of components may be aggregated into a <code>capability</code>. For example, an account management capability that consists of an account management process, and a Lightweight Directory Access Protocol (LDAP) software implementation.</p> <p>Capabilities are expressed by combining one or more components.</p> </remarks> </define-assembly>
<define-flag name="defined-component-type" as-type="string"> <formal-name>Component Type</formal-name> <description>A category describing the purpose of the component.</description> <constraint> <allowed-values id="oscal-component-type" allow-other="yes"> &allowed-values-component-type; </allowed-values> </constraint> </define-flag>
<define-assembly name="capability"> <formal-name>Capability</formal-name> <description>A grouping of other components and/or capabilities.</description> <define-flag required="yes" name="uuid" as-type="uuid"> <formal-name>Capability Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a globally unique means to identify a given capability.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="name" as-type="string" required="yes"> <formal-name>Capability Name</formal-name> <description>The capability's human-readable name.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Capability Description</formal-name> <description>A summary of the capability.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="incorporates-component" max-occurs="unbounded"> <group-as name="incorporates-components" in-json="ARRAY"/> </assembly> <assembly ref="control-implementation" max-occurs="unbounded"> <group-as name="control-implementations" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-component-definition-capability-incorporates-component" target="incorporates-component"> <key-field target="@component-uuid"></key-field> <remarks> <p>A given <code>component</code> must not be referenced more than once within the same <code>capability</code>.</p> </remarks> </is-unique> <!-- Feature Request: add constraint ensuring a capability's incorporates-component references //component-definition/component/@uuid in the same component definition instance or an imported instance--> </constraint> </define-assembly> <define-assembly name="incorporates-component"> <formal-name>Incorporates Component</formal-name> <!-- TODO: needs a description --> <description>The collection of components comprising this capability.</description> <define-flag required="yes" name="component-uuid" as-type="uuid"> <formal-name>Component Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a <code>component</code>.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Component Description</formal-name> <description>A description of the component, including information about its function.</description> </define-field> </model> </define-assembly>
<define-assembly name="control-implementation" scope="local"> <formal-name>Control Implementation Set</formal-name> <description>Defines how the component or capability supports a set of controls.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Control Implementation Set Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a means to identify a set of control implementations that are supported by a given component or capability.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="source" as-type="uri-reference" required="yes"> <formal-name>Source Resource Reference</formal-name> <description>A reference to an OSCAL catalog or profile providing the referenced control or subcontrol definition.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Description</formal-name> <description>A description of how the specified set of controls are implemented for the containing component or capability.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="set-parameter" max-occurs="unbounded"> <group-as name="set-parameters" in-json="ARRAY"/> </assembly> <assembly ref="implemented-requirement" min-occurs="1" max-occurs="unbounded"> <group-as name="implemented-requirements" in-json="ARRAY"/> </assembly> </model> <constraint> <is-unique id="oscal-unique-component-definition-control-implementation-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> </constraint> <remarks> <p>Use of <code>set-parameter</code> in this context, sets the parameter for all controls referenced by any <code>implemented-requirement</code> contained in this context. Any <code>set-parameter</code> defined in a child context will override this value. If not overridden by a child, this value applies in the child context.</p> </remarks> </define-assembly> <define-assembly name="implemented-requirement" scope="local"> <formal-name>Control Implementation</formal-name> <description>Describes how the containing component or capability implements an individual control.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Control Implementation Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a globally unique means to identify a given control implementation by a component.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <flag ref="control-id" required="yes"/> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Description</formal-name> <description>A suggestion from the supplier (e.g., component vendor or author) for how the specified control may be implemented if the containing component or capability is instantiated in a system security plan.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="set-parameter" max-occurs="unbounded"> <group-as name="set-parameters" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <assembly ref="statement" max-occurs="unbounded"> <group-as name="statements" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-component-definition-implemented-requirement-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-component-definition-implemented-requirement-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-component-definition-implemented-requirement-statement" target="statement"> <key-field target="@statement-id"/> <remarks> <p>Since <code>statement</code> entries can be referenced using the statement's statement-id, each statement must be referenced only once.</p> </remarks> </is-unique> </constraint> <remarks> <p>Implemented requirements within a component or capability in a component definition provide a means for component suppliers to suggest possible control implementation details, which may be used by a different party (e.g., component consumers) when authoring a system security plan. Thus, these requirements defined in a component definition are only a suggestion of how to implement, which may be adopted wholesale, changed, or ignored by a person defining an information system implementation.</p> <p>Use of <code>set-parameter</code> in this context, sets the parameter for the referenced control and any associated statements.</p> </remarks> </define-assembly> <define-assembly name="statement" scope="local"> <formal-name>Control Statement Implementation</formal-name> <description>Identifies which statements within a control are addressed.</description> <flag ref="statement-id" required="yes"> <remarks> <p>A reference to the specific implemented statement associated with a control.</p> </remarks> </flag> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Control Statement Reference Universally Unique Identifier</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this control statement elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#component-definition-identifiers">this or other OSCAL instances</a>. The <em>UUID</em> of the <code>control statement</code> in the source OSCAL instance is sufficient to reference the data item locally or globally (e.g., in an imported OSCAL instance).</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Statement Implementation Description</formal-name> <description>A summary of how the containing control statement is implemented by the component or capability.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-component-definition-statement-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!-- OSCAL CATALOG METASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-control-group-property-name SYSTEM "./shared-constraints/allowed-values-control-group-property-name.ent"> ]> <?xml-stylesheet type="text/css" href="metaschema-author.css"?> <METASCHEMA xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" abstract="yes"> <schema-name>OSCAL Control Catalog Format -- Common Models</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-control-common</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <import href="oscal_metadata_metaschema.xml"/> <!-- ######################################## --> <!-- # Part Assembly and related constructs # --> <!-- ######################################## --> <define-assembly name="part"> <formal-name>Part</formal-name> <description>An annotated, markup-based textual element of a control's or catalog group's definition, or a child of another part.</description> <define-flag name="id" as-type="token"> <!-- This is an id because the identifier is intended to be human-readable. --> <formal-name>Part Identifier</formal-name> <!-- Identifier Declaration --> <description>A unique identifier for the part.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> <remarks> <p>While a part is not required to have an id, it is often desirable for an identifier to be provided, which allows the part to be referenced elsewhere in OSCAL document instances. For this reason, it is RECOMMENDED to provide a part identifier.</p> </remarks> </define-flag> <define-flag name="name" as-type="token" required="yes"> <formal-name>Part Name</formal-name> <description>A textual label that uniquely identifies the part's semantic type, which exists in a value space qualified by the <code>ns</code>.</description> </define-flag> <define-flag name="ns" as-type="uri" default="http://csrc.nist.gov/ns/oscal"> <formal-name>Part Namespace</formal-name> <description>An optional namespace qualifying the part's <code>name</code>. This allows different organizations to associate distinct semantics with the same name.</description> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code>http://csrc.nist.gov/ns/oscal</code> and the name should be a name defined by the associated OSCAL model.</p> </remarks> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Part Class</formal-name> <description>An optional textual providing a sub-type or characterization of the part's <code>name</code>, or a category to which the part belongs.</description> <remarks> <p>One use of this flag is to distinguish or discriminate between the semantics of multiple parts of the same control with the same <code>name</code> and <code>ns</code> (since even within a given namespace it can be useful to overload a name).</p> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> <p>A <code>class</code> can also be used in an OSCAL profile as a means to target an alteration to control content.</p> </remarks> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>Part Title</formal-name> <description>An optional name given to the part, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <define-field name="prose" as-type="markup-multiline" in-xml="UNWRAPPED"> <formal-name>Part Text</formal-name> <description>Permits multiple paragraphs, lists, tables etc.</description> </define-field> <assembly ref="part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <!-- <any/> --> </model> <constraint> <allowed-values id="oscal-part-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-control-group-property-name; </allowed-values> </constraint> <remarks> <p>A <code>part</code> provides for logical partitioning of prose, and can be thought of as a grouping structure (e.g., section). A <code>part</code> can have child parts allowing for arbitrary nesting of prose content (e.g., statement hierarchy). A <code>part</code> can contain <code>prop</code> objects that allow for enriching prose text with structured name/value information.</p> <p>A <code>part</code> can be assigned an optional <code>id</code>, which allows references to this part from within a catalog, or within an instance of another OSCAL model that has a need to reference the part. Examples of where part referencing is used in OSCAL include:</p> <ul> <li>Referencing a part by id to tailor (make modifications to) a control statement in a profile.</li> <li>Referencing a control statement represented by a part in a system security plan implemented-requirement where a statement-level response is desired.</li> </ul> <p>Use of <code>part</code> and <code>prop</code> provides for a wide degree of extensibility within the OSCAL catalog model. The optional <code>ns</code> provides a means to qualify a part's <code>name</code>, allowing for organization-specific vocabularies to be defined with clear semantics. Any organization that extends OSCAL in this way should consistently assign a <code>ns</code> value that represents the organization, making a given namespace qualified <code>name</code> unique to that organization. This allows the combination of <code>ns</code> and <code>name</code> to always be unique and unambiguous, even when mixed with extensions from other organizations. Each organization is responsible for governance of their own extensions, and is strongly encouraged to publish their extensions as standards to their user community. If no <code>ns</code> is provided, the name is expected to be in the "OSCAL" namespace.</p> <p>To ensure a <code>ns</code> is unique to an organization and naming conflicts are avoided, a URI containing a DNS or other globally defined organization name should be used. For example, if FedRAMP and DoD both extend OSCAL, FedRAMP will use the <code>ns</code> <code>http://fedramp.gov/ns/oscal</code>, while DoD might use the <code>ns</code> <code>https://defense.gov</code> for any organization specific <code>name</code>.</p> <p>Tools that process OSCAL content are not required to interpret unrecognized OSCAL extensions; however, OSCAL compliant tools should not modify or remove unrecognized extensions, unless there is a compelling reason to do so, such as data sensitivity.</p> </remarks> <example> <description>Multiple Parts with Different Organization-Specific Names.</description> <part xmlns="http://csrc.nist.gov/ns/oscal/1.0" name="statement" id="statement-A"> <part ns="http://fedramp.gov/ns/oscal" name="status" id="statement-A-FedRAMP">A requirement specific to FedRAMP stakeholders.</part> <part ns="https://defense.gov" name="status" id="statement-A-DoD">A requirement specific to the Department of Defense stakeholders.</part> </part> </example> </define-assembly>
<!-- ############################################# --> <!-- # Parameter Assembly and related constructs # --> <!-- ############################################# --> <!-- continue here --> <define-assembly name="parameter"> <formal-name>Parameter</formal-name> <description>Parameters provide a mechanism for the dynamic assignment of value(s) in a control.</description> <use-name>param</use-name> <define-flag name="id" as-type="token" required="yes"> <!-- This is an id because the identifier is intended to be human-readable. --> <formal-name>Parameter Identifier</formal-name> <description>A unique identifier for the parameter.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <!-- TODO: What is the semantics of class here? --> <define-flag name="class" as-type="token"> <formal-name>Parameter Class</formal-name> <description>A textual label that provides a characterization of the type, purpose, use or scope of the parameter.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> </remarks> </define-flag> <define-flag name="depends-on" as-type="token" deprecated="1.0.1"> <formal-name>Depends on</formal-name> <description><strong>(deprecated)</strong> Another parameter invoking this one. This construct has been deprecated and should not be used.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <!-- CHANGE: relative order in sequence --> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-field name="label" as-type="markup-line"> <formal-name>Parameter Label</formal-name> <description>A short, placeholder name for the parameter, which can be used as a substitute for a <code>value</code> if no value is assigned.</description> <remarks> <p>The label value is intended use when rendering a parameter in generated documentation or a user interface when a parameter is referenced. Note that labels are not required to be distinctive, which means that parameters within the same control may have the same label.</p> </remarks> </define-field> <define-field name="usage" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Parameter Usage Description</formal-name> <description>Describes the purpose and use of a parameter.</description> </define-field> <assembly ref="parameter-constraint" max-occurs="unbounded"> <use-name>constraint</use-name> <group-as name="constraints" in-json="ARRAY"/> </assembly> <assembly ref="parameter-guideline" max-occurs="unbounded"> <use-name>guideline</use-name> <group-as name="guidelines" in-json="ARRAY"/> </assembly> <choice> <field ref="parameter-value" max-occurs="unbounded"> <use-name>value</use-name> <group-as name="values" in-json="ARRAY"/> <remarks> <p>A set of values provided in a catalog can be redefined in OSCAL's <code>profile</code> or <code>system-security-plan</code> models.</p> </remarks> </field> <assembly ref="parameter-selection"> <use-name>select</use-name> <remarks> <p>The OSCAL parameter <code>value</code> construct can be used to prescribe a specific parameter value in a catalog or profile. In cases where a prescriptive value is not possible in a catalog or profile, it may be possible to constrain the set of possible values to a few options. Use of <code>select</code> in a parameter instead of <code>value</code> is a way of defining value options that <strong>may</strong> be set.</p> <p>A set of allowed parameter values expressed as a set of options which may be selected. These options constrain the permissible values that may be selected for the containing parameter. When the value assignment is made, such as in an OSCAL profile or system security plan, the actual selected value can be examined to determine if it matches one of the permissible choices for the parameter value.</p> <p>When the value of <code>how-many</code> is set to "one-or-more", multiple values may be assigned reflecting more than one choice.</p> </remarks> </assembly> </choice> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-parameter-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-control-group-property-name; <enum value="alt-label">An alternate to the value provided by the parameter's label. This will typically be qualified by a class.</enum> </allowed-values> <allowed-values id="oscal-rmf-parameter-prop-name" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/rmf')]/@name"> <enum value="aggregates">The parent parameter provides an aggregation of two or more other parameters, each described by this property.</enum> </allowed-values> <expect id="oscal-parameter-depends-on-deprecated" target="." test="not(exists(@depends-on))"> <message>depends-on is deprecated</message> </expect> </constraint> <remarks> <p>In a catalog, a parameter is typically used as a placeholder for the future assignment of a parameter value, although the OSCAL model allows for the direct assignment of a value if desired by the control author. The <code>value</code> may be optionally used to specify one or more values. If no value is provided, then it is expected that the value will be provided at the Profile or Implementation layer.</p> <p>A parameter can include a variety of metadata options that support the future solicitation of one or more values. A <code>label</code> provides a textual placeholder that can be used in a tool to solicit parameter value input, or to display in catalog documentation. The <code>desc</code> provides a short description of what the parameter is used for, which can be used in tooling to help a user understand how to use the parameter. A <code>constraint</code> can be used to provide criteria for the allowed values. A <code>guideline</code> provides a recommendation for the use of a parameter.</p> </remarks> </define-assembly>
<define-assembly name="parameter-constraint"> <formal-name>Constraint</formal-name> <description>A formal or informal expression of a constraint or test.</description> <model> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Constraint Description</formal-name> <description>A textual summary of the constraint to be applied.</description> </define-field> <define-assembly name="test" max-occurs="unbounded"> <formal-name>Constraint Test</formal-name> <description>A test expression which is expected to be evaluated by a tool.</description> <group-as name="tests" in-json="ARRAY"/> <model> <define-field name="expression" as-type="string" min-occurs="1"> <formal-name>Constraint test</formal-name> <description>A formal (executable) expression of a constraint.</description> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly> </model> </define-assembly> <define-assembly name="parameter-guideline"> <formal-name>Guideline</formal-name> <description>A prose statement that provides a recommendation for the use of a parameter.</description> <model> <define-field name="prose" as-type="markup-multiline" in-xml="UNWRAPPED" min-occurs="1"> <formal-name>Guideline Text</formal-name> <description>Prose permits multiple paragraphs, lists, tables etc.</description> </define-field> </model> </define-assembly>
<define-field name="parameter-value"> <formal-name>Parameter Value</formal-name> <description>A parameter value or set of values.</description> </define-field>
<define-assembly name="parameter-selection"> <formal-name>Selection</formal-name> <description>Presenting a choice among alternatives.</description> <define-flag name="how-many" as-type="token"> <formal-name>Parameter Cardinality</formal-name> <description>Describes the number of selections that must occur. Without this setting, only one value should be assumed to be permitted.</description> <constraint> <allowed-values id="oscal-parameter-how-many-type"> <enum value="one">Only one value is permitted.</enum> <enum value="one-or-more">One or more values are permitted.</enum> </allowed-values> </constraint> </define-flag> <model> <define-field name="choice" as-type="markup-line" max-occurs="unbounded"> <formal-name>Choice</formal-name> <description>A value selection among several such options.</description> <json-value-key>value</json-value-key> <group-as name="choice" in-json="ARRAY"/> </define-field> </model> <remarks> <p>A set of parameter value choices, that may be picked from to set the parameter value.</p> </remarks> </define-assembly> <!-- ############################## --> <!-- # Control-related constructs # --> <!-- ############################## --> <define-flag name="control-id" as-type="token"> <formal-name>Control Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A reference to a control with a corresponding <code>id</code> value. When referencing an externally defined <code>control</code>, the <code>Control Identifier Reference</code> must be used in the context of the external / imported OSCAL instance (e.g., uri-reference).</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-scope" value="cross-instance"/> </define-flag> <define-assembly name="include-all"> <formal-name>Include All</formal-name> <description>Include all controls from the imported catalog or profile resources.</description> <remarks> <p>This element provides an alternative to calling controls individually from a catalog.</p> </remarks> </define-assembly> <!-- ######################################### --> <!-- # Profile and Mapping common constructs # --> <!-- ######################################### --> <define-flag as-type="string" name="pattern"> <formal-name>Pattern</formal-name> <description>A <a href="https://en.wikipedia.org/wiki/Glob_(programming)">glob expression</a> matching the IDs of one or more controls to be selected.</description> </define-flag> <define-flag as-type="token" name="with-child-controls"> <formal-name>Include Contained Controls with Control</formal-name> <description>When a control is included, whether its child (dependent) controls are also included.</description> <constraint> <allowed-values id="oscal-with-child-controls-values"> <enum value="yes">Include child controls with an included control.</enum> <enum value="no">When importing a control, only include child controls that are also explicitly called.</enum> </allowed-values> </constraint> </define-flag> <define-field name="with-id" as-type="token"> <formal-name>Match Controls by Identifier</formal-name> <description>Selecting a control by its ID given as a literal.</description> </define-field> <define-assembly name="matching"> <formal-name>Match Controls by Pattern</formal-name> <description>Selecting a set of controls by matching their IDs with a wildcard pattern.</description> <flag ref="pattern"/> <model> <!-- Without a model the flags do not get generated in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly> <define-assembly name="select-control-by-id"> <formal-name>Select Control</formal-name> <description>Select a control or controls from an imported control set.</description> <flag ref="with-child-controls"/> <model> <field ref="with-id" max-occurs="unbounded"> <group-as name="with-ids" in-json="ARRAY"/> </field> <assembly ref="matching" max-occurs="unbounded"> <group-as name="matching" in-json="ARRAY"/> </assembly> </model> <remarks> <p>If <code>with-child-controls</code> is <q>yes</q> on the call to a control, no sibling <code>call</code>elements need to be used to call any controls appearing within it. Since generally, this is how control enhancements are represented (as controls within controls), this provides a way to include controls with all their dependent controls (enhancements) without having to call them individually.</p> </remarks> </define-assembly> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-responsible-roles-operations SYSTEM "./shared-constraints/allowed-values-responsible-roles-operations.ent"> <!ENTITY allowed-values-responsible-roles-component-production SYSTEM "./shared-constraints/allowed-values-responsible-roles-component-production.ent"> <!ENTITY allowed-values-property-name-asset-type-values SYSTEM "./shared-constraints/allowed-values-property-name-asset-type-values.ent"> <!ENTITY allowed-values-component_component_property-name SYSTEM "./shared-constraints/allowed-values-component_component_property-name.ent"> <!ENTITY allowed-values-component_component_software SYSTEM "./shared-constraints/allowed-values-component_component_software.ent"> <!ENTITY allowed-values-component_component_service SYSTEM "./shared-constraints/allowed-values-component_component_service.ent"> <!ENTITY allowed-values-component_inventory-item_property-name SYSTEM "./shared-constraints/allowed-values-component_inventory-item_property-name.ent"> <!ENTITY allowed-values-component_component_link-rel SYSTEM "./shared-constraints/allowed-values-component_component_link-rel.ent"> <!ENTITY allowed-values-component-type SYSTEM "./shared-constraints/allowed-values-component-type.ent"> <!ENTITY allowed-values-property-name-networked-components SYSTEM "./shared-constraints/allowed-values-property-name-networked-components.ent"> ]> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema-xslt/support/metaschema/schema/xml/metaschema.xsd" abstract="yes"> <schema-name>OSCAL Implementation Common Information</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-implementation-common</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri>
<import href="oscal_metadata_metaschema.xml"/> <import href="oscal_control-common_metaschema.xml"/>
<!-- ################################################## --> <!-- # The System Component and supporting constructs # --> <!-- ################################################## --> <define-assembly name="system-component"> <formal-name>Component</formal-name> <description>A defined component that can be part of an implemented system.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Component Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this component elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>component</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <flag ref="system-component-type" required="yes"> <!-- CHANGED: "component-type" to "type" --> <use-name>type</use-name> </flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Component Title</formal-name> <description>A human readable name for the system component.</description> </define-field> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Component Description</formal-name> <description>A description of the component, including information about its function.</description> </define-field> <define-field name="purpose" as-type="markup-line"> <formal-name>Purpose</formal-name> <description>A summary of the technological or business purpose of the component.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="status" min-occurs="1"> <formal-name>Status</formal-name> <description>Describes the operational status of the system component.</description> <define-flag name="state" as-type="token" required="yes"> <formal-name>State</formal-name> <description>The operational status.</description> <constraint> <allowed-values id="oscal-component-status-state-values"> <enum value="under-development">The component is being designed, developed, or implemented.</enum> <enum value="operational">The component is currently operational and is available for use in the system.</enum> <enum value="disposition">The component is no longer operational.</enum> <enum value="other">Some other state.</enum> </allowed-values> </constraint> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <assembly ref="protocol" max-occurs="unbounded"> <group-as name="protocols" in-json="ARRAY"/> <remarks> <p>Used for <code>service</code> components to define the protocols supported by the service.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-component-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <!-- names related to inherited component --> <enum value="implementation-point">Relative placement of component ('internal' or 'external') to the system.</enum> <enum value="leveraged-authorization-uuid">UUID of the related leveraged-authorization assembly in this SSP.</enum> <enum value="inherited-uuid">UUID of the component as it was assigned in the leveraged system's SSP.</enum>
<!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== --> &allowed-values-component_inventory-item_property-name;
&allowed-values-component_component_property-name; </allowed-values>
<allowed-values id="oscal-component-link-rel-values" target="link/@rel" allow-other="yes"> <!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- CHANGED (BJR): Done --> <!-- ========================================================================================================== --> &allowed-values-component_component_link-rel; <enum value="uses-network">This component uses the network provided by the identified network component.</enum> <enum value="imported-from">The hyperlink identifies a URI pointing to the <code>component</code> in a <code>component-definition</code> that originally defined the <code>component</code>.</enum> </allowed-values>
<allowed-values id="oscal-component-responsible-role-id-values" target="responsible-role/@role-id" allow-other="yes"> <!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- ========================================================================================================== --> &allowed-values-responsible-roles-operations; &allowed-values-responsible-roles-component-production; </allowed-values>
<allowed-values id="oscal-component-prop-asset-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='asset-type']/@value" allow-other="yes"> &allowed-values-property-name-asset-type-values; </allowed-values>
<allowed-values id="oscal-component-prop-allows-authenticated-scan-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='allows-authenticated-scan']/@value"> <enum value="yes">The component allows an authenticated scan.</enum> <enum value="no">The component does not allow an authenticated scan.</enum> </allowed-values>
<allowed-values id="oscal-component-prop-is-public-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='public']/@value"> <enum value="yes">The component is publicly accessible.</enum> <enum value="no">The component is not publicly accessible.</enum> </allowed-values>
<allowed-values id="oscal-component-prop-is-virtual-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='virtual']/@value"> <enum value="yes">The component is virtualized.</enum> <enum value="no">The component is not virtualized.</enum> </allowed-values>
<allowed-values id="oscal-component-prop-implementation-point-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='implementation-point']/@value"> <enum value="internal">The component is implemented within the system boundary.</enum> <enum value="external">The component is implemented outside the system boundary.</enum> </allowed-values>
<index-has-key id="oscal-component-prop-physical-location" name="index-metadata-location-uuid" target="prop[@name='physical-location']"> <key-field target="@value"/> </index-has-key>
<matches id="oscal-component-inherited-uuid-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='inherited-uuid']/@value" datatype="uuid" /> <matches id="oscal-component-release-date-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='release-date']/@value" datatype="date"/>
<!-- ========================================================================================================== --> <!-- = Changes to the following values need to be synced with component in the SSP and component metaschemas. = --> <!-- ========================================================================================================== -->
<allowed-values id="oscal-component-hardware-service-software-prop-name-values" target="(.)[@type=('software', 'hardware', 'service')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="vendor-name">The name of the company or organization </enum> </allowed-values>
<!-- TODO: Add ipv4-subnet property for type='network' - add pattern constraint --> <!-- TODO: Add ipv6-subnet property for type='network' - add pattern constraint -->
<!-- ========================================================================================================== --> <!-- = VALIDATION: type='validation' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-component-prop-validation-link-rel-values" target="(.)[@type='validation']/link/@rel" allow-other="yes"> <enum value="validation-details">A link to an online information provided by the authorizing body.</enum> </allowed-values>
<!-- ========================================================================================================== --> <!-- = SOFTWARE: type='software' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-component-software-prop-name-values" target="(.)[@type='software']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-component_component_software; </allowed-values>
<!-- ========================================================================================================== --> <!-- = SERVICE: type='service' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-component-service-link-rel-values" target="(.)[@type='service']/link/@rel" allow-other="yes"> &allowed-values-component_component_service; </allowed-values>
<!-- ========================================================================================================== --> <!-- = INTERCONNECTION: type='interconnection' constraints = --> <!-- ========================================================================================================== --> <allowed-values id="oscal-component-interconnection-prop-name-values" target="(.)[@type='interconnection']/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="isa-title">Title of the Interconnection Security Agreement (ISA).</enum> <enum value="isa-date">Date of the Interconnection Security Agreement (ISA).</enum> <enum value="isa-remote-system-name">The name of the remote interconnected system.</enum> &allowed-values-property-name-networked-components; </allowed-values> <allowed-values id="oscal-component-interconnection-service-software-system-prop-name-values" target="(.)[@type=('interconnection', 'service', 'software', 'system')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-property-name-networked-components; </allowed-values> <allowed-values id="oscal-component-prop-ipaddress-class-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name=('ipv4-address','ipv6-address')]/@class"> <enum value="local">The identified IP address is for this system.</enum> <enum value="remote">The identified IP address is for the remote system to which this system is connected.</enum> </allowed-values> <allowed-values id="oscal-component-interconnection-link-rel-values" target="(.)[@type='interconnection']/link/@rel" allow-other="yes"> <!-- CHANGE: @name="agreement" changed to @name="isa-agreement" --> <enum value="isa-agreement">A link to the system interconnection agreement.</enum> </allowed-values> <allowed-values id="oscal-component-interconnection-responsible-role-id-values" target="(.)[@type='interconnection']/responsible-role/@role-id" allow-other="yes"> <enum value="isa-poc-local">Interconnection Security Agreement (ISA) point of contact (POC) for this system.</enum> <enum value="isa-poc-remote">Interconnection Security Agreement (ISA) point of contact (POC) for the remote interconnected system.</enum> <enum value="isa-authorizing-official-local">Interconnection Security Agreement (ISA) authorizing official for this system.</enum> <enum value="isa-authorizing-official-remote">Interconnection Security Agreement (ISA) authorizing official for the remote interconnected system.</enum> </allowed-values> <matches id="oscal-component-prop-isa-date-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='isa-date']/@value" datatype="date-time"/> <matches id="oscal-component-prop-ipv4address-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='ipv4-address']/@value" datatype="ip-v4-address" /> <matches id="oscal-component-prop-ipv6address-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='ipv6-address']/@value" datatype="ip-v6-address" /> <matches id="oscal-component-prop-uri-value-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='uri']/@value" datatype="uri" /> <allowed-values id="oscal-component-prop-direction-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='direction']/@value"> <enum value="incoming">Data from the remote system flows into this system.</enum> <enum value="outgoing">Data from this system flows to the remote system.</enum> </allowed-values> <is-unique id="oscal-unique-system-component-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> <remarks> <p>Components may be products, services, application programming interface (APIs), policies, processes, plans, guidance, standards, or other tangible items that enable security and/or privacy.</p> <p>The <code>type</code> indicates which of these component types is represented.</p> <!-- <p>A group of components may be aggregated into a <code>capability</code>. For example, an account management capability that consists of an account management process, and a Lightweight Directory Access Protocol (LDAP) software implementation.</p> <p>Capabilities are expressed by combining one or more components.</p>--> <p>When defining a <code>service</code> component where are relationship to other components is known, one or more <code>link</code> entries with rel values of provided-by and used-by can be used to link to the specific component identifier(s) that provide and use the service respectively.</p> </remarks> </define-assembly>
<define-flag name="system-component-type" as-type="string"> <formal-name>Component Type</formal-name> <description>A category describing the purpose of the component.</description> <constraint> <allowed-values id="oscal-component-type-values" allow-other="yes"> <enum value="this-system">The system as a whole.</enum> <enum value="system">An external system, which may be a leveraged system or the other side of an interconnection.</enum> &allowed-values-component-type; <enum value="network">A physical or virtual network.</enum> </allowed-values> </constraint> </define-flag>
<define-assembly name="protocol"> <formal-name>Service Protocol Information</formal-name> <description>Information about the protocol used to provide a service.</description> <define-flag name="uuid" as-type="uuid"> <formal-name>Service Protocol Information Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this service protocol information elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>service protocol</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <define-flag name="name"> <formal-name>Protocol Name</formal-name> <description>The common name of the protocol, which should be the appropriate "service name" from the <a href="https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml">IANA Service Name and Transport Protocol Port Number Registry</a>. </description> <remarks> <p>The short name of the protocol (e.g., https).</p> </remarks> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>Protocol Title</formal-name> <description>A human readable name for the protocol (e.g., Transport Layer Security).</description> </define-field> <assembly ref="port-range" max-occurs="unbounded"> <group-as name="port-ranges" in-json="ARRAY"/> </assembly> </model> <constraint> <expect id="oscal-component-protocol-uuid" level="WARNING" target="." test="@uuid"> <message>It is a best practice to provide a UUID.</message> </expect> </constraint> </define-assembly> <define-assembly name="port-range"> <formal-name>Port Range</formal-name> <description>Where applicable this is the transport layer protocol port range an IPv4-based or IPv6-based service uses.</description> <define-flag name="start" as-type="non-negative-integer"> <formal-name>Start</formal-name> <description>Indicates the starting port number in a port range for a transport layer protocol</description> <remarks> <p>Should be a number within a permitted range</p> </remarks> </define-flag> <define-flag name="end" as-type="non-negative-integer"> <formal-name>End</formal-name> <description>Indicates the ending port number in a port range for a transport layer protocol</description> <remarks> <p>Should be a number within a permitted range</p> </remarks> </define-flag> <define-flag name="transport" as-type="token"> <formal-name>Transport</formal-name> <description>Indicates the transport type.</description> <constraint> <allowed-values id="oscal-component-protocol-transport-values"> <enum value="TCP">Transmission Control Protocol</enum> <enum value="UDP">User Datagram Protocol</enum> </allowed-values> </constraint> </define-flag> <model> <!-- Without a model the flags do not get generated in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <expect id="oscal-component-protocol-port-range-has-start" level="WARNING" target="." test="exists(@start)"> <message>A port range should have a start port given.</message> </expect> <expect id="oscal-component-protocol-port-range-has-end" level="WARNING" target="." test="exists(@end)"> <message>A port range should have an end port given. To define a single port, the start and end should be the same value.</message> </expect> <expect id="oscal-component-protocol-port-range-starts-before-end" level="WARNING" target="." test="not(@start > @end)"> <message>The port range start should not be after its end.</message> </expect> </constraint> <remarks> <p>To be validated as a natural number (integer &gt;= 1). A single port uses the same value for start and end. Use multiple 'port-range' entries for non-contiguous ranges.</p> </remarks> <example> <description>Example of protocol and port-range encoding.</description> <service xmlns="http://csrc.nist.gov/ns/oscal/example" id="svc-01" name="Domain Name Service (DNS) Lookup"> <protocol name="dns"> <port-range start="53" end="53" transport="tcp"/> </protocol> </service> </example> </define-assembly>
<define-assembly name="implementation-status"> <formal-name>Implementation Status</formal-name> <description>Indicates the degree to which the a given control is implemented.</description> <define-flag name="state" as-type="token" required="yes"> <formal-name>Implementation State</formal-name> <description>Identifies the implementation status of the control or control objective.</description> <constraint> <allowed-values id="oscal-implementation-status-values" allow-other="yes"> <enum value="implemented">The control is fully implemented.</enum> <enum value="partial">The control is partially implemented.</enum> <enum value="planned">There is a plan for implementing the control as explained in the remarks.</enum> <enum value="alternative">There is an alternative implementation for this control as explained in the remarks.</enum> <enum value="not-applicable">This control does not apply to this system as justified in the remarks.</enum> </allowed-values> </constraint> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- ############################################# --> <!-- # The System User and supporting constructs # --> <!-- ############################################# --> <define-assembly name="system-user"> <formal-name>System User</formal-name> <description>A type of user that interacts with the system based on an associated role.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>User Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this user class elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>system user</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>User Title</formal-name> <description>A name given to the user, which may be used by a tool for display and navigation.</description> </define-field> <define-field name="short-name"> <formal-name>User Short Name</formal-name> <description>A short common name, abbreviation, or acronym for the user.</description> </define-field> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>User Description</formal-name> <description>A summary of the user's purpose within the system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships? (BJR - I don't think we need this now) --> </assembly> <field ref="role-id" min-occurs="0" max-occurs="unbounded"> <group-as name="role-ids" in-json="ARRAY"/> </field> <assembly ref="authorized-privilege" max-occurs="unbounded"> <group-as name="authorized-privileges" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-user-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="type">The type of user, such as internal, external, or general-public.</enum> <enum value="privilege-level">The user's privilege level within the system, such as privileged, non-privileged, no-logical-access.</enum> </allowed-values> <allowed-values id="oscal-user-prop-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type']/@value"> <enum value="internal">A user account for a person or entity that is part of the organization who owns or operates the system.</enum> <enum value="external">A user account for a person or entity that is not part of the organization who owns or operates the system.</enum> <enum value="general-public">A user of the system considered to be outside </enum> </allowed-values> <allowed-values id="oscal-user-prop-privilege-level-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='privilege-level']/@value"> <enum value="privileged">This role has elevated access to the system, such as a group or system administrator.</enum> <enum value="non-privileged">This role has typical user-level access to the system without elevated access.</enum> <enum value="no-logical-access">This role has no access to the system, such as a manager who approves access as part of a process.</enum> </allowed-values> <allowed-values id="oscal-user-role-id-values" target="role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; </allowed-values> </constraint> <remarks> <p>Permissible values to be determined closer to the application, such as by a receiving authority.</p> </remarks> </define-assembly> <define-assembly name="authorized-privilege"> <formal-name>Privilege</formal-name> <description>Identifies a specific system privilege held by the user, along with an associated description and/or rationale for the privilege.</description> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Privilege Title</formal-name> <description>A human readable name for the privilege.</description> </define-field> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Privilege Description</formal-name> <description>A summary of the privilege's purpose within the system.</description> </define-field> <field ref="function-performed" min-occurs="1" max-occurs="unbounded"> <group-as name="functions-performed" in-json="ARRAY"/> </field> </model> </define-assembly> <define-field name="function-performed" as-type="string"> <formal-name>Functions Performed</formal-name> <description>Describes a function performed for a given authorized privilege by this user class.</description> </define-field>
<!-- ################################################ --> <!-- # The Inventory Item and supporting constructs # --> <!-- ################################################ --> <define-assembly name="inventory-item"> <formal-name>Inventory Item</formal-name> <description>A single managed inventory item within the system.</description> <!-- <json-key flag-name="uuid"/> --> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Inventory Item Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this inventory item elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>inventory item</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <!-- CHANGED: Moved to property[@name='asset-id']. --> <!-- <define-flag name="asset-id"> <!-\- This is an id because the identifier is assigned and managed externally. -\-> <formal-name>Asset Identifier</formal-name> <description>Organizational asset identifier that is unique in the context of the system. This may be a reference to the identifier used in an asset tracking system or a vulnerability scanning tool.</description> </define-flag> --> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Inventory Item Description</formal-name> <description>A summary of the inventory item stating its purpose within the system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <define-assembly name="implemented-component" max-occurs="unbounded"> <!-- TODO: Sync constraints with system-component; maybe remove this? (CHANGED (BJR): Dave-See Gitter for details on this. --> <formal-name>Implemented Component</formal-name> <description>The set of components that are implemented in a given system inventory item.</description> <group-as name="implemented-components" in-json="ARRAY"/>
<define-flag required="yes" name="component-uuid" as-type="uuid"> <formal-name>Component Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a <code>component</code> that is implemented as part of an inventory item.</description> </define-flag>
<!-- CHANGED (daw): the following is not needed since it is required on the referenced component --> <!-- <!-\- CHANGED (BJR): Added component-type for alignment with system-component -\-> <flag ref="component-type" required="yes" /> --> <!-- The following is commented because this is not being used and can be inferred based on the type of the component --> <!-- <define-flag name="use"> <formal-name>Implementation Use Type</formal-name> <description>The type of implementation</description> <constraint> <allowed-values allow-other="yes"> <enum value="runs-software">The implemented component is a 'software' component that the inventory item has installed and uses.</enum> <enum value="uses-hardware">The implemented component is a 'hardware' component that the inventory item has installed and uses.</enum> <enum value="enforces-policy">The implemented component is a 'policy' component that the inventory item supports and enforces.</enum> <enum value="implements-process">The implemented component is a 'process' component that the inventory item supports and enforces.</enum> </allowed-values> </constraint> </define-flag> --> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> <remarks> <p>This construct is used to either: 1) associate a party or parties to a role defined on the component using the <code>responsible-role</code> construct, or 2) to define a party or parties that are responsible for a role defined within the context of the containing <code>inventory-item</code>. </p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <!-- TODO: constrain component-uuid references to components defined in the document. ((BJR): Was unsure how to do this.) --> <!-- TODO: constrain link href values based on rel ((BJR): Was unsure of how to do this.) -->
<!-- TODO: constrain property values based on name (CHANGED (BJR): Done.) --> <allowed-values id="oscal-implemented-component-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-component_component_property-name; &allowed-values-component_inventory-item_property-name;
</allowed-values>
<allowed-values id="oscal-implemented-component-responsible-party-role-id-values" target="responsible-party/@role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; </allowed-values>
<!-- TODO: constrain party-id references to parties defined in the document. (BJR Unsure how to do this. )-->
<is-unique id="oscal-unique-implemented-component-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-inventory-item-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="ipv4-address">The Internet Protocol v4 Address of the asset.</enum> <enum value="ipv6-address">The Internet Protocol v6 Address of the asset.</enum> <enum value="fqdn">The full-qualified domain name (FQDN) of the asset.</enum> <enum value="uri">A Uniform Resource Identifier (URI) for the asset.</enum> <enum value="serial-number">A serial number for the asset.</enum> <enum value="netbios-name">The NetBIOS name for the asset.</enum> <enum value="mac-address">The media access control (MAC) address for the asset.</enum> <enum value="physical-location">The physical location of the asset's hardware (e.g., Data Center ID, Cage#, Rack#, or other meaningful location identifiers).</enum> <enum value="is-scanned">is the asset subjected to network scans? (yes/no)</enum> &allowed-values-component_inventory-item_property-name;
</allowed-values> <allowed-values id="oscal-inventory-item-prop-asset-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='asset-type']/@value" allow-other="yes"> &allowed-values-property-name-asset-type-values; </allowed-values>
<allowed-values id="oscal-inventory-item-hardware-service-software-prop-name-values" target="(.)[@type=('software', 'hardware', 'service')]/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="vendor-name">The name of the company or organization </enum> </allowed-values>
<allowed-values id="oscal-inventory-item-prop-is-scanned-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='is-scanned']/@value"> <enum value="yes">The asset is included in periodic vulnerability scanning.</enum> <enum value="no">The asset is not included in periodic vulnerability scanning.</enum> </allowed-values>
<allowed-values id="oscal-inventory-item-link-rel-values" target="link/@rel" allow-other="yes"> <enum value="baseline-template">A reference to the baseline template used to configure the asset.</enum> </allowed-values> <!-- TODO: constrain link href values based on rel ((BJR): Was unsure how to do this.) -->
<allowed-values id="oscal-inventory-item-responsible-party-role-id-values" target="responsible-party/@role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; &allowed-values-responsible-roles-component-production; </allowed-values>
<index-has-key id="oscal-index-inventory-item-responsible-party-role-id" name="index-metadata-role-id" target="responsible-party"> <key-field target="@role-id"></key-field> </index-has-key> <index-has-key id="oscal-index-inventory-item-responsible-party-party-uuid" name="index-metadata-party-uuid" target="responsible-party"> <key-field target="party-uuid"></key-field> </index-has-key> <is-unique id="oscal-unique-inventory-item-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly>
<!-- <define-assembly name="only-statement"> <formal-name>Specific Statement</formal-name> <description>Describes which specific statements are addressed by a requirement, by pointing to a specific requirement statement within a control.</description> <json-key flag-name="statement-id"/> <flag ref="statement-id" required="yes"> <remarks> <p>A reference to the specific implemented statement.</p> </remarks> </flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Statement Implementation Description</formal-name> <description>A description of the component, including information about its function.</description> </define-field> <field ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </field> <assembly ref="property" max-occurs="unbounded"> <group-as name="properties" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-\- TODO: Model specific link relationships ((BJR): Was unsure how to do this.) -\-> </assembly> <!-\- <assembly ref="using"/> -\-> <!-\- TODO: Implement parameters -\-> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly> --> <define-flag name="statement-id" as-type="token"> <formal-name>Control Statement Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a> identifier reference to a <code>control statement</code>.</description> </define-flag> <define-assembly name="set-parameter"> <formal-name>Set Parameter Value</formal-name> <description>Identifies the parameter that will be set by the enclosed value.</description> <flag ref="param-id" required="yes"/> <model> <define-field name="value" as-type="string" min-occurs="1" max-occurs="unbounded"> <!-- CHANGED type from "markup-line" to "string" since this is intended to be a scalar value --> <formal-name>Parameter Value</formal-name> <description>A parameter value or set of values.</description> <group-as name="values" in-json="ARRAY"/> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly>
<!-- ===== FIELDS ===== --> <define-field name="system-id" as-type="string"> <!-- This is an id because the identifier is assigned and managed by humans. --> <formal-name>System Identification</formal-name> <!-- Identifier Declaration --> <!-- TODO: Given feedback, we need to update Metaschema with usnistgov/metaschema#222 with props like in https://github.com/david-waltermire-nist/OSCAL/commit/3aafc080b3dc5f488c15b763f707326e77a61f5d#diff-4176d3cf694dd36b02a94207426934306ec0fdaecc54d1bb96f50f52cd7ceae6R27-R32.
We need to determine if both identifier-type='machine-oriented' and identifier-type='human-oriented'. Option 2 is identifier-type='unspecified'. --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this system identification property elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#scope">this or other OSCAL instances</a>. When referencing an externally defined <code>system identification</code>, the <code>system identification</code> must be used in the context of the external / imported OSCAL instance (e.g., uri-reference). This string should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same system across revisions of the document.</description> <json-value-key>id</json-value-key> <define-flag name="identifier-type" as-type="uri"> <formal-name>Identification System Type</formal-name> <description>Identifies the identification system from which the provided identifier was assigned. </description> <constraint> <allowed-values id="oscal-system-identifier-type-values" allow-other="yes"> <enum value="http://fedramp.gov" deprecated="1.0.3">**deprecated** The identifier was assigned by FedRAMP. This has been deprecated; use <code>http://fedramp.gov/ns/oscal</code> instead.</enum> <enum value="http://fedramp.gov/ns/oscal">The identifier was assigned by FedRAMP.</enum> <enum value="https://ietf.org/rfc/rfc4122" deprecated="1.0.3">**deprecated** A Universally Unique Identifier (UUID) as defined by RFC4122. This value has been deprecated; use <code>http://datatracker.ietf.org/doc/html/rfc4122</code> instead.</enum> <enum value="http://ietf.org/rfc/rfc4122" deprecated="1.1.4">**deprecated** A Universally Unique Identifier (UUID) as defined by RFC4122. This value has been deprecated; use <code>http://datatracker.ietf.org/doc/html/rfc4122</code> instead.</enum> <enum value="http://datatracker.ietf.org/doc/html/rfc4122">A Universally Unique Identifier (UUID) as defined by RFC4122.</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> </define-field>
<!-- ===== FLAGS ===== --> <define-flag name="param-id" as-type="token"> <!-- This is an id because the identifier is assigned and managed by humans. --> <formal-name>Parameter ID</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a> reference to a <code>parameter</code> within a control, who's catalog has been imported into the current implementation context.</description> <example> <description>Example of a human-oriented parameter reference.</description> <set-param xmlns="http://csrc.nist.gov/ns/oscal/example" param-id="ac-2_prm_2"> <enum>System ISSO</enum> </set-param> </example> </define-flag> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema/toolchains/xslt-M4/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!-- OSCAL MAPPING METASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-control-group-property-name SYSTEM "shared-constraints/allowed-values-control-group-property-name.ent"> ]> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:meta="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema/toolchains/xslt-M4/validate/metaschema.xsd"> <schema-name>OSCAL Control Mapping Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-mapping</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL Control mapping format can be used to describe how a collection of security controls and related control enhancements relate to another collection of controls. The root of the Control Catalog format is <code>mapping-collection</code>. </p> </remarks> <import href="oscal_metadata_metaschema.xml"/> <import href="oscal_mapping-common_metaschema.xml"/>
<define-assembly name="mapping-collection"> <formal-name>Mapping Collection</formal-name> <description>A collection of relationship-based control and/or control statement mappings.</description> <root-name>mapping-collection</root-name> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Mapping Collection Universally Unique Identifier</formal-name> <description>A globally unique identifier with cross-instance scope for this catalog instance. This UUID should be changed when this document is revised.</description> </define-flag> <model> <assembly ref="metadata" min-occurs="1"/> <assembly ref="mapping-provenance" min-occurs="1"> <use-name>provenance</use-name> </assembly> <assembly ref="mapping" min-occurs="1" max-occurs="unbounded"> <group-as name="mappings" /> </assembly> <assembly ref="back-matter"> <remarks> <p>Back matter including references and resources.</p> </remarks> </assembly> </model> <remarks> <p>A mapping collection affirmatively declares the relationships that exist between sets of controls and/or control statements in a source and target. It is expected that inferences can be made based on what is mapped; however, no inferences should be made based on what is not mapped, since it is impossible to quantify how complete or granular a given mapping is.</p> </remarks> </define-assembly>
</METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema/toolchains/xslt-M4/validate/metaschema-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!DOCTYPE METASCHEMA [ ]> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema/toolchains/xslt-M4/validate/metaschema.xsd" abstract="yes"> <schema-name>OSCAL Mapping Model -- Common Models</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-mapping-common</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri>
<import href="oscal_metadata_metaschema.xml" /> <import href="oscal_control-common_metaschema.xml"/>
<!-- #################### --> <!-- ASSEMBLY DEFINITIONS --> <!-- #################### -->
<define-assembly name="mapping"> <formal-name>Control Mapping</formal-name> <description>A mapping between two target resources.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Mapping Universally Unique Identifier</formal-name> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented"> machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance"> cross-instance</a> scope that can be used to reference this mapping definition elsewhere in this or other OSCAL instances. The locally defined <em>UUID</em> of the <code> mapping</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency"> per-subject</a>, which means it should be consistently used to identify the same mapping across revisions of the document.</description> </define-flag> <flag ref="method" required="no" /> <flag ref="matching-rationale" required="no" /> <flag ref="status" required="no" /> <model> <assembly ref="mapping-resource-reference" min-occurs="1"> <use-name>source-resource</use-name> </assembly> <assembly ref="mapping-resource-reference" min-occurs="1"> <use-name>target-resource</use-name> </assembly> <assembly ref="map" min-occurs="1" max-occurs="unbounded"> <group-as name="maps" in-json="ARRAY" /> </assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY" /> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY" /> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> <field ref="mapping-description" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> <assembly ref="gap-summary"> <use-name>source-gap-summary</use-name> </assembly> <assembly ref="gap-summary"> <use-name>target-gap-summary</use-name> </assembly> <assembly ref="confidence-score" min-occurs="0" max-occurs="1" /> <field ref="coverage" min-occurs="0" max-occurs="1" /> </model> </define-assembly>
<define-assembly name="map"> <formal-name>Mapping Entry</formal-name> <description>A relationship-based mapping between a source and target set consisting of members (i.e., controls, control statements) from the respective source and target.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Mapping Entry Identifier</formal-name> <description>The unique identifier for the mapping entry.</description> </define-flag> <define-flag name="ns" as-type="uri" default="http://csrc.nist.gov/ns/oscal"> <formal-name>Relationship Value Namespace</formal-name> <description>A namespace qualifying the relationship's value. This allows different organizations to associate distinct semantics for relationships with the same name.</description> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code> http://csrc.nist.gov/ns/oscal</code> and the name should be a name defined by the associated OSCAL model.</p> </remarks> </define-flag> <flag ref="matching-rationale" required="no" /> <model> <define-field name="relationship" as-type="token" min-occurs="1"> <formal-name>Mapping Entry Relationship</formal-name> <description>The relationship type for the mapping entry, which describes the relationship between the effective requirements of the specified source and target sets in the context of the <code>matching-rationale</code> method globaly defined in the <code>provenance</code> unless overwritten locally in the <code> map</code>. The <code>relationship</code> type and the <code>matching-rationale</code> must be used together. However, more than one <code>matching-rationale</code> method may apply to a <code>source</code> and <code>target</code> pair. </description> <json-value-key>type</json-value-key> <constraint> <allowed-values target=".[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]"> <enum value="equivalent-to">The <code>source</code> and <code>target</code> requirements are similar, although not necessarily identical. The words may differ, but both mapped sets convey similar information with the same effective meaning. This relationship may be reversed, since `A equivalent-to B` also means that `B equivalent-to A`. This relationship is less suitable for a <em>syntactic</em> <code>matching-rationale</code> .</enum> <enum value="equal-to">The <code>source</code> and <code>target</code> requirements are the same. Differences in capitalization, spelling, and grammar can be ignored, if these differences do not change the meaning. This relationship may be reversed, since `A equal-to B` also means that `B equal-to A`.</enum> <enum value="subset-of">The <code>source</code> requirements are a subset of <code> target</code> requirements. In other words, <code>target</code> contains all <code>source</code>requirements and aditional others. This relationship may be reversed as a `superset-of`, since `A subset-of B` also means that `B superset-of A`.</enum> <enum value="superset-of">The <code>source</code> requirements are a superset of <code>target</code> requirements. In other words, <code> source</code> contains all <code>target</code>requirements and aditional others. This relationship may be reversed as a `subset-of`, since `A superset-of B` also means that `B subset-of A`.</enum> <enum value="intersects-with">The <code>source</code> and <code>target</code> requirements have some overlap, but each includes content that the other does not. This relationship may be reversed, since `A intersects-with B` also means that `B intersects-with A`. A mapping at statement level could result on <code>relationships</code> mapping that allows for more inference than using this relationship type.</enum> <enum value="no-relationship">The <code>source</code> and <code>target</code> requirements are not related; their content does not overlap. This relation is introduced not with the intention to support exhaustiv mapping of all requirements and statements that have no overlap, but rather to support edge cases such is the need to tailor a <code> relationship</code> in the context of a component or system to better align with the implementation and configuration of the respective component or system. Also, this <code>relationship</code> is provided in support of the <a href="https://doi.org/10.6028/NIST.IR.8477">NIST IR 8477</a>.</enum> </allowed-values> </constraint> <remarks> <p>For example, consider the CSF 1.1's PR.AC-1, "Identities and credentials are issued, managed, verified, revoked, and audited for authorized devices, users and processes", and the Privacy Framework's PR.AC-P1, "Identities and credentials are issued, managed, verified, and devices." </p> <p>These two requirements have identical wording except for "users” versus “individuals” and the order of the last few words. With a `matching-rationale` of syntactic, the relationship type would beintersects with because the two overlap, but each includes content that the other does not. However, with a rationale of semantic, the relationship type would be equal if “users” and “individuals” have the same meaning in their respective sources, subset if “users” was a subset of “individuals,” and so on.</p> <p>When establishing relationships, mapping SHOULD be done at the control statement level where possible. This approach allows for a more accurate relationship.</p> </remarks> </define-field>
<assembly ref="mapping-item" min-occurs="1" max-occurs="unbounded"> <use-name>source</use-name> <group-as name="sources" in-json="ARRAY" /> </assembly> <assembly ref="mapping-item" min-occurs="1" max-occurs="unbounded"> <use-name>target</use-name> <group-as name="targets" in-json="ARRAY" /> </assembly> <assembly ref="qualifier-item" min-occurs="0" max-occurs="unbounded"> <use-name>qualifier</use-name> <group-as name="qualifiers" in-json="ARRAY" /> </assembly> <assembly ref="confidence-score" min-occurs="0" max-occurs="1" /> <field ref="coverage" min-occurs="0" max-occurs="1" /> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY" /> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY" /> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> </model> </define-assembly>
<define-assembly name="mapping-item"> <formal-name>Mapping Entry Item (source or target)</formal-name> <description>A specific edge within a source or target that is the subject of a mapping.</description> <define-flag name="type" as-type="token" required="yes"> <formal-name>Subject Type</formal-name> <description>The semantic type of the subject.</description> <constraint> <allowed-values> <enum value="control">A control as <a href="https://pages.nist.gov/OSCAL/concepts/terminology/#control"> defined</a> by OSCAL.</enum> <enum value="statement">A textual element of a control that defines part of the control's requirements.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="id-ref" as-type="string" required="yes"> <formal-name>Subject Identifier Reference</formal-name> <description>A reference to an identified subject that is of the specified <code>type</code> .</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY" /> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY" /> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> </model> </define-assembly>
<define-assembly name="mapping-resource-reference"> <formal-name>Mapped Resource Reference</formal-name> <description>A reference to a resource that is either the source or the target of a mapping.</description> <define-flag name="ns" as-type="uri" default="http://csrc.nist.gov/ns/oscal" required="no"> <formal-name>Resource Type Namespace</formal-name> <description>An optional namespace qualifying the resource's <code>type</code>. </description> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code>http://csrc.nist.gov/ns/oscal</code> and the type should be a type defined by the associated OSCAL model.</p> </remarks> </define-flag> <define-flag name="type" as-type="token" required="yes"> <formal-name>Resource Type</formal-name> <description>The semantic type of the resource.</description> <constraint> <allowed-values allow-other="yes"> <enum value="catalog">The mapped resource is a control catalog.</enum> <enum value="profile">The mapped resource is a control profile. A resolved profile is also accepted.</enum> </allowed-values> </constraint> <remarks> <p>The <code>type</code> value must be interpreted in the context of the associated <code>ns</code> value.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code>http://csrc.nist.gov/ns/oscal</code> and this type should be set to one of the OSCAL defined values.</p> </remarks> </define-flag> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Catalog or Profile Reference</formal-name> <description>A resolvable URL reference to the base catalog or profile that this profile is tailoring.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY" /> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY" /> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> </model> </define-assembly>
<!-- Original <qualifier subject=“source|target|both” predicate=“has-requirement|has-incompatibility” category=“restricted|addressable|blocked”> Description of qualifier... </qualifier> -->
<define-assembly name="qualifier-item"> <formal-name>Relationship Qualifier</formal-name> <description>Describes requirements, incompatibilities and gaps that are identified between a target and source in a mapping item.</description> <define-flag name="subject" required="yes" as-type="string"> <formal-name>Subject</formal-name> <description>The focus of the qualifier.</description> <constraint> <allowed-values> <enum value="source">This qualifier is related to the source in the mapped relationship.</enum> <enum value="target">This qualifier is related to the target in the mapped relationship.</enum> <enum value="both">This qualifier is related to both the source and target in the mapped relationship.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="predicate" required="yes" as-type="string"> <formal-name>Predicate</formal-name> <description>The predicate describes how the qualifer applies to the subject.</description> <constraint> <allowed-values> <enum value="has-requirement">The subject has a requirement that must be met for the relationship to be satisfied.</enum> <enum value="has-incompatibility">The subject has an incompatibility which impacts the relationship.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="category" required="yes" as-type="string"> <formal-name>Category</formal-name> <description>The category expresses the resolvable nature of the predicate.</description> <constraint> <allowed-values> <enum value="restricted">A restriction exists, and is defined in the description.</enum> <enum value="addressable">The qualifier is addressable, and is outlined in the description.</enum> <enum value="blocked">The mapping is blocked due to the reason noted in the description.</enum> </allowed-values> </constraint> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Description of the qualifier</formal-name> <description>Details that outline what requirements must be met, or cannot be met. If the qualifier identifies a gap, this should idenfity the gap, and any incompatibilities.</description> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER" /> </model> </define-assembly>
<!-- <provenance responsible-parties="" method=“human|automation” matching=“lexical|logical|semantic|etc” confidence-score="" status=“complete|not-complete|draft|deprecated|superseded|etc”> Description of context and intended use... </provenance> -->
<define-assembly name="mapping-provenance"> <formal-name>Mapping Provenance</formal-name> <description>Describes requirements, incompatibilities and gaps that are identified between a target and source in a mapping item.</description> <flag ref="method" required="yes" /> <flag ref="matching-rationale" required="yes" /> <flag ref="status" required="yes" /> <model> <assembly ref="confidence-score" min-occurs="0" max-occurs="1" /> <field ref="coverage" min-occurs="0" max-occurs="1" /> <!-- define-field name="mapping-description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Mapping Description</formal-name> <description>Description of the context and intended use of the mapping set.</description> </define-field --> <!-- mapping-description had conflicting cardinality, with min-occurs=0 and min-occurs=1 see above and below. MUST REVIEW WITH THE OF --> <field ref="mapping-description" in-xml="WITH_WRAPPER" min-occurs="1" max-occurs="1" /> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY" /> </assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY" /> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY" /> </assembly> <!-- field ref="mapping-description" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" / --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1" /> </model> </define-assembly>
<!-- Original <qualifier subject=“source|target|both” predicate=“has-requirement|has-incompatibility” category=“restricted|addressable|blocked”> Description of qualifier... </qualifier> -->
<define-assembly name="gap-summary"> <formal-name>Gap Summary</formal-name> <description>A <em>by-id</em> collection of all controls that were not mapped at all in this <code> mapping-collection</code>. If a control is partially mapped, the parts of the control are not mappable, the gap and discrepancies should be documented in the <code> relationship-gal</code>. </description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Gap Summary Universally Unique Identifier</formal-name> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented"> machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance"> cross-instance</a> scope that can be used to reference this mapping gap summary elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>SSP</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance).This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency"> per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="select-control-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>unmapped-controls</use-name> <group-as name="unmapped-controls" in-json="ARRAY" /> <remarks> <p>If <code>with-child-controls</code> is <q>yes</q> on the call to a control, any controls appearing within it (child controls) will be selected, with no additional <code>call</code> directives required. This flag provides a way to include controls with all their dependent controls (enhancements) without having to call them individually.</p> </remarks> </assembly> </model> </define-assembly>
<!-- NOTE: there is another select-control-by-id defined locally in assessment but it is NOT identical with the one in profile and mapping. Moved the local definition of the select-control-by-id assembly to control-common file --> <!-- NOTE: NOT clear the selection of controls using pattern matching is needed. If NOT needed, we can simplify but this assembly will be similar to the assessment-common one and cannot be moved. --> <!-- define-assembly name="select-control-by-id" > <formal-name>Select Control</formal-name> <description>Select a control or controls from an imported control set.</description> <flag ref="with-child-controls" /> <model> <define-field name="with-id" as-type="token" max-occurs="unbounded"> <formal-name>Match Controls by Identifier</formal-name> <description>Selecting a control by its ID given as a literal.</description> <group-as name="with-ids" in-json="ARRAY" /> </define-field> <assembly ref="matching" max-occurs="unbounded"> <group-as name="matching" in-json="ARRAY" /> </assembly> </model> <remarks> <p>If <code>with-child-controls</code> is <q>yes</q> on the call to a control, no sibling <code>call</code>elements need to be used to call any controls appearing within it. Since generally, this is how control enhancements are represented (as controls within controls), this provides a way to include controls with all their dependent controls (enhancements) without having to call them individually.</p> </remarks> </define-assembly -->
<!-- NOTE: Similar assembly named matching is defined in profile. --> <!-- Mover the assembly's definition to control-common file--> <!-- define-assembly name="matching" > <formal-name>Match Controls by Pattern</formal-name> <description>Selecting a set of controls by matching their IDs with a wildcard pattern.</description> <flag ref="pattern" /> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly -->
<define-assembly name="confidence-score" > <formal-name>Confidence Score</formal-name> <description>This records either a string category or a decimal value from 0-1 representing a percentage. Both of these values describe an estimation of the author's confidence that this mapping is correct and accurate. </description> <model> <choice> <define-field name="category" as-type="string" > <constraint> <allowed-values target=".[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]" allow-other="yes"> <enum value="unspecified">No category is specified for the confidence score.</enum> <enum value="high">High confidence in the mapping.</enum> <enum value="medium">Medium confidence in the mapping.</enum> <enum value="low">Low confidence in the mapping.</enum> </allowed-values> </constraint> </define-field> <field ref="percentage" /> </choice> </model> </define-assembly>
<!-- The coverage defined as field with flag with the intention of representing it as <coverage generation-method="arbitrary">0.85</coverage> does not convert clean oin the JSON schema - it adds STRVALUE to store the value of the named field. A representation like <coverage value="0.85" generation-method="arbitrary"/> <coverage generation-method="arbitrary"/></coverage>is generated with an assembly in metaschema definition and converts clean to JSON --> <!-- define-assembly name="coverage" > <formal-name>Coverage</formal-name> <description>A decimal value from 0-1, representing the percentage coverage of the targets by the sources.</description> <define-flag name="generation-method" as-type="string" required="no" default="arbitrary"> <constraint> <allowed-values allow-other="yes"> <enum value="arbitrary">The coverage value is a qualitative estimate of coverage with no strict formula.</enum> </allowed-values> </constraint> </define-flag> <model> <field ref="percentage" min-occurs="1" max-occurs="1" /> </model> <remarks> <p>This field is scoped - that is, it can be used at the document-level, the mapping level, or the individual map item level. It only applies to targets and sources within it's scope.</p> <p>Coverage is calculated by taking the full set of all targets in-scope and the full set of all sources in-scope, then applying the "generation-method" to the two sets. By default the method is an arbitrary estimation of coverage.</p> <p>In a general sense "coverage" is defined as the percent of the set of targets that have mapped to by the set of sources, where each map is an "equivalent-to" or "equal-to" valued "relationship". Where relationship is "subset-of" or otherwise, it counts as an appropriate fraction of a full map. </p> <p> Since coverage is derived from mapping relationships, it is defined in the context of the mapping's "matching-rationale" - that is, the method used to determine relationships.</p> </remarks> </define-assembly -->
<!-- ################# --> <!-- FIELD DEFINITIONS --> <!-- ################# -->
<!-- This definition as field for hte confidence-score does not represent correctly the TWG intentions of having either a string or a decimal, no other values. Changed it above to an assembly with a choice between the two fields, each with the appropriate constraints. --> <!-- define-field name="confidence-score" as-type="string-or-decimal"> <formal-name>Confidence Score</formal-name> <description>This records either a string category or a decimal value from 0-1 representing a percentage. Both of these values describe an estimation of the author's confidence that this mapping is correct and accurate. </description> <define-flag name="category" as-type="string" required="no"> <constraint> <allowed-values allow-other="yes"> <enum value="unspecified">No category is specified for the confidence score.</enum> <enum value="high">High confidence in the mapping.</enum> <enum value="medium">Medium confidence in the mapping.</enum> <enum value="low">Low confidence in the mapping.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="percentage" as-type="decimal" required="no"/> </define-field -->
<define-field name="coverage" as-type="decimal" > <formal-name>Coverage</formal-name> <description>A decimal value from 0-1, representing the percentage coverage of the targets by the sources.</description> <json-value-key>target-coverage</json-value-key> <define-flag name="generation-method" as-type="string" required="no" default="arbitrary"> <formal-name>Coverage Generation Method</formal-name> <description>The method used to determine the coverage value.</description> <constraint> <allowed-values id="oscal-mapping-coverage-generation-method-values" allow-other="yes"> <enum value="arbitrary">The coverage value is a qualitative estimate of coverage with no strict formula.</enum> </allowed-values> </constraint> </define-flag> <remarks> <p>This field is scoped - that is, it can be used at the document-level, the mapping level, or the individual map item level. It only applies to targets and sources within it's scope.</p> <p>Coverage is calculated by taking the full set of all targets in-scope and the full set of all sources in-scope, then applying the "generation-method" to the two sets. By default the method is an arbitrary estimation of coverage.</p> <p>In a general sense "coverage" is defined as the percent of the set of targets that have mapped to by the set of sources, where each map is an "equivalent-to" or "equal-to" valued "relationship". Where relationship is "subset-of" or otherwise, it counts as an appropriate fraction of a full map. </p> <p> Since coverage is derived from mapping relationships, it is defined in the context of the mapping's "matching-rationale" - that is, the method used to determine relationships.</p> </remarks> </define-field >
<define-field name="percentage" as-type="decimal"> <formal-name>Percentage</formal-name> <description>A decimal value from 0-1, representing a percentage.</description> </define-field>
<define-field name="mapping-description" as-type="markup-multiline"> <formal-name>Mapping Description</formal-name> <description>Description of the context and intended use of the mapping set.</description> <remarks> <p>The value of this field applies to the entire document if found in the top-level mapping provenance, otherwise it applies to the specific mapping in which it is found.</p> <p>If this field appears in both locations, the lower-scoped value overrides while within it's scope.</p> </remarks> </define-field>
<!-- ################ --> <!-- FLAG DEFINITIONS --> <!-- ################ --> <define-flag name="matching-rationale" as-type="string"> <formal-name>Matching</formal-name> <description>The method used for relating controls within the mapping. The supported methods are aligned with the <a href=" https://doi.org/10.6028/NIST.IR.8477">NIST Interagency Report (IR) 8477</a>, Section 4.3 Set Theory Relationship Mapping.</description> <constraint> <allowed-values> <enum value="syntactic">Syntactic: How similar is the <em>wording</em> that expresses the two concepts. This is a word-for-word analysis of the relationship, not an interpretation of the language.</enum> <enum value="semantic">Semantic: How similar are the <em>meanings</em> of the two concepts? This involves some interpretation of each concept’s language.</enum> <enum value="functional">Functional: How similar are the <em>results</em> of executing the two concepts? This involves understanding what will happen if the two concepts are implemented, performed, or otherwise executed.</enum> </allowed-values> </constraint> <remarks> <p>The value of this flag applies to the entire document if found in the top-level mapping provenance, otherwise it applies to the specific mapping in which it is found.</p> <p>If this flag appears in both locations, the lower-scoped value overrides while within it's scope.</p> </remarks> </define-flag>
<define-flag name="status" as-type="string"> <formal-name>Status</formal-name> <description>The current status of this mapping document.</description> <constraint> <allowed-values> <enum value="complete">Complete</enum> <enum value="not-complete">Not Complete</enum> <enum value="draft">Draft</enum> <enum value="deprecated">Deprecated</enum> <enum value="superseded">Superseded</enum> </allowed-values> </constraint> <remarks> <p>The value of this flag applies to the entire document if found in the top-level mapping provenance, otherwise it applies to the specific mapping in which it is found.</p> <p>If this flag appears in both locations, the lower-scoped value overrides while within it's scope.</p> </remarks> </define-flag>
<define-flag name="method" as-type="string"> <formal-name>Method</formal-name> <description>The method used to complete the overall mapping.</description> <constraint> <allowed-values> <enum value="human">Human</enum> <enum value="automation">Automation</enum> <enum value="hybrid">Hybrid</enum> </allowed-values> </constraint> <remarks> <p>The value of this flag applies to the entire document if found in the top-level mapping provenance, otherwise it applies to the specific mapping in which it is found.</p> <p>If this flag appears in both locations, the lower-scoped value overrides while within it's scope.</p> </remarks> </define-flag>
<!-- Updated the name of the flag to avoid conflict in the complete schema with the "patern" defined in oscal_profile_metaschema.xml --> <define-flag as-type="string" name="match-pattern"> <formal-name>Matching Pattern</formal-name> <description>A <a href="https://en.wikipedia.org/wiki/Glob_(programming)">glob expression</a> matching the IDs of one or more controls to be selected.</description> </define-flag>
<!-- Updated the name of the flag to avoid conflict in the complete schema with the "with-child-control" defined in oscal_profile_metaschema.xml --> <define-flag as-type="token" name="match-with-child-controls"> <formal-name>Include Contained Controls with Control</formal-name> <description>When a control is included, whether its child (dependent) controls are also included.</description> <constraint> <allowed-values> <enum value="yes">Include child controls with an included control.</enum> <enum value="no">When importing a control, only include child controls that are also explicitly called.</enum> </allowed-values> </constraint> </define-flag>
</METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!-- OSCAL CATALOG METASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <?xml-stylesheet type="text/css" href="metaschema-author.css"?> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" abstract="yes"> <schema-name>OSCAL Document Metadata Description</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-metadata</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri>
<!-- ############################################### --> <!-- # Metadata Assembly and supporting constructs # --> <!-- ############################################### --> <define-assembly name="metadata"> <formal-name>Document Metadata</formal-name> <description>Provides information about the containing document, and defines concepts that are shared across the document.</description> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Document Title</formal-name> <description>A name given to the document, which may be used by a tool for display and navigation.</description> </define-field> <field ref="published"/> <field ref="last-modified" min-occurs="1"/> <field ref="version" min-occurs="1"/> <field ref="oscal-version" min-occurs="1"/> <define-assembly name="revision" max-occurs="unbounded"> <formal-name>Revision History Entry</formal-name> <description>An entry in a sequential list of revisions to the containing document, expected to be in reverse chronological order (i.e. latest first).</description> <group-as name="revisions" in-xml="GROUPED" in-json="ARRAY"/> <model> <define-field name="title" as-type="markup-line"> <formal-name>Document Title</formal-name> <description>A name given to the document revision, which may be used by a tool for display and navigation.</description> </define-field> <field ref="published" /> <field ref="last-modified"/> <field ref="version" min-occurs="1"/> <field ref="oscal-version"/> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <!-- TODO: consider making this a warning <has-cardinality target="published|last-modified|link[@rel='canonical']" min-occurs="1"/> --> <allowed-values id="oscal-metadata-revision-link-rel-types" target="link/@rel" allow-other="yes"> <enum value="canonical">The link identifies the authoritative location for this resource. Defined by <a href="https://tools.ietf.org/html/rfc6596">RFC 6596</a>.</enum> <enum value="alternate">The link identifies an alternative location or format for this resource. Defined by <a href="https://html.spec.whatwg.org/multipage/links.html#linkTypes">the HTML Living Standard</a></enum> <enum value="predecessor-version">This link identifies a resource containing the predecessor version in the version history. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> <enum value="successor-version">This link identifies a resource containing the predecessor version in the version history. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> <enum value="version-history">This link identifies a resource containing the version history of this document. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> </allowed-values> <!-- TODO: check for if the last-modified is >= the latest revision. --> </constraint> <remarks> <p>While <code>published</code>, <code>last-modified</code>, and <code>oscal-version</code> are not required, values for these entries should be provided if the information is known. A <code>link</code> with a <code>rel</code> of <q>source</q> should be provided if the information is known.</p> </remarks> </define-assembly> <field ref="document-id" max-occurs="unbounded"> <group-as name="document-ids" in-json="ARRAY"/> </field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="role" max-occurs="unbounded"> <formal-name>Role</formal-name> <description>Defines a function, which might be assigned to a party in a specific situation.</description> <group-as name="roles" in-json="ARRAY"/> <define-flag name="id" as-type="token" required="yes"> <!-- Identifier Declarations --> <formal-name>Role Identifier</formal-name> <description>A unique identifier for the role.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> <!-- TODO: discuss overriding of locally defined values. --> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Role Title</formal-name> <description>A name given to the role, which may be used by a tool for display and navigation.</description> </define-field> <define-field name="short-name"> <formal-name>Role Short Name</formal-name> <description>A short common name, abbreviation, or acronym for the role.</description> </define-field> <!-- CHANGE "desc" to "description" --> <define-field name="description" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Role Description</formal-name> <description>A summary of the role's purpose and associated responsibilities.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <!-- TODO: Add support for builtin objects --> <!-- <builtins> <role id="creator"> <title>Document Created By Party </title> <short-name>Document Creator</short-name> <description> <p>Indicates the person or organization that created this content.</p> </description> </role> <role id="prepared-by"> <title>Prepared by Party</title> <short-name>Prepared By</short-name> <description> <p>Indicates the person or organization that prepared this content.</p> </description> </role> <role id="prepared-for"> <title>Prepared for Party</title> <short-name>Prepared For</short-name> <description> <p>Indicates the person or organization for which this content was created.</p> </description> </role> <role id="content-approver"> <title>Approved by Party</title> <short-name>Content Approver</short-name> <description> <p>Indicates the person or organization responsible for all content represented in the "document".</p> </description> </role> <role id="contact"> <title>Document Contact</title> <short-name>Contact</short-name> <description> <p>Indicates the person or organization to contact for questions or support related to this content.</p> </description> </role> </builtins> --> <remarks> <!-- TODO: roles only appear in metadata. Referenced in the document and linked instances. --> <!-- TODO: discuss built-in roles. --> <p>Permissible values to be determined closer to the application (e.g. by a receiving authority).</p> <p>OSCAL has defined a set of standardized roles for consistent use in OSCAL documents. This allows tools consuming OSCAL content to infer specific semantics when these roles are used. These roles are documented in the specific contexts of their use (e.g., responsible-party, responsible-role). When using such a role, it is necessary to define these roles in this list, which will then allow such a role to be referenced.</p> </remarks> </define-assembly> <define-assembly name="location" max-occurs="unbounded"> <formal-name>Location</formal-name> <description>A physical point of presence, which may be associated with people, organizations, or other concepts within the current or linked OSCAL document.</description> <group-as name="locations" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Location Universally Unique Identifier</formal-name> <description>A unique ID for the location, for reference.</description> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>Location Title</formal-name> <description>A name given to the location, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="address"> <remarks> <p>The physical address of the location, which will provided for physical locations. Virtual locations can omit this data item.</p> </remarks> </assembly> <field ref="email-address" max-occurs="unbounded"> <group-as name="email-addresses" in-json="ARRAY"/> <remarks> <p>A contact email associated with the location.</p> </remarks> </field> <field ref="telephone-number" max-occurs="unbounded"> <group-as name="telephone-numbers" in-json="ARRAY"/> <remarks> <p>A phone number used to contact the location.</p> </remarks> </field> <define-field name="url" as-type="uri" max-occurs="unbounded" deprecated="1.1.0"> <formal-name>Location URL</formal-name> <description>The uniform resource locator (URL) for a web site or other resource associated with the location.</description> <group-as name="urls" in-json="ARRAY"/> <remarks> <p>This data field is deprecated in favor of using a link with an appropriate relationship.</p> </remarks> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-metadata-location-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="type">Characterizes the kind of location.</enum> </allowed-values> <allowed-values id="oscal-metadata-location-prop-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type']/@value" allow-other="yes"> <enum value="data-center">A location that contains computing assets. A <code>class</code> can be used to indicate the sub-type of data-center as <em>primary</em> or <em>alternate</em>.</enum> </allowed-values> <allowed-values id="oscal-metadata-location-prop-type-data-center-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type' and @value='data-center']/@class" allow-other="yes"> <enum value="primary">The location is a data-center used for normal operations.</enum> <enum value="alternate">The location is a data-center used for fail-over or backup operations.</enum> </allowed-values> <has-cardinality id="oscal-metadata-location-address-cardinality" target="address" level="WARNING" min-occurs="1"> <description>In most cases, it is useful to define a location. In some cases, defining an explicit location may represent a security risk.</description> </has-cardinality> <has-cardinality id="oscal-metadata-location-title-address-email-address-telephone-cardinality" target="title|address|email-address|telephone-number" level="ERROR" min-occurs="1"> <description>A location must have at least a title, address, email-address, or telephone number.</description> </has-cardinality> </constraint> <remarks> <p>An address might be sensitive in nature. In such cases a title, mailing address, email-address, and/or phone number may be used instead.</p> </remarks> </define-assembly> <define-assembly name="party" max-occurs="unbounded"> <formal-name>Party</formal-name> <description>An organization or person, which may be associated with roles or other concepts within the current or linked OSCAL document.</description> <group-as name="parties" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Party Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A unique identifier for the party.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="type" as-type="string" required="yes"> <formal-name>Party Type</formal-name> <description>A category describing the kind of party the object describes.</description> <constraint> <allowed-values id="oscal-metadata-party-type-values"> <enum value="person">A human being regarded as an individual.</enum> <enum value="organization">An organized group of one or more <code>person</code> individuals with a specific purpose.</enum> </allowed-values> </constraint> </define-flag> <model> <define-field name="name"> <formal-name>Party Name</formal-name> <description>The full name of the party. This is typically the legal name associated with the party.</description> </define-field> <define-field name="short-name"> <formal-name>Party Short Name</formal-name> <description>A short common name, abbreviation, or acronym for the party.</description> </define-field> <define-field name="external-id" max-occurs="unbounded"> <!-- This is an id because the identifier is assigned and managed externally by humans. --> <formal-name>Party External Identifier</formal-name> <description>An identifier for a person or organization using a designated scheme. e.g. an Open Researcher and Contributor ID (ORCID).</description> <json-value-key>id</json-value-key> <group-as name="external-ids" in-json="ARRAY"/> <define-flag name="scheme" as-type="uri" required="yes"> <formal-name>External Identifier Schema</formal-name> <description>Indicates the type of external identifier.</description> <constraint> <allowed-values id="oscal-metadata-party-external-id-values" allow-other="yes"> <enum value="http://orcid.org/">The identifier is Open Researcher and Contributor ID (ORCID).</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="email-address" max-occurs="unbounded"> <group-as name="email-addresses" in-json="ARRAY"/> <remarks> <p>This is a contact email associated with the party.</p> </remarks> </field> <field ref="telephone-number" max-occurs="unbounded"> <group-as name="telephone-numbers" in-json="ARRAY"/> <remarks> <p>A phone number used to contact the party.</p> </remarks> </field> <choice> <assembly ref="address" max-occurs="unbounded"> <group-as name="addresses" in-json="ARRAY"/> </assembly> <field ref="location-uuid" max-occurs="unbounded"> <group-as name="location-uuids" in-json="ARRAY"/> </field> </choice> <define-field name="member-of-organization" as-type="uuid" max-occurs="unbounded"> <formal-name>Organizational Affiliation</formal-name> <!-- Identifier Reference --> <description>A reference to another <code>party</code> by UUID, typically an organization, that this subject is associated with.</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-scope" value="cross-instance"/> <group-as name="member-of-organizations" in-json="ARRAY"/> <constraint> <!-- TODO: Move to top-level to address cross-document issues. --> <index-has-key id="oscal-index-metadata-party-organizations-uuid" name="index-metadata-party-organizations-uuid" target="."> <key-field target="."/> </index-has-key> </constraint> <remarks> <p>Since the reference target of an organizational affiliation must be another <code>party</code> (whether further qualified as person or organization) as indicated by its <code>uuid</code>. As a <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented" >machine-oriented</a> identifier with uniqueness across document and trans-document scope, this <code>uuid</code> value is sufficient to reference the data item locally or globally across related documents, e.g., in an imported OSCAL instance. </p> <p>Parties of both the <code>person</code> or <code>organization</code> type can be associated with an organization using the <code>member-of-organization</code>.</p> </remarks> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-metadata-party-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="mail-stop">A mail stop associated with the party.</enum> <enum value="office">The name or number of the party's office.</enum> <enum value="job-title">The formal job title of a person.</enum> </allowed-values> </constraint> <remarks> <p>A party can be optionally associated with either an address or a location. While providing a meaningful location for a party is desired, there are some cases where it might not be possible to provide an exact location or even any location.</p> </remarks> </define-assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <assembly ref="action" max-occurs="unbounded"> <group-as name="actions" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <index id="oscal-index-metadata-roles" name="index-metadata-role-ids" target="role"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@id"/> </index> <is-unique id="oscal-unique-metadata-doc-id" target="document-id"> <!-- CHANGE: Fixing field name @type -> @scheme --> <key-field target="@scheme"/> <key-field target="."/> </is-unique> <is-unique id="oscal-unique-metadata-property" target="prop"> <key-field target="@name"/> <key-field target="@ns"/> <key-field target="@class"/> <key-field target="@group"/> <key-field target="@value"/> </is-unique> <index id="oscal-index-metadata-property-uuid" name="index-metadata-property-uuid" target=".//prop"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@uuid"/> </index> <is-unique id="oscal-unique-metadata-link" target="link"> <key-field target="@href"/> <key-field target="@rel"/> <key-field target="@media-type"/> </is-unique> <index id="oscal-index-metadata-role-id" name="index-metadata-role-id" target="role"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@id"/> <!-- <builtin> <o:role id="prepared-by"> <o:title>Document Preparer</o:title> </o:role> </builtin> --> </index> <index id="oscal-index-metadata-location-uuid" name="index-metadata-location-uuid" target="location"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@uuid"/> </index> <index id="oscal-index-metadata-party-uuid" name="index-metadata-party-uuid" target="party"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@uuid"/> </index> <index id="oscal-index-metadata-party-organizations-uuid" name="index-metadata-party-organizations-uuid" target="party[@type='organization']"> <!-- TODO: Should this be unique across the document and all imported documents? --> <key-field target="@uuid"/> </index> <is-unique id="oscal-unique-metadata-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> <allowed-values id="oscal-metadata-responsible-party-role-ids" target="responsible-party/@role-id" allow-other="yes"> <enum value="creator">Indicates the person or organization that created this content.</enum> <enum value="prepared-by">Indicates the person or organization that prepared this content.</enum> <enum value="prepared-for">Indicates the person or organization for which this content was created.</enum> <enum value="content-approver">Indicates the person or organization responsible for all content represented in the "document".</enum> <enum value="contact">Indicates the person or organization to contact for questions or support related to this content.</enum> </allowed-values> <allowed-values id="oscal-metadata-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="keywords">The value identifies a comma-seperated listing of keywords associated with this content. These keywords may be used as search terms for indexing and other applications.</enum> </allowed-values> <allowed-values id="oscal-metadata-link-rel-values" target="link/@rel" allow-other="yes"> <enum value="canonical">The link identifies the authoritative location for this resource. Defined by <a href="https://tools.ietf.org/html/rfc6596">RFC 6596</a>.</enum> <enum value="alternate">The link identifies an alternative location or format for this resource. Defined by <a href="https://html.spec.whatwg.org/multipage/links.html#linkTypes">the HTML Living Standard</a></enum> <enum value="latest-version">This link identifies a resource containing the latest version in the version history. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> <enum value="predecessor-version">This link identifies a resource containing the predecessor version in the version history. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> <enum value="successor-version">This link identifies a resource containing the predecessor version in the version history. Defined by <a href="https://tools.ietf.org/html/rfc5829">RFC 5829</a>.</enum> </allowed-values> <is-unique id="oscal-metadata-unique-document-id" target="document-id"> <key-field target="@scheme"/> <key-field target="."/> <remarks> <p>The combination of <code>scheme</code> and the field value must be unique.</p> </remarks> </is-unique> </constraint> <remarks> <p>All OSCAL documents use the same metadata structure, that provides a consistent way of expressing OSCAL document metadata across all OSCAL models. The metadata section also includes declarations of individual objects (i.e., roles, location, parties) that may be referenced within and across linked OSCAL documents.</p> <p>The metadata in an OSCAL document has few required fields, representing only the bare minimum data needed to differentiate one instance from another. Tools and users creating OSCAL documents may choose to use any of the optional fields, as well as extension mechanisms (e.g., properties, links) to go beyond this minimum to suit their use cases.</p> <p>A publisher of OSCAL content can use the <code>published</code>, <code>last-modified</code>, and <code>version</code> fields to establish information about an individual in a sequence of successive revisions of a given OSCAL-based publication. The metadata for a previous revision can be represented as a <code>revision</code> within this object. Links may also be provided using the <code>predecessor-version</code> and <code>successor-version</code> link relations to provide for direct access to the related resource. These relations can be provided as a link child of this object or as <code>link</code> within a given <code>revision</code>.</p> <p>A <code>responsible-party</code> entry in this context refers to roles and parties that have responsibility relative to the production, review, publication, and use of the containing document.</p> </remarks> </define-assembly>
<define-field name="location-uuid" as-type="uuid"> <formal-name>Location Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>Reference to a location by UUID.</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-scope" value="cross-instance"/> <constraint> <index-has-key id="oscal-index-metadata-location-uuid" name="index-metadata-location-uuid" target="."> <!-- TODO: This is impacted by cross-document cross-references We need to relocate or localize this constraint. --> <key-field target="."/> </index-has-key> </constraint> </define-field>
<define-field name="party-uuid" as-type="uuid"> <formal-name>Party Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>Reference to a party by UUID.</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-scope" value="cross-instance"/> <constraint> <index-has-key id="oscal-index-metadata-party-uuid" name="index-metadata-party-uuid" target="."> <!-- TODO: This is impacted by cross-document cross-references We need to relocate or localize this constraint. --> <key-field target="."/> </index-has-key> </constraint> </define-field>
<define-field name="role-id" as-type="token"> <formal-name>Role Identifier Reference</formal-name> <!-- Identifier Reference --> <description>Reference to a role by UUID.</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-scope" value="cross-instance"/> <constraint> <index-has-key id="oscal-index-metadata-role-id" name="index-metadata-role-id" target="."> <!-- TODO: This is impacted by cross-document cross-references We need to relocate or localize this constraint. --> <key-field target="."/> </index-has-key> </constraint> </define-field>
<!-- ############################################### --> <!-- # Back Matter Assembly and related constructs # --> <!-- ############################################### --> <define-assembly name="back-matter"> <formal-name>Back matter</formal-name> <description>A collection of resources that may be referenced from within the OSCAL document instance.</description> <model> <define-assembly name="resource" max-occurs="unbounded"> <formal-name>Resource</formal-name> <description>A resource associated with content in the containing document instance. A resource may be directly included in the document using base64 encoding or may point to one or more equivalent internet resources.</description> <group-as name="resources" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Resource Universally Unique Identifier</formal-name> <description>A unique identifier for a resource.</description> <!-- identifier declaration --> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>Resource Title</formal-name> <description>An optional name given to the resource, which may be used by a tool for display and navigation.</description> </define-field> <define-field name="description" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>Resource Description</formal-name> <description>An optional short summary of the resource used to indicate the purpose of the resource.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <field ref="document-id" max-occurs="unbounded"> <group-as name="document-ids" in-json="ARRAY"/> </field> <define-assembly name="citation"> <formal-name>Citation</formal-name> <description>An optional citation consisting of end note text using structured markup.</description> <model> <define-field name="text" as-type="markup-line" min-occurs="1"> <formal-name>Citation Text</formal-name> <description>A line of citation text.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> </model> </define-assembly> <define-assembly name="rlink" max-occurs="unbounded"> <formal-name>Resource link</formal-name> <description>A URL-based pointer to an external resource with an optional hash for verification and change detection.</description> <group-as name="rlinks" in-json="ARRAY"/> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Hypertext Reference</formal-name> <description>A resolvable URL pointing to the referenced resource.</description> <remarks> <p>This value may be either:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> </ol> </remarks> </define-flag> <flag ref="media-type"/> <model> <field ref="hash" max-occurs="unbounded"> <description>A hash of the resource identified by <code>href</code>, which can be used to verify the resource was not changed since it was hashed.</description> <group-as name="hashes" in-json="ARRAY"/> <remarks> <p>The <code>hash</code> value can be used to confirm that the resource referenced by the <code>href</code> is the same resources that was hashed by retrieving the resource, calculating a hash, and comparing the result to this value.</p> </remarks> </field> </model> <remarks> <p>Multiple <code>rlink</code> objects can be included for a resource. In such a case, all provided <code>rlink</code> items are intended to be equivalent in content, but may differ in structure or format.</p> <p>A <code>media-type</code> is used to identify the format of a given rlink, and can be used to differentiate items in a collection of rlinks. The <code>media-type</code> provides a hint to the OSCAL document consumer about the structure of the resource referenced by the <code>rlink</code>. </p> </remarks> </define-assembly>
<define-field name="base64" as-type="base64"> <formal-name>Base64</formal-name> <description>A resource encoded using the Base64 alphabet defined by <a href="https://www.rfc-editor.org/rfc/rfc2045.html">RFC 2045</a>.</description> <json-value-key>value</json-value-key> <define-flag name="filename" as-type="token"> <formal-name>File Name</formal-name> <description>Name of the file before it was encoded as Base64 to be embedded in a <code>resource</code>. This is the name that will be assigned to the file when the file is decoded.</description> </define-flag> <flag ref="media-type"/> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER"/> <!-- <any/> --> </model> <constraint> <allowed-values id="oscal-back-matter-resource-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="type">Identifies the type of resource represented. The most specific appropriate type value SHOULD be used.</enum> <enum value="version">For resources representing a published document, this represents the version number of that document.</enum> <enum value="published">For resources representing a published document, this represents the publication date of that document.</enum> </allowed-values> <matches id="oscal-back-matter-resource-prop-published-datatype" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='published']/@value" datatype="date-time-with-timezone"/> <allowed-values id="oscal-back-matter-resource-prop-type-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='type']/@value"> <!-- More general. Applies across all models. --> <enum value="logo">Indicates the resource is an organization's logo.</enum> <enum value="image">Indicates the resource represents an image.</enum> <enum value="screen-shot">Indicates the resource represents an image of screen content. </enum> <enum value="law">Indicates the resource represents an applicable law.</enum> <enum value="regulation">Indicates the resource represents an applicable regulation.</enum> <enum value="standard">Indicates the resource represents an applicable standard.</enum> <enum value="external-guidance">Indicates the resource represents applicable guidance.</enum> <enum value="acronyms">Indicates the resource provides a list of relevant acronyms.</enum> <enum value="citation">Indicates the resource cites relevant information.</enum> <!-- More related to implementation layer. --> <enum value="policy">Indicates the resource is a policy.</enum> <enum value="procedure">Indicates the resource is a procedure.</enum> <enum value="system-guide">Indicates the resource is guidance document related to the subject system of an SSP.</enum> <enum value="users-guide">Indicates the resource is guidance document a user's guide or administrator's guide.</enum> <enum value="administrators-guide">Indicates the resource is guidance document a administrator's guide.</enum> <enum value="rules-of-behavior">Indicates the resource represents rules of behavior content.</enum> <enum value="plan">Indicates the resource represents a plan.</enum> <!-- More related to assessment layers. --> <enum value="artifact">Indicates the resource represents an artifact, such as may be reviewed by an assessor.</enum> <enum value="evidence">Indicates the resource represents evidence, such as to support an assessment finding.</enum> <enum value="tool-output">Indicates the resource represents output from a tool.</enum> <enum value="raw-data">Indicates the resource represents machine data, which may require a tool or analysis for interpretation or presentation.</enum> <enum value="interview-notes">Indicates the resource represents notes from an interview, such as may be collected during an assessment.</enum> <enum value="questionnaire">Indicates the resource is a set of questions, possibly with responses.</enum> <enum value="report">Indicates the resource is a report.</enum> <enum value="agreement">Indicates the resource is a formal agreement between two or more parties.</enum> </allowed-values> <has-cardinality id="oscal-back-matter-resource-base64-rlink-cardinality" level="WARNING" target="rlink|base64" min-occurs="1"> <description>A resource should provide at least an <code>rlink</code> or <code>base64</code> object.</description> </has-cardinality> <is-unique id="oscal-unique-resource-rlink-href" target="rlink"> <description>Ensure that each rlink item references a unique resource.</description> <key-field target="@href"/> <key-field target="@media-type"/> </is-unique> <is-unique id="oscal-unique-resource-base64-filename" target="base64"> <description>Ensure that all base64 resources have a unique <code>filename</code>.</description> <key-field target="@filename"/> </is-unique> <expect id="oscal-back-matter-resource-citation-title" target=".[citation]" test="title"> <description>A <code>title</code> is required when a <code>citation</code> is provided.</description> </expect> </constraint> <remarks> <!-- TODO: state that at least one rlink and/or base64 should be provided. --> <p>A resource can be used in two ways. 1) it may point to an specific retrievable network resource using a <code>rlink</code>, or 2) it may be included as an attachment using a <code>base64</code>. A resource may contain multiple <code>rlink</code> and <code>base64</code> entries that represent alternative download locations (rlink) and attachments (base64) for the same resource.</p> <p>Both rlink and base64 allow for a <code>media-type</code> to be specified, which is used to distinguish between different representations of the same resource (e.g., Microsoft Word, PDF). When multiple <code>rlink</code> and <code>base64</code> items are included for a given resource, all items must contain equivalent information. This allows the document consumer to choose a preferred item to process based on a the selected item's <code>media-type</code>. This is extremely important when the items represent OSCAL content that is represented in alternate formats (i.e., XML, JSON, YAML), allowing the same OSCAL data to be processed from any of the available formats indicated by the items.</p> <p>When a resource includes a citation, then the <code>title</code> and <code>citation</code> properties must both be included.</p> </remarks> </define-assembly> </model> <constraint> <index id="oscal-back-matter-resource-uuid-index" name="index-back-matter-resource" target="resource"> <key-field target="@uuid"/> </index> </constraint> <remarks> <p>Provides a collection of identified <code>resource</code> objects that can be referenced by a <code>link</code> with a <code>rel</code> value of "reference" and an <code>href</code> value that is a fragment "#" followed by a reference to a reference's <code>uuid</code>. Other specialized link "rel" values also use this pattern when indicated in that context of use.</p> </remarks> <example> <!-- TODO: revisit this example --> <description>Use of link, citation, and resource</description> <remarks> <p>The following is a contrived example to show the use of link, citation, and resource.</p> </remarks> <o:profile xmlns:o="http://csrc.nist.gov/ns/oscal/example"> <o:metadata> <o:link rel="citation" href="#a53da8f9-4182-4f11-9d1f-50f08ac2117b">My citation</o:link> </o:metadata> <o:back-matter> <o:resource uuid="a53da8f9-4182-4f11-9d1f-50f08ac2117b"> <o:rlink href="https://example.org/some-resource"/> </o:resource> </o:back-matter> </o:profile> </example> </define-assembly>
<!-- ##################### --> <!-- # Global constructs # --> <!-- ##################### --> <define-assembly name="property"> <formal-name>Property</formal-name> <description>An attribute, characteristic, or quality of the containing object expressed as a namespace qualified name/value pair.</description> <use-name>prop</use-name> <define-flag name="name" as-type="token" required="yes"> <formal-name>Property Name</formal-name> <description>A textual label, within a namespace, that identifies a specific attribute, characteristic, or quality of the property's containing object.</description> </define-flag> <define-flag name="uuid" as-type="uuid"> <formal-name>Property Universally Unique Identifier</formal-name> <!-- identifier declaration --> <description>A unique identifier for a property.</description> </define-flag> <define-flag name="ns" as-type="uri" default="http://csrc.nist.gov/ns/oscal"> <formal-name>Property Namespace</formal-name> <description>A namespace qualifying the property's name. This allows different organizations to associate distinct semantics with the same name.</description> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> <p>When a <code>ns</code> is not provided, its value should be assumed to be <code>http://csrc.nist.gov/ns/oscal</code> and the name should be a name defined by the associated OSCAL model.</p> </remarks> </define-flag> <define-flag name="value" as-type="string" required="yes"> <formal-name>Property Value</formal-name> <description>Indicates the value of the attribute, characteristic, or quality.</description> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Property Class</formal-name> <description>A textual label that provides a sub-type or characterization of the property's <code>name</code>.</description> <remarks> <p>This can be used to further distinguish or discriminate between the semantics of multiple properties of the same object with the same <code>name</code> and <code>ns</code>, or to group properties into categories.</p> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value. It is available for grouping, but unlike <code>group</code> is not expected specifically to designate any group membership as such.</p> </remarks> </define-flag> <define-flag name="group" as-type="token"> <formal-name>Property Group</formal-name> <description>An identifier for relating distinct sets of properties.</description> <remarks> <p>Different sets of properties may relate to separate contexts. Declare a group on a property to associate it with one or more other properties in a given context.</p> </remarks> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-metadata-prop-name-values" target=".[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="marking">A label or descriptor that is tied to a sensitivity or classification marking system. An optional class can be used to define the specific marking system used for the associated value.</enum> </allowed-values> </constraint> <remarks> <p>Properties permit the deployment and management of arbitrary controlled values, within OSCAL objects. A property can be included for any purpose useful to an application or implementation. Typically, properties will be used to sort, filter, select, order, and arrange OSCAL content objects, to relate OSCAL objects to one another, or to associate an OSCAL object to class hierarchies, taxonomies, or external authorities. Thus, the lexical composition of properties may be constrained by external processes to ensure consistency.</p> <p>Property allows for associated remarks that describe why the specific property value was applied to the containing object, or the significance of the value in the context of the containing object.</p> </remarks> </define-assembly>
<define-assembly name="link"> <formal-name>Link</formal-name> <description>A reference to a local or remote resource, that has a specific relation to the containing object.</description> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Hypertext Reference</formal-name> <description>A resolvable URL reference to a resource.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to an OSCAL object by the objects identifier (e.g., id, uuid) in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>). The specific object type will differ based on the link relationship type.</li> </ol> </remarks> </define-flag> <define-flag name="rel" as-type="token"> <formal-name>Link Relation Type</formal-name> <description>Describes the type of relationship provided by the link's hypertext reference. This can be an indicator of the link's purpose.</description> <constraint> <allowed-values id="oscal-metadata-link-rel-values" allow-other="yes"> <enum value="reference">A generalized reference to a network resource (relative or absolute) or to a <code>back-matter</code> resource by UUID expressed as a bare URI fragment.</enum> </allowed-values> </constraint> </define-flag> <flag ref="media-type"> <formal-name>Link Media Type</formal-name> <remarks> <p>The <code>media-type</code> provides a hint about the content model of the referenced resource. A valid entry from the <a href="https://www.iana.org/assignments/media-types/media-types.xhtml">IANA Media Types registry</a> SHOULD be used.</p> </remarks> </flag> <define-flag name="resource-fragment" as-type="string"> <formal-name>Resource Fragment</formal-name> <description>In case where the <code>href</code> points to a <code>back-matter/resource</code>, this value will indicate the URI <a href="https://www.rfc-editor.org/rfc/rfc3986#section-3.5">fragment</a> to append to any <code>rlink</code> associated with the resource. This value MUST be <a href="https://www.rfc-editor.org/rfc/rfc3986#section-2.1">URI encoded</a>.</description> </define-flag> <model> <define-field name="text" as-type="markup-line"> <formal-name>Link Text</formal-name> <description>A textual label to associate with the link, which may be used for presentation in a tool.</description> </define-field> </model> <constraint> <expect id="oscal-metadata-link-uri-reference-no-media-type" target=".[starts-with(@href,'#')]" test="not(exists(@media-type))"> <description>A local reference SHOULD NOT have a media-type.</description> <remarks> <p>Since both <code>link</code> and <code>back-matter/resource</code> both allow specification of a <code>media-type</code>, the <code>media-type</code> on <code>link</code> may conflict with the any <code>media-type</code> entries on a resource's <code>rlink</code> or <code>base64</code> objects. This constraint prevents this from occurring.</p> </remarks> </expect> <matches id="oscal-metadata-link-reference-href-datatype-uri-reference" target=".[@rel=('reference') and starts-with(@href,'#')]/@href" datatype="uri-reference"/> <index-has-key id="oscal-metadata-link-reference-index-back-matter-resource" name="index-back-matter-resource" target=".[@rel=('reference') and starts-with(@href,'#')]"> <key-field target="@href" pattern="#(.*)"/> </index-has-key> <matches id="oscal-metadata-link-reference-href-datatype-uri" target=".[@rel=('reference') and not(starts-with(@href,'#'))]/@href" datatype="uri"/> <matches id="oscal-metadata-link-resource-fragment-datatype" target="@resource-fragment" regex="(?:[0-9a-zA-Z-._~/?!$&amp;'()*+,;=:@]|%[0-9A-F][0-9A-F])+"> <remarks> <p>This pattern is based on the fragment Augmented Backus-Naur form (ABNF) syntax provided in [RFC3986 section 3.5](https://www.rfc-editor.org/rfc/rfc3986#section-3.5). Uppercase alpha hex digits are required, which is the preferred normalized form defined in RFC3986.</p> </remarks> </matches> </constraint> <remarks> <p>To provide a cryptographic hash for a remote target resource, a local reference to a back matter <code>resource</code> is needed. The resource allows one or more hash values to be provided using the <code>rlink/hash</code> object.</p> <p>The OSCAL <code>link</code> is a roughly based on the HTML <a href="https://www.w3.org/TR/html401/struct/links.html#edef-LINK">link element</a>. </p> </remarks> <example> <description>Providing for link integrity</description> <remarks> <p>The following is a contrived example to show the use of link, citation, and resource.</p> </remarks> <o:oscal xmlns:o="http://csrc.nist.gov/ns/oscal/example"> <o:link rel="reference" href="#resource1">My Hashed Resource</o:link> ...snip... <o:back-matter> <o:resource id="resource1"> <o:rlink href="https://example.org/some-resource"> <o:hash algorithm="sha512">C2E9C1..snip..F88D2E</o:hash> </o:rlink> </o:resource> </o:back-matter> </o:oscal> </example> </define-assembly>
<define-assembly name="responsible-party"> <formal-name>Responsible Party</formal-name> <description>A reference to a set of persons and/or organizations that have responsibility for performing the referenced role in the context of the containing object.</description> <define-flag required="yes" name="role-id" as-type="token"> <formal-name>Responsible Role</formal-name> <!-- Identifier Reference --> <description>A reference to a <code>role</code> performed by a <code>party</code>.</description> <prop name="value-type" value="identifier-reference"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-scope" value="cross-instance"/> </define-flag> <model> <field ref="party-uuid" min-occurs="1" max-occurs="unbounded"> <description>Specifies one or more parties responsible for performing the associated <code>role</code>.</description> <group-as name="party-uuids" in-json="ARRAY"/> </field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <index-has-key id="oscal-metadata-responsible-party-index-metadata-role-id" name="index-metadata-role-id" target="."> <key-field target="@role-id"/> </index-has-key> </constraint> <remarks> <p>A <code>responsible-party</code> requires one or more <code>party-uuid</code> references creating a strong relationship arc between the referenced <code>role-id</code> and the reference parties. This differs in semantics from <code>responsible-role</code> which doesn't require that a <code>party-uuid</code> is referenced.</p> <p>The scope of use of this object determines if the responsibility has been performed or will be performed in the future. The containing object will describe the intent.</p> </remarks> </define-assembly>
<define-assembly name="action"> <formal-name>Action</formal-name> <description>An action applied by a role within a given party to the content.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Action Universally Unique Identifier</formal-name> <description>A unique identifier that can be used to reference this defined action elsewhere in an OSCAL document. A UUID should be consistently used for a given location across revisions of the document.</description> </define-flag> <define-flag name="date" as-type="date-time-with-timezone"> <formal-name>Action Occurrence Date</formal-name> <description>The date and time when the action occurred.</description> </define-flag> <define-flag name="type" as-type="token" required="yes"> <formal-name>Action Type</formal-name> <description>The type of action documented by the assembly, such as an approval.</description> </define-flag> <define-flag name="system" as-type="uri" required="yes"> <formal-name>Action Type System</formal-name> <description>Specifies the action type system used.</description> <remarks> <p>Provides a means to segment the value space for the <code>type</code>, so that different organizations and individuals can assert control over the allowed <code>action</code>'s <code>type</code>. This allows the semantics associated with a given <code>type</code> to be defined on an organization-by-organization basis.</p> <p>An organization MUST use a URI that they have control over. e.g., a domain registered to the organization in a URI, a registered uniform resource names (URN) namespace.</p> </remarks> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <index-has-key id="oscal-metadata-action-name-index-metadata-role-id" name="index-metadata-role-id" target="responsible-party"> <key-field target="@role-id"/> </index-has-key> <index-has-key id="oscal-metadata-action-name-index-metadata-party-uuid" name="index-metadata-party-uuid" target="responsible-party"> <key-field target="party-uuid"/> </index-has-key> <allowed-values id="oscal-metadata-action-system-values" target="./system/@value" allow-other="yes"> <enum value="http://csrc.nist.gov/ns/oscal">This value identifies action types defined in the NIST OSCAL namespace.</enum> </allowed-values> <allowed-values id="oscal-metadata-action-type-values" target="./type[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@value"> <enum value="approval">An approval of a document instance's content.</enum> <enum value="request-changes">A request from the responsible party or parties to change the content.</enum> </allowed-values> </constraint> </define-assembly>
<define-assembly name="responsible-role"> <formal-name>Responsible Role</formal-name> <description>A reference to a role with responsibility for performing a function relative to the containing object, optionally associated with a set of persons and/or organizations that perform that role.</description> <define-flag name="role-id" as-type="token" required="yes"> <formal-name>Responsible Role ID</formal-name> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a> identifier reference to a <code>role</code> performed.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="party-uuid" max-occurs="unbounded"> <description>Specifies zero or more parties responsible for performing the associated <code>role</code>.</description> <group-as name="party-uuids" in-json="ARRAY"/> </field> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <remarks> <p>A <code>responsible-role</code> allows zero or more <code>party-uuid</code> references, each of which creates a relationship arc between the referenced <code>role-id</code> and the referenced party. This differs in semantics from <code>responsible-party</code>, which requires that at least one <code>party-uuid</code> is referenced.</p> <p>The scope of use of this object determines if the responsibility has been performed or will be performed in the future. The containing object will describe the intent.</p> </remarks> </define-assembly>
<define-field name="hash"> <!-- TODO: need a hex binary type. --> <formal-name>Hash</formal-name> <description>A representation of a cryptographic digest generated over a resource using a specified hash algorithm.</description> <json-value-key>value</json-value-key> <define-flag name="algorithm" as-type="string" required="yes"> <formal-name>Hash algorithm</formal-name> <description>The digest method by which a hash is derived.</description> <constraint> <allowed-values id="oscal-back-matter-resource-hash-algorithm-values" allow-other="yes"> <enum value="SHA-224">The SHA-224 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.180-4">NIST FIPS 180-4</a>. </enum> <enum value="SHA-256">The SHA-256 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.180-4">NIST FIPS 180-4</a>. </enum> <enum value="SHA-384">The SHA-384 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.180-4">NIST FIPS 180-4</a>. </enum> <enum value="SHA-512">The SHA-512 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.180-4">NIST FIPS 180-4</a>. </enum> <enum value="SHA3-224">The SHA3-224 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.202">NIST FIPS 202</a>. </enum> <enum value="SHA3-256">The SHA3-256 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.202">NIST FIPS 202</a>. </enum> <enum value="SHA3-384">The SHA3-384 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.202">NIST FIPS 202</a>. </enum> <enum value="SHA3-512">The SHA3-512 algorithm as defined by <a href="https://doi.org/10.6028/NIST.FIPS.202">NIST FIPS 202</a>. </enum> </allowed-values> </constraint> <remarks> <p>Any other value used MUST be a value defined in the W3C <a href="https://www.w3.org/TR/xmlsec-algorithms/#digest-method-uris">XML Security Algorithm Cross-Reference</a> Digest Methods (W3C, April 2013) or <a href="https://tools.ietf.org/html/rfc6931#section-2.1.5">RFC 6931 Section 2.1.5</a> New SHA Functions.</p> </remarks> </define-flag> <constraint> <matches id="oscal-check-hash-length-SHA2-3-224" target=".[@algorithm=('SHA-224','SHA3-224')]" regex="^[0-9a-fA-F]{56}$"/> <matches id="oscal-check-hash-length-SHA2-3-256" target=".[@algorithm=('SHA-256','SHA3-256')]" regex="^[0-9a-fA-F]{64}$"/> <matches id="oscal-check-hash-length-SHA2-3-384" target=".[@algorithm=('SHA-384','SHA3-384')]" regex="^[0-9a-fA-F]{96}$"/> <matches id="oscal-check-hash-length-SHA2-3-512" target=".[@algorithm=('SHA-512','SHA3-512')]" regex="^[0-9a-fA-F]{128}$"/> </constraint> </define-field>
<define-flag name="media-type" as-type="string"> <formal-name>Media Type</formal-name> <description>A label that indicates the nature of a resource, as a data serialization or format.</description> <remarks> <p> The Internet Assigned Numbers Authority (IANA) <a href="https://www.iana.org/assignments/media-types/media-types.xhtml">Media Types Registry</a> defines a standardized set of media types, which may be used here.</p> <p>The <code>application/oscal+xml</code>, <code>application/oscal+json</code> or <code>application/oscal+yaml</code> media types SHOULD be used when referencing OSCAL XML, JSON, or YAML resources respectively.</p> <p>**Note: There is no official media type for YAML at this time.** OSCAL documents should specify <code>application/yaml</code> for general YAML content, or <code>application/oscal+yaml</code> for YAML-based OSCAL content. This approach aligns with use of a structured name suffix, per <a href="https://www.rfc-editor.org/rfc/rfc6838.html#section-4.2.8">RFC 6838 Section 4.2.8</a>.</p> <p>Some earlier OSCAL content incorporated the model into the media type. For example: <code>application/oscal.catalog+xml</code>. This practice SHOULD be avoided, since the OSCAL model can be detected by parsing the initial content of the referenced resource.</p> </remarks> </define-flag>
<define-field name="remarks" as-type="markup-multiline"> <formal-name>Remarks</formal-name> <description>Additional commentary about the containing object.</description> <remarks> <p>The <code>remarks</code> field SHOULD not be used to store arbitrary data. Instead, a <code>prop</code> or <code>link</code> should be used to annotate or reference any additional data not formally supported by OSCAL.</p> </remarks> </define-field>
<!-- #################### --> <!-- # Local constructs # --> <!-- #################### --> <define-field name="published" as-type="date-time-with-timezone" scope="local"> <formal-name>Publication Timestamp</formal-name> <description>The date and time the document was last made available.</description> <remarks> <p>Typically, this date value will be machine-generated at the time the containing document is published.</p> <p>In some cases, an OSCAL document may be derived from some source material provided in a different format. In such a case, the <code>published</code> value should indicate when the OSCAL document instance was last published, not the source material.</p> <!-- TODO: (AJ) State how to do the following: Where necessary, the publication date of the original source material can be captured as a named property. Define the link relation, and document here how to do this. --> </remarks> </define-field>
<define-field name="last-modified" as-type="date-time-with-timezone" scope="local"> <formal-name>Last Modified Timestamp</formal-name> <description>The date and time the document was last stored for later retrieval.</description> <remarks> <p>This value represents the point in time when the OSCAL document was last updated, or at the point of creation the creation date. Typically, this date value will be machine generated at time of creation or modification. Ideally, this field will be managed by the editing tool or service used to make modifications when storing the modified document.</p> <p>The intent of the last modified timestamp is to distinguish between significant change milestones when the document may be accessed by multiple entities. This allows a given entity to differentiate between multiple document states at specific points in time. It is possible to make multiple modifications to the document without storing these changes. In such a case, the last modified timestamp might not be updated until the document is finally stored.</p> <p>In some cases, an OSCAL document may be derived from some source material in a different format. In such a case, the <code>last-modified</code> value should indicate the last modification time of the OSCAL document instance, not the source material.</p> </remarks> </define-field> <define-field name="version" scope="local"> <formal-name>Document Version</formal-name> <description>Used to distinguish a specific revision of an OSCAL document from other previous and future versions.</description> <remarks> <p>A version may be a release number, sequence number, date, or other identifier sufficient to distinguish between different document revisions.</p> <p>While not required, it is recommended that OSCAL content authors use <a href="https://semver.org/spec/v2.0.0.html">Semantic Versioning</a> as the version format. This allows for the easy identification of a version tree consisting of major, minor, and patch numbers.</p> <p>A version is typically set by the document owner or by the tool used to maintain the content.</p> </remarks> </define-field> <define-field name="oscal-version" scope="local"> <formal-name>OSCAL Version</formal-name> <description>The OSCAL model version the document was authored against and will conform to as valid.</description> <remarks> <p>Indicates the version of the OSCAL model to which the document conforms, for example <q>1.1.0</q> or <q>1.0.0-milestone1</q>. That can be used as a hint for a tool indicating which version of the OSCAL XML or JSON schema to use for validation.</p> <p>The OSCAL version serves a different purpose from the document version and is used to represent a different concept. If both have the same value, this is coincidental.</p> </remarks> </define-field>
<define-field name="email-address" as-type="email-address" scope="local"> <formal-name>Email Address</formal-name> <description>An email address as defined by <a href="https://tools.ietf.org/html/rfc5322#section-3.4.1">RFC 5322 Section 3.4.1</a>.</description> </define-field>
<define-field name="telephone-number" scope="local"> <formal-name>Telephone Number</formal-name> <description>A telephone service number as defined by <a href="https://www.itu.int/rec/T-REC-E.164-201011-I/en">ITU-T E.164</a>.</description> <json-value-key>number</json-value-key> <define-flag name="type"> <formal-name>type flag</formal-name> <description>Indicates the type of phone number.</description> <constraint> <allowed-values id="oscal-metadata-telephone-number-type-values" allow-other="yes"> <enum value="home">A home phone number.</enum> <enum value="office">An office phone number.</enum> <enum value="mobile">A mobile phone number.</enum> </allowed-values> </constraint> </define-flag> <constraint> <matches id="oscal-metadata-telephone-number-regex" level="WARNING" target="." regex="^[0-9]{3}[0-9]{1,12}$"> <remarks> <p>Providing a country code provides an international means to interpret the phone number.</p> </remarks> </matches> </constraint> </define-field>
<define-assembly name="address" scope="local"> <formal-name>Address</formal-name> <description>A postal address for the location.</description> <flag ref="location-type"> <use-name>type</use-name> </flag> <model> <field ref="addr-line" max-occurs="unbounded"> <!-- CHANGE: "postal-address" to "addr-lines" --> <group-as name="addr-lines" in-json="ARRAY"/> </field> <define-field name="city"> <formal-name>City</formal-name> <description>City, town or geographical region for the mailing address.</description> </define-field> <define-field name="state"> <formal-name>State</formal-name> <description>State, province or analogous geographical region for a mailing address.</description> </define-field> <define-field name="postal-code"> <formal-name>Postal Code</formal-name> <description>Postal or ZIP code for mailing address.</description> </define-field> <define-field name="country"> <formal-name>Country Code</formal-name> <description>The ISO 3166-1 alpha-2 country code for the mailing address.</description> <constraint> <matches id="oscal-metadata-location-address-country-regex" target="." regex="[A-Z]{2}"/> </constraint> </define-field> <!-- More address stuff --> </model> </define-assembly> <define-field name="addr-line" scope="local"> <formal-name>Address line</formal-name> <description>A single line of an address.</description> </define-field>
<define-flag name="location-type" as-type="token" scope="local"> <formal-name>Address Type</formal-name> <description>Indicates the type of address.</description> <constraint> <allowed-values id="oscal-metadata-address-location-type-values" allow-other="yes"> <enum value="home">A home address.</enum> <enum value="work">A work address.</enum> </allowed-values> </constraint> </define-flag>
<define-field name="document-id" scope="local"> <formal-name>Document Identifier</formal-name> <!-- identifier declaration --> <description>A document identifier qualified by an identifier <code>scheme</code>.</description> <json-value-key>identifier</json-value-key> <define-flag name="scheme" as-type="uri"> <formal-name>Document Identification Scheme</formal-name> <description>Qualifies the kind of document identifier using a URI. If the scheme is not provided the value of the element will be interpreted as a string of characters.</description> <constraint> <allowed-values id="oscal-metadata-document-id-scheme-values" allow-other="yes"> <enum value="http://www.doi.org/">A <a href="https://www.doi.org/hb.html">Digital Object Identifier</a> (DOI); use is preferred, since this allows for retrieval of a full bibliographic record.</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> <remarks> <p>A document identifier provides a <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique" >globally unique</a> identifier with a <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that is used for a group of documents that are to be treated as different versions, representations or digital surrogates of the same document.</p> <p>A document identifier provides an additional data point for identifying a document that can be assigned by a publisher or organization for purposes in a wider system, such as a digital object identifier (DOI) or a local content management system identifier.</p> <p>Use of a document identifier allows for document creators to associate sets of documents that are related in some way by the same <code>document-id</code>.</p> <p>An OSCAL document always has an implicit document identifier provided by the document's UUID, defined by the <code>uuid</code> on the top-level object. Having a default UUID-based identifier ensures all documents can be minimally identified when other document identifiers are not provided.</p> </remarks> </define-field> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema-xslt/support/metaschema/schema/xml/metaschema.xsd"> <schema-name>OSCAL Plan of Action and Milestones (POA&amp;M) Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-poam</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL Plan of Action and Milestones (POA&amp;M) format is used to describe the information typically provided by an assessor during the preparation for an assessment.</p> <p>The root of the OSCAL Plan of Action and Milestones (POA&amp;M) format is <code>plan-action-milestones</code>. </p> </remarks> <!-- IMPORT STATEMENTS --> <import href="oscal_metadata_metaschema.xml"/> <import href="oscal_implementation-common_metaschema.xml"/> <import href="oscal_assessment-common_metaschema.xml"/> <!-- TOP LEVEL ASSEMBLY --> <define-assembly name="plan-of-action-and-milestones"> <formal-name>Plan of Action and Milestones (POA&amp;M)</formal-name> <description>A plan of action and milestones which identifies initial and residual risks, deviations, and disposition, such as those required by FedRAMP.</description> <root-name>plan-of-action-and-milestones</root-name> <define-flag name="uuid" required="yes" as-type="uuid"> <formal-name>POA&amp;M Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#instance">instance</a>scope that can be used to reference this POA&amp;M instance in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#poam-identifiers">this OSCAL instance</a>. This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="metadata" min-occurs="1" max-occurs="1"/> <!-- QUESTION: should this be a choice with system-id? --> <assembly ref="import-ssp" min-occurs="0" max-occurs="1"> <remarks> <p>Used by the POA&amp;M to import information about the system.</p> </remarks> </assembly> <field ref="system-id" min-occurs="0" max-occurs="1"/> <assembly ref="local-definitions" min-occurs="0" max-occurs="1"/> <!-- CHANGE: move "observation" from poam-item --> <assembly ref="observation" min-occurs="0" max-occurs="unbounded"> <group-as name="observations" in-json="ARRAY"/> </assembly> <!-- CHANGE: move "risk" from poam-item --> <assembly ref="risk" min-occurs="0" max-occurs="unbounded"> <group-as name="risks" in-json="ARRAY"/> </assembly> <assembly ref="finding" min-occurs="0" max-occurs="unbounded"> <group-as name="findings" in-json="ARRAY"/> </assembly> <assembly ref="poam-item" min-occurs="1" max-occurs="unbounded"> <!-- CHANGED: removed the top-level "poam-items" --> <!-- CHANGED: "poam-item-group" to "poam-items" --> <group-as name="poam-items" in-json="ARRAY"/> </assembly> <assembly ref="back-matter" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>Either an OSCAL-based SSP must be imported, or a unique system-id must be specified. Both may be present.</p> </remarks> </define-assembly> <define-assembly name="local-definitions"> <formal-name>Local Definitions</formal-name> <description>Allows components, and inventory-items to be defined within the POA&amp;M for circumstances where no OSCAL-based SSP exists, or is not delivered with the POA&amp;M.</description> <model> <assembly ref="system-component" min-occurs="0" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> <remarks> <p>Used to add any components, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <assembly ref="inventory-item" min-occurs="0" max-occurs="unbounded"> <group-as name="inventory-items" in-json="ARRAY"/> <remarks> <p>Used to add any inventory-items, not defined via the System Security Plan (AR-&gt;AP-&gt;SSP)</p> </remarks> </assembly> <!-- CHANGED: added to specify components and assessment-platforms from the assessment --> <assembly ref="assessment-assets" min-occurs="0" max-occurs="1"> <remarks> <p>Specifies components or assessment-platforms used in the assessment.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <is-unique id="oscal-unique-poam-local-definitions-component" target="component"> <key-field target="@uuid"/> <remarks> <p>Since multiple <code>component</code> entries can be provided, each component must have a unique <code>uuid</code>.</p> </remarks> </is-unique> </constraint> </define-assembly>
<define-assembly name="poam-item"> <formal-name>POA&amp;M Item</formal-name> <description>Describes an individual POA&amp;M item.</description> <define-flag name="uuid" as-type="uuid"> <formal-name>POA&amp;M Item Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#instance">instance</a> scope that can be used to reference this POA&amp;M item entry in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#poam-identifiers">this OSCAL instance</a>. This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" min-occurs="1" max-occurs="1" as-type="markup-line"> <formal-name>POA&amp;M Item Title</formal-name> <description>The title or name for this POA&amp;M item .</description> </define-field> <!-- CHANGE: Added WITH_WRAPPER to description--> <define-field name="description" min-occurs="1" max-occurs="1" in-xml="WITH_WRAPPER" as-type="markup-multiline"> <formal-name>POA&amp;M Item Description</formal-name> <description>A human-readable description of POA&amp;M item.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="origin" max-occurs="unbounded"> <formal-name>Origin</formal-name> <description>Identifies the source of the finding, such as a tool or person.</description> <group-as name="origins" in-json="ARRAY"/> <model> <assembly ref="origin-actor" min-occurs="1" max-occurs="unbounded"> <use-name>actor</use-name> <group-as name="actors" in-json="ARRAY"/> </assembly> </model> <remarks> <p>Used to identify the individual and/or tool generated this poam-item.</p> </remarks> </define-assembly>
<define-assembly name="related-finding" min-occurs="0" max-occurs="unbounded"> <formal-name>Related Finding</formal-name> <description>Relates the poam-item to referenced finding(s).</description> <group-as name="related-findings" in-json="ARRAY"/> <define-flag name="finding-uuid" as-type="uuid" required="yes"> <formal-name>Finding Universally Unique Identifier Reference</formal-name> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a finding defined in the list of findings.</description> </define-flag> <model> <!-- Without a model the flags do not get generated in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly>
<!-- TODO: add link; check in the other assessment models --> <!-- CHANGED: removed "collected" and "expires" (moved to observation) by brianrufgsa --> <!-- CHANGED: removed "objective-status" per brianrufgsa --> <!-- CHANGED: (per Brian) removed "implementation-statement-uuid" since this is in the SAR --> <!-- CHANGED: replaced embedded observation with references --> <assembly ref="related-observation" max-occurs="unbounded"> <group-as name="related-observations" in-json="ARRAY"/> </assembly>
<!-- CHANGED: replaced "risk" with new "associated-risk" --> <!-- define-assembly name="associated-risk" max-occurs="unbounded"> <formal-name>Associated Risk</formal-name> <description>Relates the finding to a set of referenced risks that were used to determine the finding.</description> <group-as name="related-risks" in-json="ARRAY"/> <define-flag name="risk-uuid" as-type="uuid" required="yes"> <formal-name>Risk Universally Unique Identifier Reference</formal-name> <!- - Identifier Reference - -> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a risk defined in the list of risks.</description> </define-flag> </define-assembly --> <assembly ref="associated-risk" max-occurs="unbounded"> <group-as name="related-risks" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <constraint> <expect id="oscal-poam-item-uuid" level="WARNING" target="." test="@uuid"> <message>It is a best practice to provide a UUID.</message> </expect> </constraint> </define-assembly> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <?xml-model href="../../build/metaschema-xslt/src/validate/metaschema-composition-check.sch" type="application/xml" schematypens="http://purl.oclc.org/dsdl/schematron"?> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-control-group-property-name SYSTEM "./shared-constraints/allowed-values-control-group-property-name.ent"> ]> <?xml-stylesheet type="text/css" href="metaschema-author.css"?> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0"> <schema-name>OSCAL Profile Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-profile</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>In OSCAL a profile represents a set of selected <a href="https://pages.nist.gov/OSCAL/concepts/terminology/#control" >controls</a> from one or more control catalogs. Such a set of controls can be referenced by an OSCAL <a href="https://pages.nist.gov/OSCAL/concepts/layer/implementation/ssp/" >system security plan</a> (SSP) to establish a control <a href="https://pages.nist.gov/OSCAL/concepts/terminology/#baseline" >baseline</a>. This effective set of controls is produced from an OSCAL profile using a deterministic, predictable process called <a href="https://pages.nist.gov/OSCAL/concepts/processing/profile-resolution/" >profile resolution</a>.</p> <p>A profile references one or more OSCAL catalogs or profiles to import controls for control selection and tailoring. A profile can also describe how a resulting catalog is structured. When the profile is resolved, these selections and modifications are processed to produce a resulting OSCAL catalog.</p> <p>OSCAL profiles have uses beyond establishing control baselines, such as documentation generation or as reference tables for validations.</p> </remarks>
<import href="oscal_metadata_metaschema.xml"/> <import href="oscal_control-common_metaschema.xml"/>
<define-assembly name="profile"> <formal-name>Profile</formal-name> <description>Each OSCAL profile is defined by a <code>profile</code> element.</description> <root-name>profile</root-name> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Profile Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>Provides a globally unique means to identify a given profile instance.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="machine-oriented"/> <prop name="identifier-uniqueness" value="global"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="change-on-write"/> </define-flag> <model> <assembly ref="metadata" min-occurs="1"/> <assembly ref="import" min-occurs="1" max-occurs="unbounded"> <group-as name="imports" in-json="ARRAY"/> </assembly> <assembly ref="merge"/> <assembly ref="modify"/> <assembly ref="back-matter"/> </model> <remarks> <p>An OSCAL document that describes a tailoring of controls from one or more catalogs, with possible modification of multiple controls. It provides mechanisms by which controls may be selected (<code>import</code>), merged or (re)structured (<code>merge</code>), and amended (<code>modify</code>). OSCAL profiles may select subsets of controls, set parameter values for them in application, and even adjust the representation of controls as given in and by a catalog. They may also serve as sources for further modification in and by other profiles, that import them.</p> </remarks> </define-assembly> <define-assembly name="import"> <formal-name>Import Resource</formal-name> <description>Designates a referenced source catalog or profile that provides a source of control information for use in creating a new overlay or baseline.</description> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Catalog or Profile Reference</formal-name> <description>A resolvable URL reference to the base catalog or profile that this profile is tailoring.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> </remarks> </define-flag> <model> <choice> <assembly ref="include-all" min-occurs="1"> <remarks> <p>Identifies that all controls are to be included from the imported catalog or profile.</p> </remarks> </assembly> <assembly ref="select-control-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>include-controls</use-name> <group-as name="include-controls" in-json="ARRAY"/> <remarks> <p>If <code>with-child-controls</code> is <q>yes</q> on the call to a control, any controls appearing within it (child controls) will be selected, with no additional <code>call</code> directives required. This flag provides a way to include controls with all their dependent controls (enhancements) without having to call them individually.</p> </remarks> </assembly> </choice> <assembly ref="select-control-by-id" max-occurs="unbounded"> <use-name>exclude-controls</use-name> <group-as name="exclude-controls" in-json="ARRAY"/> <remarks> <p>Identifies which controls to exclude, or eliminate, from the set of included controls by control identifier or match pattern.</p> </remarks> </assembly> </model> <remarks> <p>The contents of the <code>import</code> element indicate which controls from the source will be included. Controls from the source catalog or profile may be either selected, using the <code>include-all</code> or <code>include-controls</code> directives, or de-selected (using an <code>exclude-controls</code> directive).</p> </remarks> <example> <import xmlns="http://csrc.nist.gov/ns/oscal/example" href="catalog.xml"> <include-all/> </import> </example> </define-assembly> <define-assembly name="merge"> <formal-name>Merge Controls</formal-name> <description>Provides structuring directives that instruct how controls are organized after profile resolution.</description> <model> <define-assembly name="combine"> <formal-name>Combination Rule</formal-name> <description>A Combine element defines how to resolve duplicate instances of the same control (e.g., controls with the same ID).</description> <define-flag name="method" as-type="string"> <formal-name>Combination Method</formal-name> <description>Declare how clashing controls should be handled.</description> <constraint> <allowed-values id="oscal-profile-merge-combine-method-values"> <enum value="use-first">Use the first definition - the first control with a given ID is used; subsequent ones are discarded</enum> <enum value="merge" deprecated="1.0.1" >**(<i>deprecated</i>)** **(<i>unspecified</i>)** Merge - controls with the same ID are combined</enum> <enum value="keep">Keep - controls with the same ID are kept, retaining the clash</enum> </allowed-values> </constraint> </define-flag> <constraint> <expect id="oscal-profile-req-merge-combine" target="." test="not(@method='merge')"/> </constraint> </define-assembly> <choice> <define-assembly name="flat" min-occurs="1"> <formal-name>Flat Without Grouping</formal-name> <description>Directs that controls appear without any grouping structure.</description> </define-assembly> <define-field name="as-is" as-type="boolean" min-occurs="1"> <formal-name>Group As-Is</formal-name> <description>Indicates that the controls selected should retain their original grouping as defined in the import source.</description> </define-field> <define-assembly name="custom" min-occurs="1"> <formal-name>Custom Grouping</formal-name> <description>Provides an alternate grouping structure that selected controls will be placed in.</description> <model> <assembly ref="group" max-occurs="unbounded"> <group-as name="groups" in-json="ARRAY"/> </assembly> <assembly ref="insert-controls" max-occurs="unbounded"> <group-as name="insert-controls" in-json="ARRAY"/> </assembly> </model> <remarks> <p>The <code>custom</code> element represents a custom arrangement or organization of controls in the resolution of a catalog. This structuring directive gives the profile author the ability to define an entirely different organization of controls as compared to their source catalog(s).</p> </remarks> </define-assembly> </choice> </model> </define-assembly> <define-assembly name="group"> <formal-name>Control Group</formal-name> <description>A group of (selected) controls or of groups of controls.</description> <define-flag name="id" as-type="token"> <!-- This is an id because the identifier is assigned and managed externally by humans. --> <formal-name>Group Identifier</formal-name> <!-- Identifier Declaration --> <description>Identifies the group.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> <remarks> <p>This optional data element is available to support hyperlinking to formal groups or families as defined in control catalogs, among other operations.</p> </remarks> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Group Class</formal-name> <description>A textual label that provides a sub-type or characterization of the group.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> <p>A <code>class</code> can also be used in an OSCAL profile as a means to target an alteration to control content.</p> </remarks> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>Group Title</formal-name> <description>A name to be given to the group for use in display.</description> </define-field> <assembly ref="parameter" max-occurs="unbounded"> <group-as name="params" in-json="ARRAY"/> </assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> <choice> <assembly ref="group" max-occurs="unbounded"> <group-as name="groups" in-json="ARRAY"/> </assembly> <assembly ref="insert-controls" max-occurs="unbounded"> <group-as name="insert-controls" in-json="ARRAY"/> </assembly> </choice> </model> <remarks> <p>This construct mirrors the same construct that exists in an OSCAL catalog.</p> </remarks> </define-assembly> <define-assembly name="modify"> <formal-name>Modify Controls</formal-name> <description>Set parameters or amend controls in resolution.</description> <model> <define-assembly name="set-parameter" max-occurs="unbounded"> <formal-name>Parameter Setting</formal-name> <description>A parameter setting, to be propagated to points of insertion.</description> <group-as name="set-parameters" in-json="ARRAY"/> <define-flag required="yes" name="param-id" as-type="token"> <!-- This is an id because the identifier is assigned and managed by humans. --> <formal-name>Parameter ID</formal-name> <!-- Identifier Declaration --> <description>An identifier for the parameter.</description> <prop name="value-type" value="identifier"/> <prop name="identifier-type" value="human-oriented"/> <prop name="identifier-uniqueness" value="instance"/> <prop name="identifier-scope" value="cross-instance"/> <prop name="identifier-persistence" value="per-subject"/> </define-flag> <define-flag name="class" as-type="token"> <formal-name>Parameter Class</formal-name> <description>A textual label that provides a characterization of the parameter.</description> <remarks> <p>A <code>class</code> can be used in validation rules to express extra constraints over named items of a specific <code>class</code> value.</p> </remarks> </define-flag> <define-flag name="depends-on" as-type="token" deprecated="1.0.1"> <formal-name>Depends On</formal-name> <description>**(deprecated)** Another parameter invoking this one. This construct has been deprecated and should not be used.</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-field name="label" as-type="markup-line"> <formal-name>Parameter Label</formal-name> <description>A short, placeholder name for the parameter, which can be used as a substitute for a <code>value</code> if no value is assigned.</description> <remarks> <p>The label value should be suitable for inline display in a rendered catalog.</p> </remarks> </define-field> <define-field name="usage" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Parameter Usage Description</formal-name> <description>Describes the purpose and use of a parameter.</description> </define-field> <assembly ref="parameter-constraint" max-occurs="unbounded"> <use-name>constraint</use-name> <group-as name="constraints" in-json="ARRAY"/> </assembly> <assembly ref="parameter-guideline" max-occurs="unbounded"> <use-name>guideline</use-name> <group-as name="guidelines" in-json="ARRAY"/> </assembly> <choice> <field ref="parameter-value" max-occurs="unbounded"> <use-name>value</use-name> <group-as name="values" in-json="ARRAY"/> <remarks> <p>Used to (re)define a parameter value.</p> </remarks> </field> <assembly ref="parameter-selection"> <use-name>select</use-name> </assembly> </choice> </model> </define-assembly> <define-assembly name="alter" max-occurs="unbounded"> <formal-name>Alteration</formal-name> <description>Specifies changes to be made to an included control when a profile is resolved.</description> <group-as name="alters" in-json="ARRAY"/> <flag ref="control-id" required="yes"/> <model> <define-assembly name="remove" max-occurs="unbounded"> <formal-name>Removal</formal-name> <description>Specifies objects to be removed from a control based on specific aspects of the object that must all match.</description> <group-as name="removes" in-json="ARRAY"/> <define-flag name="by-name" as-type="token"> <formal-name>Reference by (assigned) name</formal-name> <description>Identify items remove by matching their assigned name.</description> </define-flag> <define-flag name="by-class" as-type="token"> <formal-name>Reference by class</formal-name> <description>Identify items to remove by matching their <code>class</code>.</description> </define-flag> <define-flag name="by-id" as-type="token"> <formal-name>Reference by ID</formal-name> <description>Identify items to remove indicated by their <code>id</code>.</description> </define-flag> <define-flag name="by-item-name" as-type="token"> <formal-name>Item Name Reference</formal-name> <description>Identify items to remove by the name of the item's information object name, e.g. <code>title</code> or <code>prop</code>.</description> <constraint> <allowed-values id="oscal-profile-alter-by-item-name-values"> <enum value="param">A descendant parameter and all of its descendants.</enum> <enum value="prop">A descendant property and all of its descendants.</enum> <enum value="link">A descendant link and all of its descendants.</enum> <enum value="part">A descendant parameter and all of its descendants.</enum> <enum value="mapping">A descendant mapping and all of its descendants.</enum> <enum value="map">A descendant mapping entry (map) and all of its descendants.</enum> </allowed-values> </constraint> </define-flag> <define-flag name="by-ns" as-type="uri"> <formal-name>Item Namespace Reference</formal-name> <description>Identify items to remove by the item's <code>ns</code>, which is the namespace associated with a <code>part</code>, or <code>prop</code>.</description> </define-flag> <model> <!-- Without a model the flags do not get generated in JSON schemas --> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> <remarks> <p>Use <code>by-name</code>, <code>by-class</code>, <code>by-id</code> or <code>by-item-name</code> to indicate class tokens or ID reference, or the formal name, of the component to be removed or erased from a control, when a catalog is resolved. The control affected is indicated by the pointer on the removal's parent (containing) <code>alter</code> element.</p> <p>To change an element, use <code>remove</code> to remove the element, then <code>add</code> to add it back again with changes.</p> </remarks> </define-assembly> <define-assembly name="add" max-occurs="unbounded"> <formal-name>Addition</formal-name> <description>Specifies contents to be added into controls, in resolution.</description> <group-as name="adds" in-json="ARRAY"/> <define-flag name="position" as-type="token" default="ending"> <formal-name>Position</formal-name> <description>Where to add the new content with respect to the targeted element (beside it or inside it).</description> <constraint> <allowed-values id="oscal-alter-position-values"> <enum value="before">Preceding the by-id target</enum> <enum value="after">Following the by-id target</enum> <enum value="starting">Inside the control or by-id target, at the start</enum> <enum value="ending">Inside the control or by-id target, at the end</enum> </allowed-values> </constraint> </define-flag> <define-flag name="by-id" as-type="token"> <formal-name>Reference by ID</formal-name> <description>Target location of the addition.</description> </define-flag> <model> <define-field name="title" as-type="markup-line"> <formal-name>Title Change</formal-name> <description>A name given to the control, which may be used by a tool for display and navigation.</description> </define-field> <assembly ref="parameter" max-occurs="unbounded"> <group-as name="params" in-json="ARRAY"/> </assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="part" max-occurs="unbounded"> <group-as name="parts" in-json="ARRAY"/> </assembly> </model> <constraint> <allowed-values id="oscal-profile-modify-alter-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> &allowed-values-control-group-property-name; </allowed-values> </constraint> <remarks> <p>When no <code>by-id</code> is given, the addition is inserted into the control targeted by the alteration at the start or end as indicated by <code>position</code>. Only <code>position</code> values of "starting" or "ending" are permitted when there is no <code>by-id</code>.</p> <p><code>by-id</code>, when given, should indicate, by its ID, an element inside the control to serve as the anchor point for the addition. In this case, <code>position</code> value may be any of the permitted values.</p> </remarks> </define-assembly> </model> <remarks> <p>Use <code>@control-id</code> to indicate the scope of alteration.</p> <p>It is an error for two <code>alter</code> elements to apply to the same control. In practice, multiple alterations can be applied (together), but it creates confusion.</p> <p>At present, no provision is made for altering many controls at once (for example, to systematically remove properties or add global properties); extending this element to match multiple control IDs could provide for this.</p> </remarks> </define-assembly> </model> <constraint> <is-unique id="oscal-unique-profile-modify-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> </constraint>
</define-assembly> <define-assembly name="insert-controls"> <formal-name>Insert Controls</formal-name> <description>Specifies which controls to use in the containing context.</description> <define-flag as-type="token" name="order"> <formal-name>Order</formal-name> <description>A designation of how a selection of controls in a profile is to be ordered.</description> <constraint> <allowed-values id="oscal-profile-insert-controls-order-values"> <enum value="keep">Use the order of their appearance, using a depth-first traversal of the source profile's imports.</enum> <enum value="ascending">Sort all selected controls into ascending alphanumeric order by their ID.</enum> <enum value="descending">Sort all selected controls into descending alphanumeric order by their ID.</enum> </allowed-values> </constraint> </define-flag> <model> <choice> <assembly ref="include-all" min-occurs="1"/> <assembly ref="select-control-by-id" min-occurs="1" max-occurs="unbounded"> <use-name>include-controls</use-name> <group-as name="include-controls" in-json="ARRAY"/> </assembly> </choice> <assembly ref="select-control-by-id" max-occurs="unbounded"> <use-name>exclude-controls</use-name> <group-as name="exclude-controls" in-json="ARRAY"/> <remarks> <p>Identifies which controls to exclude, or eliminate, from the set of matching includes.</p> </remarks> </assembly> </model> <remarks> <p>To be schema-valid, this element must contain either (but not both) a single <code>include-all</code> directive, or a sequence of <code>include-controls</code> directives.</p> <p>If this directive is not provided, then no controls are to be inserted; i.e., all controls are included explicitly.</p> </remarks> </define-assembly> <!-- assembly definition moved to the control-common file for reuse in mapping --> <!-- define-assembly name="select-control-by-id" scope="local"> <formal-name>Select Control</formal-name> <description>Select a control or controls from an imported control set.</description> <flag ref="with-child-controls"/> <model> <field ref="with-id" max-occurs="unbounded"> <group-as name="with-ids" in-json="ARRAY"/> </field> <assembly ref="matching" max-occurs="unbounded"> <group-as name="matching" in-json="ARRAY"/> </assembly> </model> <remarks> <p>If <code>with-child-controls</code> is <q>yes</q> on the call to a control, no sibling <code>call</code>elements need to be used to call any controls appearing within it. Since generally, this is how control enhancements are represented (as controls within controls), this provides a way to include controls with all their dependent controls (enhancements) without having to call them individually.</p> </remarks> </define-assembly --> <!-- define-flag as-type="token" name="with-child-controls"> <formal-name>Include Contained Controls with Control</formal-name> <description>When a control is included, whether its child (dependent) controls are also included.</description> <constraint> <allowed-values id="oscal-profile-with-child-controls-values"> <enum value="yes">Include child controls with an included control.</enum> <enum value="no">When importing a control, only include child controls that are also explicitly called.</enum> </allowed-values> </constraint> </define-flag --> <!-- next flag definition was moved to the control-common file for reuse in mapping --> <!-- define-flag as-type="string" name="pattern"> <formal-name>Pattern</formal-name> <description>A <a href="https://en.wikipedia.org/wiki/Glob_(programming)">glob expression</a> matching the IDs of one or more controls to be selected.</description> </define-flag --> <!-- next field definition was moved to the control-common file for reuse in mapping --> <!-- define-field name="with-id" as-type="token"> <formal-name>Match Controls by Identifier</formal-name> <description>Selecting a control by its ID given as a literal.</description> </define-field --> <!-- next assembly definition was moved to the control-common file for reuse in mapping --> <!-- define-assembly name="matching"> <formal-name>Match Controls by Pattern</formal-name> <description>Selecting a set of controls by matching their IDs with a wildcard pattern.</description> <flag ref="pattern"/> <model> <field ref="remarks" in-xml="WITH_WRAPPER" min-occurs="0" max-occurs="1"/> </model> </define-assembly --> </METASCHEMA><?xml version="1.0" encoding="UTF-8"?> <!-- ** NOTES ** - Need to check latest FR SSP template for "Privacy Impact Designation". Was it dropped in latest template, or is it missing from schema? --> <!-- OSCAL Implementation Layer: System Security Plan (SSP) METASCHEMA --> <!-- validate with XSD and Schematron (linked) --> <!DOCTYPE METASCHEMA [ <!ENTITY allowed-values-responsible-roles-system SYSTEM "./shared-constraints/allowed-values-responsible-roles-system.ent"> <!ENTITY allowed-values-responsible-roles-operations SYSTEM "./shared-constraints/allowed-values-responsible-roles-operations.ent"> <!ENTITY allowed-values-responsible-roles-component-production SYSTEM "./shared-constraints/allowed-values-responsible-roles-component-production.ent"> ]> <METASCHEMA xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns="http://csrc.nist.gov/ns/oscal/metaschema/1.0" xsi:schemaLocation="http://csrc.nist.gov/ns/oscal/metaschema/1.0 ../../build/metaschema-xslt/support/metaschema/schema/xml/metaschema.xsd"> <schema-name>OSCAL System Security Plan (SSP) Model</schema-name> <schema-version>1.2.2</schema-version> <short-name>oscal-ssp</short-name> <namespace>http://csrc.nist.gov/ns/oscal/1.0</namespace> <json-base-uri>http://csrc.nist.gov/ns/oscal</json-base-uri> <remarks> <p>The OSCAL Control SSP format can be used to describe the information typically specified in a system security plan, such as those defined in NIST SP 800-18.</p> <p>The root of the OSCAL System Security Plan (SSP) format is <code>system-security-plan</code>.</p> </remarks>
<import href="oscal_metadata_metaschema.xml"/> <import href="oscal_implementation-common_metaschema.xml"/>
<!-- ############################################## --> <!-- # The SSP Assembly and supporting constructs # --> <!-- ############################################## --> <define-assembly name="system-security-plan"> <formal-name>System Security Plan (SSP)</formal-name> <description>A system security plan, such as those described in NIST SP 800-18.</description> <root-name>system-security-plan</root-name> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>System Security Plan Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this system security plan (SSP) elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>SSP</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance).This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <assembly ref="metadata" min-occurs="1"/> <assembly ref="import-profile" min-occurs="1"/> <assembly ref="system-characteristics" min-occurs="1"/> <assembly ref="system-implementation" min-occurs="1"/> <assembly ref="control-implementation" min-occurs="1"/> <assembly ref="back-matter"/> </model> <constraint> <index id="oscal-ssp-by-component-uuid-index" name="by-component-uuid" target="control-implementation/implemented-requirement//by-component|doc(system-implementation/leveraged-authorization/link[@rel='system-security-plan']/@href)/system-security-plan/control-implementation/implemented-requirement//by-component"> <key-field target="@uuid"/> </index> </constraint> </define-assembly>
<!-- ######################################################### --> <!-- # The Import Profile Assembly and supporting constructs # --> <!-- ######################################################### --> <define-assembly name="import-profile"> <formal-name>Import Profile</formal-name> <description>Used to import the OSCAL profile representing the system's control baseline.</description> <define-flag name="href" as-type="uri-reference" required="yes"> <formal-name>Profile Reference</formal-name> <description>A resolvable URL reference to the profile or catalog to use as the system's control baseline.</description> <remarks> <p>This value may be one of:</p> <ol> <li>an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that points to a network resolvable resource,</li> <li>a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#relative-reference">relative reference</a> pointing to a network resolvable resource whose base URI is the URI of the containing document, or</li> <li>a bare URI fragment (i.e., `#uuid`) pointing to a <code>back-matter</code> resource in this or an imported document (see <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#linking-to-another-oscal-object">linking to another OSCAL object</a>).</li> </ol> <p>If the resource is an OSCAL profile, it is expected that a tool will resolve the profile according to the OSCAL <a href="https://pages.nist.gov/OSCAL/concepts/processing/profile-resolution/">profile resolution specification</a> to produce a resolved profile for use when processing the containing system security plan. This allows a system security plan processor to use the baseline as a catalog of controls.</p> <p>While it is possible to reference a previously resolved OSCAL profile as a catalog, this practice is discouraged since the unresolved form of the profile communicates more information about selections and changes to the underlying catalog. Furthermore, the underlying catalog can be maintained separately from the profile, which also has maintenance advantages for distinct maintainers, ensuring that the best available information is produced through profile resolution.</p> </remarks> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> </define-assembly>
<!-- ################################################################# --> <!-- # The System Characteristics Assembly and supporting constructs # --> <!-- ################################################################# --> <define-assembly name="system-characteristics"> <formal-name>System Characteristics</formal-name> <description>Contains the characteristics of the system, such as its name, purpose, and security impact level.</description> <model> <field ref="system-id" min-occurs="1" max-occurs="unbounded"> <group-as name="system-ids" in-json="ARRAY"/> </field> <define-field name="system-name" as-type="string" min-occurs="1"> <formal-name>System Name - Full</formal-name> <description>The full name of the system.</description> </define-field> <define-field name="system-name-short" as-type="string"> <formal-name>System Name - Short</formal-name> <description>A short name for the system, such as an acronym, that is suitable for display in a data table or summary list.</description> <remarks> <p>Since <code>system-name-short</code> is optional, if the <code>system-name-short</code> is not provided, the <code>system-name</code> can be used as a substitute.</p> </remarks> </define-field> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>System Description</formal-name> <description>A summary of the system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="date-authorized"/> <define-field name="security-sensitivity-level" min-occurs="0"> <formal-name>Security Sensitivity Level</formal-name> <description>The overall information system sensitivity categorization, such as defined by <a href="https://doi.org/10.6028/NIST.FIPS.199">FIPS-199</a>.</description> <remarks> <p>Often, organizations require the security sensitivity level to correspond with the highest confidentiality, integrity, or availability level identified by <code>security-impact-level</code>. </p> </remarks> </define-field> <assembly ref="system-information" min-occurs="1"/> <assembly ref="security-impact-level" min-occurs="0"/> <assembly ref="status" min-occurs="1"/> <assembly ref="authorization-boundary" min-occurs="1"/> <assembly ref="network-architecture"/> <assembly ref="data-flow"/> <assembly ref="responsible-party" max-occurs="unbounded"> <group-as name="responsible-parties" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-system-characteristics-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="identity-assurance-level">A value of 1, 2, or 3 as defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> <enum value="authenticator-assurance-level">A value of 1, 2, or 3 as defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> <enum value="federation-assurance-level">A value of 1, 2, or 3 as defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> </allowed-values> <allowed-values id="oscal-system-characteristics-prop-sp-800-63-assurance-level-values" target="prop[@name=('identity-assurance-level','authenticator-assurance-level','federation-assurance-level')]/@value"> <enum value="1">As defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> <enum value="2">As defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> <enum value="3">As defined by <a href="https://doi.org/10.6028/NIST.SP.800-63-3">SP 800-63-3</a>. </enum> </allowed-values> <allowed-values id="oscal-system-characteristics-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="cloud-deployment-model">The associated value is one of: public-cloud, private-cloud, community-cloud, government-only-cloud, hybrid-cloud, or other.</enum> <enum value="cloud-service-model">The associated value is one of: saas, paas, iaas, or other.</enum> </allowed-values> <allowed-values id="oscal-system-characteristics-prop-cloud-deployment-model-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='cloud-deployment-model']/@value"> <enum value="public-cloud">The public cloud deployment model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="private-cloud">The private cloud deployment model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="community-cloud">The community cloud deployment model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="hybrid-cloud">The hybrid cloud deployment model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <!-- TODO: consider generalizing this in a way that applies to other usage contexts. --> <enum value="government-only-cloud">A specific type of community-cloud for use only by government services.</enum> <enum value="other">Any other type of cloud deployment model that is exclusive to the other choices.</enum> <remarks> <p>The hybrid cloud deployment model, as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>, can be supported by selecting two or more of the existing deployment models.</p> </remarks> </allowed-values> <allowed-values id="oscal-system-characteristics-prop-cloud-service-model-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='cloud-service-model']/@value"> <enum value="saas">Software as a service (SaaS) cloud service model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="paas">Platform as a service (PaaS) cloud service model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="iaas">Infrastructure as a service (IaaS) cloud service model as defined by <a href="https://doi.org/10.6028/NIST.SP.800-145">The NIST Definition of Cloud Computing</a>. </enum> <enum value="other">Any other type of cloud service model that is exclusive to the other choices.</enum> </allowed-values> <is-unique id="oscal-unique-ssp-system-characteristics-responsible-party" target="responsible-party"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-party</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> <allowed-values id="oscal-system-characteristics-responsible-party-role-id-values" target="responsible-party/@role-id" allow-other="yes"> &allowed-values-responsible-roles-system; </allowed-values> </constraint> </define-assembly> <define-assembly name="system-information"> <formal-name>System Information</formal-name> <description>Contains details about all information types that are stored, processed, or transmitted by the system, such as privacy information, and those defined in <a href="https://doi.org/10.6028/NIST.SP.800-60v2r1">NIST SP 800-60</a>.</description> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-assembly name="information-type" min-occurs="1" max-occurs="unbounded"> <formal-name>Information Type</formal-name> <description>Contains details about one information type that is stored, processed, or transmitted by the system, such as privacy information, and those defined in <a href="https://doi.org/10.6028/NIST.SP.800-60v2r1">NIST SP 800-60</a>.</description> <group-as name="information-types" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid"> <formal-name>Information Type Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this information type elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>information type</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>title field</formal-name> <description>A human readable name for the information type. This title should be meaningful within the context of the system.</description> </define-field> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Information Type Description</formal-name> <description>A summary of how this information type is used within the system.</description> </define-field> <define-assembly name="categorization" max-occurs="unbounded"> <!-- CHANGED: replaced the information-type-id structure with the current structure --> <formal-name>Information Type Categorization</formal-name> <description>A set of information type identifiers qualified by the given identification <code>system</code> used, such as NIST SP 800-60.</description> <group-as name="categorizations" in-json="ARRAY"/> <define-flag name="system" as-type="uri" required="yes"> <formal-name>Information Type Identification System</formal-name> <description>Specifies the information type identification system used.</description> <constraint> <allowed-values id="oscal-information-type-categorization-system-values" allow-other="yes"> <enum value="http://doi.org/10.6028/NIST.SP.800-60v2r1">Based on the section identifiers in NIST <a href="https://doi.org/10.6028/NIST.SP.800-60v2r1">Special Publication 800-60 Volume II Revision 1</a>.</enum> </allowed-values> </constraint> <remarks> <p>This value must be an <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#absolute-uri">absolute URI</a> that serves as a <a href="https://pages.nist.gov/OSCAL/concepts/uri-use/#use-as-a-naming-system-identifier">naming system identifier</a>.</p> </remarks> </define-flag> <model> <define-field name="information-type-id" as-type="string" max-occurs="unbounded"> <!-- This is an id because the identifier is assigned and managed externally by humans. --> <formal-name>Information Type Systematized Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#human-oriented">human-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier qualified by the given identification <code>system</code> used, such as NIST SP 800-60. This identifier has <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope and can be used to reference this system elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. This id should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> <json-value-key>id</json-value-key> <group-as name="information-type-ids" in-json="ARRAY"/> </define-field> </model> </define-assembly> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="impact"> <formal-name>Confidentiality Impact Level</formal-name> <description>The expected level of impact resulting from the unauthorized disclosure of the described information.</description> <use-name>confidentiality-impact</use-name> </assembly> <assembly ref="impact"> <formal-name>Integrity Impact Level</formal-name> <description>The expected level of impact resulting from the unauthorized modification of the described information.</description> <use-name>integrity-impact</use-name> </assembly> <assembly ref="impact"> <formal-name>Availability Impact Level</formal-name> <description>The expected level of impact resulting from the disruption of access to or use of the described information or the information system.</description> <use-name>availability-impact</use-name> </assembly> </model> <constraint> <expect id="oscal-information-type-uuid" level="WARNING" target="." test="@uuid"> <message>It is a best practice to provide a UUID.</message> </expect> </constraint> </define-assembly> </model> <constraint> <allowed-values id="oscal-system-information-prop-name-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="privacy-designation">Is this a privacy sensitive system? yes or no</enum> </allowed-values> <allowed-values id="oscal-system-information-prop-privacy-designation-values" target="prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='privacy-designation']/@value"> <enum value="yes">The system is privacy sensitive.</enum> <enum value="no">The system is not privacy sensitive.</enum> </allowed-values> <allowed-values id="oscal-system-information-link-rel-values" target="link/@rel" allow-other="yes"> <enum value="privacy-impact-assessment">A link to the privacy impact assessment.</enum> </allowed-values> <matches id="oscal-system-information-pia-datatype-uri-reference" target="link[@rel='privacy-impact-assessment']/@href[starts-with(.,'#')]" datatype="uri-reference"/> <index-has-key id="oscal-system-information-index-back-matter-resource-pia-link-rel" name="index-back-matter-resource" target="link[@rel='privacy-impact-assessment' and starts-with(@href,'#')]"> <key-field target="@href" pattern="#(.*)"/> </index-has-key> <!-- TODO: Per discussion in usnisgov/OSCAL#1331 review on 29 July 2022, add the path target to security-sensitivity-level as well. --> <matches id="oscal-system-information-pia-datatype-uri" target="link[@rel='privacy-impact-assessment']/@href[not(starts-with(.,'#'))]" datatype="uri"/> <allowed-values id="oscal-fips-199-impact-levels" target="information-type/(confidentiality-impact|integrity-impact|availability-impact)/(base|selected)" allow-other="yes"> <enum value="fips-199-low">A 'low' sensitivity level as defined in <a href="https://doi.org/10.6028/NIST.FIPS.199">FIPS-199</a>. </enum> <enum value="fips-199-moderate">A 'moderate' sensitivity level as defined in <a href="https://doi.org/10.6028/NIST.FIPS.199">FIPS-199</a>. </enum> <enum value="fips-199-high">A 'high' sensitivity level as defined in <a href="https://doi.org/10.6028/NIST.FIPS.199">FIPS-199</a>. </enum> <remarks> <p>FIPS-199 taxonomy is provided here as a starting point. We will provide other taxonomies based on community requests.</p> </remarks> </allowed-values> </constraint> </define-assembly> <define-assembly name="impact"> <formal-name>Impact Level</formal-name> <description>The expected level of impact resulting from the described information.</description> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <field ref="base" min-occurs="1"/> <field ref="selected"/> <field ref="adjustment-justification" in-xml="WITH_WRAPPER"/> </model> </define-assembly> <define-field name="base" as-type="string" scope="local"> <formal-name>Base Level (Confidentiality, Integrity, or Availability)</formal-name> <description>The prescribed base (Confidentiality, Integrity, or Availability) security impact level.</description> </define-field> <define-field name="selected" as-type="string" scope="local"> <formal-name>Selected Level (Confidentiality, Integrity, or Availability)</formal-name> <description>The selected (Confidentiality, Integrity, or Availability) security impact level.</description> </define-field> <define-field name="adjustment-justification" as-type="markup-multiline" scope="local"> <formal-name>Adjustment Justification</formal-name> <description>If the selected security level is different from the base security level, this contains the justification for the change.</description> </define-field> <define-assembly name="security-impact-level"> <formal-name>Security Impact Level</formal-name> <description>The overall level of expected impact resulting from unauthorized disclosure, modification, or loss of access to information.</description> <model> <!-- TODO: Per discussion in usnisgov/OSCAL#1331 review on 29 July 2022, add the path target to security-impact-level as well for fips-199-low/mod/high. --> <define-field name="security-objective-confidentiality" as-type="string" min-occurs="1"> <formal-name>Security Objective: Confidentiality</formal-name> <description>A target-level of confidentiality for the system, based on the sensitivity of information within the system.</description> </define-field> <define-field name="security-objective-integrity" as-type="string" min-occurs="1"> <formal-name>Security Objective: Integrity</formal-name> <description>A target-level of integrity for the system, based on the sensitivity of information within the system.</description> </define-field> <define-field name="security-objective-availability" as-type="string" min-occurs="1"> <formal-name>Security Objective: Availability</formal-name> <description>A target-level of availability for the system, based on the sensitivity of information within the system.</description> </define-field> </model> </define-assembly> <define-assembly name="status" scope="local"> <formal-name>Status</formal-name> <description>Describes the operational status of the system.</description> <define-flag name="state" required="yes" as-type="string"> <formal-name>State</formal-name> <description>The current operating status.</description> <constraint> <allowed-values id="oscal-status-state-values"> <enum value="operational">The system is currently operating in production.</enum> <enum value="under-development">The system is being designed, developed, or implemented</enum> <enum value="under-major-modification">The system is undergoing a major change, development, or transition.</enum> <enum value="disposition">The system is no longer operational.</enum> <enum value="other">Some other state.</enum> </allowed-values> </constraint> </define-flag> <model> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <remarks> <p>If 'other' is selected, a remark must be included to describe the current state.</p> </remarks> </define-assembly> <define-field name="date-authorized" as-type="date" scope="local"> <formal-name>System Authorization Date</formal-name> <description>The date the system received its authorization.</description> </define-field> <define-assembly name="authorization-boundary"> <formal-name>Authorization Boundary</formal-name> <description>A description of this system's authorization boundary, optionally supplemented by diagrams that illustrate the authorization boundary.</description> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Authorization Boundary Description</formal-name> <description>A summary of the system's authorization boundary.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships? --> </assembly> <assembly ref="diagram" max-occurs="unbounded"> <group-as name="diagrams" in-json="ARRAY"/> <remarks> <p>A visual depiction of the system's authorization boundary.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-ssp-authorization-boundary-diagram" target="diagram"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a diagram.</p> </remarks> </is-unique> </constraint> </define-assembly> <define-assembly name="diagram"> <formal-name>Diagram</formal-name> <description>A graphic that provides a visual representation the system, or some aspect of it.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Diagram ID</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this diagram elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>diagram</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Diagram Description</formal-name> <description>A summary of the diagram.</description> <remarks> <p>This description is intended to be used as alternate text to support compliance with requirements from <a href="https://www.section508.gov/manage/laws-and-policies">Section 508 of the United States Workforce Rehabilitation Act of 1973</a>. </p> </remarks> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-field name="caption" as-type="markup-line"> <formal-name>Caption</formal-name> <description>A brief caption to annotate the diagram.</description> </define-field> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-diagram-link-rel-values" target="link/@rel" allow-other="yes"> <enum value="diagram">A reference to the diagram image.</enum> </allowed-values> <matches id="oscal-diagram-datatype-uri-reference" target="link[@rel='diagram']/@href[starts-with(.,'#')]" datatype="uri-reference"/> <index-has-key id="oscal-diagram-index-back-matter-resource-link-rel" name="index-back-matter-resource" target="link[@rel='diagram' and starts-with(@href,'#')]"> <key-field target="@href" pattern="#(.*)"/> </index-has-key> <matches id="oscal-diagram-datatype-uri" target="link[@rel='diagram']/@href[not(starts-with(.,'#'))]" datatype="uri"/> </constraint> <remarks> <p>A diagram must include a <code>link</code> with a rel value of "diagram", who's href references a remote URI or an internal reference within this document containing the diagram.</p> </remarks> <example> <remarks> <p>The internal reference "#diagram1" points to an attached resource defined in the <code>back-matter</code> as a <code>resource</code>. The <code>media-type</code> indicates that the image is a Portable Network Graphics (PNG) image.</p> </remarks> <o:diagram xmlns:o="http://csrc.nist.gov/ns/oscal/example" id="boundary-diagram-1"> <o:description>A boundary diagram.</o:description> <o:link rel="diagram" href="#diagram1" media-type="image/png"/> </o:diagram> </example> </define-assembly> <define-assembly name="network-architecture"> <formal-name>Network Architecture</formal-name> <description>A description of the system's network architecture, optionally supplemented by diagrams that illustrate the network architecture.</description> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Network Architecture Description</formal-name> <description>A summary of the system's network architecture.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships? --> </assembly> <assembly ref="diagram" max-occurs="unbounded"> <group-as name="diagrams" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-ssp-network-architecture-diagram" target="diagram"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a diagram.</p> </remarks> </is-unique> </constraint>
</define-assembly> <define-assembly name="data-flow"> <formal-name>Data Flow</formal-name> <description>A description of the logical flow of information within the system and across its boundaries, optionally supplemented by diagrams that illustrate these flows.</description> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Data Flow Description</formal-name> <description>A summary of the system's data flow.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships? --> </assembly> <assembly ref="diagram" max-occurs="unbounded"> <group-as name="diagrams" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-ssp-data-flow-diagram" target="diagram"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a diagram.</p> </remarks> </is-unique> </constraint> </define-assembly>
<!-- ################################################################ --> <!-- # The System Implementation Assembly and supporting constructs # --> <!-- ################################################################ --> <define-assembly name="system-implementation"> <formal-name>System Implementation</formal-name> <description>Provides information as to how the system is implemented.</description> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships? --> </assembly> <define-assembly name="leveraged-authorization" max-occurs="unbounded"> <formal-name>Leveraged Authorization</formal-name> <description>A description of another authorized system from which this system inherits capabilities that satisfy security requirements. Another term for this concept is a <em>common control provider</em>.</description> <group-as name="leveraged-authorizations" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Leveraged Authorization Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope and can be used to reference this leveraged authorization elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>leveraged authorization</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="title" as-type="markup-line" min-occurs="1"> <formal-name>title field</formal-name> <description>A human readable name for the leveraged authorization in the context of the system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <define-field name="party-uuid" as-type="uuid" min-occurs="1"> <formal-name>party-uuid field</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to the <code>party</code> that manages the leveraged system.</description> </define-field> <field ref="date-authorized" min-occurs="1"/> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-leveraged-authorization-link-rel-values" target="link/@rel" allow-other="yes"> <enum value="system-security-plan">A reference to the system security plan for the leveraged authorization.</enum> </allowed-values> <matches id="oscal-leveraged-authorization-link-rel-ssp-datatype-uri-reference" target="link[@rel='system-security-plan']/@href[starts-with(.,'#')]" datatype="uri-reference"/> <index-has-key id="oscal-leveraged-authorization-index-back-matter-resource-ssp" name="index-back-matter-resource" target="link[@rel='system-security-plan' and starts-with(@href,'#')]"> <key-field target="@href" pattern="#(.*)"/> </index-has-key> <matches id="oscal-leveraged-authorization-link-rel-ssp-datatype-uri" target="link[@rel='system-security-plan']/@href[not(starts-with(.,'#'))]" datatype="uri"/> </constraint> </define-assembly>
<assembly ref="system-user" min-occurs="0" max-occurs="unbounded"> <use-name>user</use-name> <group-as name="users" in-json="ARRAY"/> </assembly> <assembly ref="system-component" min-occurs="1" max-occurs="unbounded"> <use-name>component</use-name> <group-as name="components" in-json="ARRAY"/> </assembly> <!-- <assembly ref="capability" max-occurs="unbounded"> <group-as name="capabilities" in-json="BY_KEY"/> </assembly> --> <assembly ref="inventory-item" min-occurs="0" max-occurs="unbounded"> <group-as name="inventory-items" in-json="ARRAY"/> <remarks> <p>A set of <code>inventory-item</code> entries that represent the managed inventory instances of the system.</p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <!-- TODO: future: for FedRAMP, have user counts as props: current/internal, current/external, future/internal, future, external --> <index id="oscal-system-implementation-component-leveraged-authorization-uuid-index" name="index-system-implementation-leveraged-authorization-uuid" target="leveraged-authorization"> <key-field target="@uuid"/> </index> <index-has-key id="oscal-system-implementation-component-prop-leveraged-authorization-uuid-index" name="index-system-implementation-leveraged-authorization-uuid" target="component/prop[@name='leveraged-authorization-uuid']"> <key-field target="@value"/> </index-has-key>
<!-- References to components --> <index id="oscal-system-implementation-component-uuid-index" name="index-system-implementation-component-uuid" target="component"> <key-field target="@uuid"/> </index> <index-has-key id="oscal-system-implementation-component-depends-on-link-index" name="index-system-implementation-component-uuid" target="component/link[@rel='depends-on']"> <key-field target="@href"/> </index-has-key>
<!-- References to components of @type="validation" --> <index id="oscal-system-implementation-component-validation-uuid-index" name="index-system-implementation-component-uuid-validation" target="component[@type='validation']"> <key-field target="@uuid"/> </index> <!-- "validated-by" was replaced with "validation" in allowed-values-component_component_link-rel.ent but the change was not propagated at that time. Propagating the change to the index-has-key below, which was missed in the original change, to align with the new rel value of "validation" while also implementing the PR #2107 which has been abandoned by the author. PR #2107 was adding `and starts-with(@href,'#')` to the index-has-key for the "validated-by" rel value which is no longer valid. The proposed change is included below. NOTE: By propagating the old change that renamed "validated-by" with "validation" and implementing the link/@rel=`validation`, the "validation" value is intentionally now used by the component/@type="validation" and link/@rel="validation". This is a feature not a bug. --> <index-has-key id="oscal-system-implementation-validation-index" name="index-system-implementation-component-uuid-validation" target="component/link[@rel='validation' and starts-with(@href,'#')]"> <key-field target="@href"/> </index-has-key>
<!-- References to components of @type="service" --> <index id="oscal-index-system-implementation-component-uuid-service" name="index-system-implementation-component-uuid-service" target="component[@type='service']"> <key-field target="@uuid"/> </index> <index-has-key id="oscal-index-system-implementation-component-uuid-service" name="index-system-implementation-component-uuid-service" target="component/link[@rel='uses-service']"> <key-field target="@href"/> </index-has-key>
<!-- TODO: check that prop names are defined --> <allowed-values id="oscal-component-inventory-item-allows-authenticated-scan-values" target="(component | inventory-item)/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='allows-authenticated-scan']/@value"> <enum value="yes">The component allows an authenticated scan.</enum> <enum value="no">The component does not allow an authenticated scan.</enum> </allowed-values>
<!-- TODO: only allow a single "this-system" component -->
<is-unique id="oscal-unique-ssp-system-implementation-user" target="user"> <key-field target="@uuid"/> <remarks> <p>A given <code>uuid</code> must be assigned only once to a user.</p> </remarks> </is-unique> </constraint> </define-assembly>
<define-assembly name="control-implementation" scope="local"> <formal-name>Control Implementation</formal-name> <description>Describes how the system satisfies a set of controls.</description> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Description</formal-name> <description>A statement describing important things to know about how this set of control satisfaction documentation is approached.</description> </define-field> <assembly ref="set-parameter" max-occurs="unbounded"> <group-as name="set-parameters" in-json="ARRAY"/> </assembly> <assembly ref="implemented-requirement" min-occurs="1" max-occurs="unbounded"> <group-as name="implemented-requirements" in-json="ARRAY"/> </assembly> </model> <constraint> <is-unique id="oscal-unique-ssp-control-implementation-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> <index id="oscal-by-component-export-provided-uuid-index" name="by-component-export-provided-uuid" target="implemented-requirement//by-component/export/provided"> <key-field target="@uuid"/> </index> </constraint> <remarks> <p>Use of <code>set-parameter</code> in this context, sets the parameter for all controls referenced by any <code>implemented-requirement</code> contained in this context. Any <code>set-parameter</code> defined in a child context will override this value. If not overridden by a child, this value applies in the child context.</p> </remarks> </define-assembly> <define-assembly name="implemented-requirement" scope="local"> <formal-name>Control-based Requirement</formal-name> <description>Describes how the system satisfies the requirements of an individual control.</description> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Control Requirement Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this control requirement elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>control requirement</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <flag ref="control-id" required="yes"/> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <assembly ref="set-parameter" max-occurs="unbounded"> <group-as name="set-parameters" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <assembly ref="statement" max-occurs="unbounded"> <group-as name="statements" in-json="ARRAY"/> </assembly> <assembly ref="by-component" min-occurs="0" max-occurs="unbounded"> <group-as name="by-components" in-json="ARRAY"/> </assembly> <!-- TODO: Implement parameters --> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-implemented-requirement-statement-by-component-prop-name-values" target="(.|statement|.//by-component)/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal')]/@name"> <enum value="control-origination">Identifies the source of the implemented control. Any <code>control-origination</code> prop defined in a child context will override the parent value.</enum> </allowed-values> <allowed-values id="oscal-implemented-requirement-statement-by-component-prop-control-origination-values" target="(.|statement|.//by-component)/prop[has-oscal-namespace('http://csrc.nist.gov/ns/oscal') and @name='control-origination']/@value"> <enum value="organization">The control is implemented by the organization owning the system, but is not specific to the system itself.</enum> <enum value="system-specific">The control is implemented specifically to this system.</enum> <enum value="customer-configured">The control is provided by the system, but must be configured by the customer.</enum> <enum value="customer-provided">The control must be implemented by the customer.</enum> <enum value="inherited">This control is inherited from an underlying system.</enum> </allowed-values> <allowed-values id="oscal-implemented-requirement-responsible-role-id-values" target="responsible-role/@role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; </allowed-values> <index-has-key id="oscal-implemented-requirement-index-metadata-role-id" name="index-metadata-role-id" target="responsible-role|statement/responsible-role|.//by-component//responsible-role"> <key-field target="@role-id"/> </index-has-key> <index-has-key id="oscal-implemented-requirement-index-metadata-party-uuid" name="index-metadata-party-uuid" target="responsible-role[party-uuid]|statement/responsible-role[party-uuid]|.//by-component//responsible-role[party-uuid]"> <key-field target="party-uuid"/> </index-has-key> <has-cardinality id="oscal-implemented-requirement-by-component-cardinality" target=".//by-component" min-occurs="1"> <remarks> <p>Since all implementation statements are defined at the by-component level (e.g., type=this-system), there must be at least one by-component.</p> </remarks> </has-cardinality> <is-unique id="oscal-unique-ssp-implemented-requirement-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ssp-implemented-requirement-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ssp-implemented-requirement-statement" target="statement"> <key-field target="@statement-id"/> <remarks> <p>Since <code>statement</code> entries can be referenced using the statement's statement-id, each statement must be referenced only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ssp-implemented-requirement-by-component" target="by-component"> <key-field target="@component-uuid"/> <remarks> <p>Since <code>by-component</code> can reference <code>component</code> entries using the component's uuid, each component must be referenced only once. This ensures that all implementation statements are contained in the same <code>by-component</code> entry.</p> </remarks> </is-unique> </constraint> <remarks> <p>Use of <code>set-parameter</code> in this context, sets the parameter for the referenced control. Any <code>set-parameter</code> defined in a child context will override this value. If not overridden by a child, this value applies in the child context.</p> </remarks> </define-assembly> <define-assembly name="statement" scope="local"> <formal-name>Specific Control Statement</formal-name> <description>Identifies which statements within a control are addressed.</description> <flag ref="statement-id" required="yes"> <remarks> <p>A reference to the specific implemented statement associated with a control.</p> </remarks> </flag> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Control Statement Reference Universally Unique Identifier</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this control statement elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The <em>UUID</em> of the <code>control statement</code> in the source OSCAL instance is sufficient to reference the data item locally or globally (e.g., in an imported OSCAL instance).</description> </define-flag> <model> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <assembly ref="by-component" max-occurs="unbounded"> <group-as name="by-components" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-statement-responsible-role-id-values" target="responsible-role/@role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; </allowed-values> <is-unique id="oscal-unique-ssp-statement-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> <is-unique id="oscal-unique-ssp-implemented-requirement-statement-by-component" target="by-component"> <key-field target="@component-uuid"/> <remarks> <p>Since <code>by-component</code> can reference <code>component</code> entries using the component's uuid, each component must be referenced only once. This ensures that all implementation statements are contained in the same <code>by-component</code> entry.</p> </remarks> </is-unique>
</constraint> </define-assembly> <define-assembly name="by-component"> <!-- QUESTION: Should set-parameter be moved here to allow component-specific parameter settings? or "this-system" for the whole system? --> <formal-name>Component Control Implementation</formal-name> <description>Defines how the referenced component implements a set of controls.</description> <define-flag required="yes" name="component-uuid" as-type="uuid"> <formal-name>Component Universally Unique Identifier Reference</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to the <code>component</code> that is implementing a given control.</description> </define-flag> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>By-Component Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this by-component entry elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>by-component</code> entry can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Description</formal-name> <description>An implementation statement that describes how a control or a control statement is implemented within the referenced system component.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> </assembly> <assembly ref="set-parameter" max-occurs="unbounded"> <group-as name="set-parameters" in-json="ARRAY"/> </assembly> <assembly ref="implementation-status"> <remarks> <p>The <code>implementation-status</code> is used to qualify the <code>status</code> value to indicate the degree to which the control is implemented.</p> </remarks> </assembly> <define-assembly name="export" max-occurs="1"> <formal-name>Export</formal-name> <description>Identifies content intended for external consumption, such as with leveraged organizations.</description> <model> <define-field name="description" as-type="markup-multiline" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Export Description</formal-name> <description>An implementation statement that describes the aspects of the control or control statement implementation that can be available to another system leveraging this system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <define-assembly name="provided" max-occurs="unbounded"> <formal-name>Provided Control Implementation</formal-name> <description>Describes a capability which may be inherited by a leveraging system.</description> <!-- CHANGED: "provided-group" to "provided" --> <group-as name="provided" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Provided Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this provided entry elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>provided</code> entry can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Provided Control Implementation Description</formal-name> <description>An implementation statement that describes the aspects of the control or control statement implementation that can be provided to another system leveraging this system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <assembly ref="responsible-role" min-occurs="0" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-provided-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <define-assembly name="responsibility" max-occurs="unbounded"> <formal-name>Control Implementation Responsibility</formal-name> <description>Describes a control implementation responsibility imposed on a leveraging system.</description> <group-as name="responsibilities" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Responsibility Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this responsibility elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>responsibility</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <flag ref="provided-uuid" required="no" /> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Control Implementation Responsibility Description</formal-name> <description>An implementation statement that describes the aspects of the control or control statement implementation that a leveraging system must implement to satisfy the control provided by a leveraged system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <assembly ref="responsible-role" min-occurs="0" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> <remarks> <p>A role defined at the by-component level takes precedence over the same role defined on the parent implemented-requirement or on the referenced component. </p> </remarks> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-responsibility-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <has-cardinality id="oscal-by-component-export-provided-responsibility-cardinality" target="provided|responsibility" min-occurs="1"/> <index-has-key id="oscal-by-component-export-provided-uuid-index" name="by-component-export-provided-uuid" target="responsibility"> <key-field target="@provided-uuid"/> </index-has-key> </constraint> </define-assembly> <define-assembly name="inherited" max-occurs="unbounded"> <formal-name>Inherited Control Implementation</formal-name> <description>Describes a control implementation inherited by a leveraging system.</description> <!-- CHANGED: "inherited-group" to "inherited" --> <group-as name="inherited" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Inherited Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this inherited entry elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>inherited control implementation</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <flag ref="provided-uuid" required="no" /> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Inherited Control Implementation Description</formal-name> <description>An implementation statement that describes the aspects of a control or control statement implementation that a leveraging system is inheriting from a leveraged system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <assembly ref="responsible-role" min-occurs="0" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> </model> <constraint> <is-unique id="oscal-unique-inherited-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <define-assembly name="satisfied" max-occurs="unbounded"> <formal-name>Satisfied Control Implementation Responsibility</formal-name> <description>Describes how this system satisfies a responsibility imposed by a leveraged system.</description> <!-- CHANGED: "satisfied-group" to "satisfied" --> <group-as name="satisfied" in-json="ARRAY"/> <define-flag name="uuid" as-type="uuid" required="yes"> <formal-name>Satisfied Universally Unique Identifier</formal-name> <!-- Identifier Declaration --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a>, <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#globally-unique">globally unique</a> identifier with <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#cross-instance">cross-instance</a> scope that can be used to reference this satisfied control implementation entry elsewhere in <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#ssp-identifiers">this or other OSCAL instances</a>. The locally defined <em>UUID</em> of the <code>control implementation</code> can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#consistency">per-subject</a>, which means it should be consistently used to identify the same subject across revisions of the document.</description> </define-flag> <flag ref="responsibility-uuid" required="no" /> <model> <define-field name="description" as-type="markup-multiline" min-occurs="1" in-xml="WITH_WRAPPER"> <formal-name>Satisfied Control Implementation Responsibility Description</formal-name> <description>An implementation statement that describes the aspects of a control or control statement implementation that a leveraging system is implementing based on a requirement from a leveraged system.</description> </define-field> <assembly ref="property" max-occurs="unbounded"> <group-as name="props" in-json="ARRAY"/> </assembly> <assembly ref="link" max-occurs="unbounded"> <group-as name="links" in-json="ARRAY"/> <!-- TODO: Model specific link relationships --> </assembly> <assembly ref="responsible-role" min-occurs="0" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <is-unique id="oscal-unique-satisfied-responsible-role" target="responsible-role"> <key-field target="@role-id"/> <remarks> <p>Since <code>responsible-role</code> associates multiple <code>party-uuid</code> entries with a single <code>role-id</code>, each role-id must be referenced only once.</p> </remarks> </is-unique> </constraint> </define-assembly> <assembly ref="responsible-role" max-occurs="unbounded"> <group-as name="responsible-roles" in-json="ARRAY"/> </assembly> <!-- CHANGED: removed "set-parameter" --> <field ref="remarks" in-xml="WITH_WRAPPER"/> </model> <constraint> <allowed-values id="oscal-by-component-link-rel-values" target="link/@rel" allow-other="yes"> <!-- TODO: More work needs to be done around link enforcement constraints and requires Metaschema work on recurse-depth-first() recursive index searching. --> <enum value="imported-from">The hyperlink identifies a URI pointing to the <code>component</code> in a <code>component-definition</code> that originally described the <code>component</code> this component was based on.</enum> <enum value="provided-by">A reference to the UUID of a control or statement <code>by-component</code> object that is used as evidence of implementation.</enum> </allowed-values> <allowed-values id="oscal-by-component-responsible-role-id-values" target=".//responsible-role/@role-id" allow-other="yes"> &allowed-values-responsible-roles-operations; &allowed-values-responsible-roles-component-production; </allowed-values> <is-unique id="oscal-unique-ssp-by-component-set-parameter" target="set-parameter"> <key-field target="@param-id"/> <remarks> <p>Since multiple <code>set-parameter</code> entries can be provided, each parameter must be set only once.</p> </remarks> </is-unique> <index-has-key id="oscal-by-component-uuid-index" name="by-component-uuid" target="link[@rel='provided-by']"> <key-field target="@href" pattern="#(.*)" /> </index-has-key> </constraint> <remarks> <p>Use of <code>set-parameter</code> in this context, sets the parameter for the control referenced in the containing <code>implemented-requirement</code> applied to the referenced component. If the <code>by-component</code> is used as a child of a <code>statement</code>, then the parameter value also applies only in the context of the referenced statement. If the same parameter is also set in the <code>control-implementation</code> or a specific <code>implemented-requirement</code>, then this <code>by-component/set-parameter</code> value will override the other value(s) in the context of the referenced component, control, and statement (if parent).</p> </remarks> </define-assembly>
<define-flag name="provided-uuid" as-type="uuid" scope="local"> <formal-name>Provided UUID</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to an inherited control implementation that a leveraging system is inheriting from a leveraged system.</description> </define-flag>
<define-flag name="responsibility-uuid" as-type="uuid" scope="local"> <formal-name>Responsibility UUID</formal-name> <!-- Identifier Reference --> <description>A <a href="https://pages.nist.gov/OSCAL/concepts/identifier-use/#machine-oriented">machine-oriented</a> identifier reference to a control implementation that satisfies a responsibility imposed by a leveraged system.</description> </define-flag> </METASCHEMA># OSCAL Metaschema
An OSCAL Metaschema defines the the information structures that define an OSCAL model in a format-neutral form. Documentation about the meaning (semantics) and use of a given metaschema structure is provided on the Metaschema [website].
OSCAL Metaschemas are used to generate other OSCAL artifacts based on the metaschema description. These artifacts include:
- XML and JSON schemas, or *data models*, which are derived from the Metaschema modules and expressed as XSD and JSON Schema; - Conversion scripts that can convert OSCAL content between the XML and JSON OSCAL formats, ensuring the resulting content is schema valid; - XML and JSON [model documentation](https://pages.nist.gov/OSCAL/docs/schemas/) for use on the [OSCAL website](https://pages.nist.gov/OSCAL).
Use of Metaschema modules in OSCAL allows us to maintain seamless and consistent support for multiple OSCAL model formats, including XML and JSON. More information is at the [Metaschema Information Modeling Framework documentation site](https://pages.nist.gov/metaschema/).type: map mapping: standards: type: map mapping: =: type: map mapping: =: type: any name: type: strtype: map mapping: name: type: str required: true key: type: str system: type: str required: false schema_version: type: float required: true documentation_complete: type: bool references: type: seq sequence: - type: map mapping: name: type: str required: true path: type: str type: type: str enum: - URL - Image required: false verifications: type: seq sequence: - type: map mapping: key: type: str required: true name: type: str required: true path: type: str type: type: str enum: - URL - Image required: false description: type: str test_passed: type: bool last_run: type: any satisfies: type: seq sequence: - type: map mapping: standard_key: type: text required: true control_key: type: text required: true narrative: type: str required: true parameters: type: seq sequence: - type: map mapping: key: type: str required: true text: type: str required: true implementation_status: type: str enum: - partial - complete - planned - none covered_by: type: seq sequence: - type: map mapping: system_key: type: str component_key: type: str verification_key: type: str required: truetype: map mapping: name: type: str required: true key: type: str system: type: str required: false schema_version: type: str required: true documentation_complete: type: bool responsible_role: type: str references: type: seq sequence: - type: map mapping: name: type: str required: true path: type: str type: type: str enum: - URL - Image required: false verifications: type: seq sequence: - type: map mapping: key: type: str required: true name: type: str required: true path: type: str type: type: str enum: - URL - Image required: false descrip